(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-711":{scenario:{company:"Thanh Mai General Hospital",supervisor:{name:"Ninh Thị Bảo Trâm",role:{vi:"Trưởng khoa Dược",en:"Head of Pharmacy"}},ref_code:"DL-3308",title:{vi:"Đúng thuốc. Đúng liều. An toàn người bệnh.",en:"Right drug. Right dose. Patient safety first."},brief:{vi:"Đây là tình huống đào tạo. Bạn là dược sĩ lâm sàng khoa Nội, duyệt đơn DL-3308 của người bệnh nữ 76 tuổi, nặng 72 kg, creatinin huyết thanh 0,8 mg/dL, viêm phổi cộng đồng. Đơn mới kê clarithromycin 500 mg x 2 lần/ngày trong khi người bệnh đang dùng simvastatin 40 mg buổi tối. Đối chiếu phiếu can thiệp dược nháp với tài liệu gốc, sửa mức độ tương tác và độ thanh thải creatinin, rồi lập báo cáo đề xuất cho bác sĩ.",en:"This is a training scenario. As the internal medicine clinical pharmacist you review order DL-3308 for a 76-year-old woman, 72 kg, serum creatinine 0.8 mg/dL, with community-acquired pneumonia. The new order adds clarithromycin 500 mg twice daily while she takes simvastatin 40 mg every evening. Compare the draft intervention form with the source documents, correct the interaction severity and the creatinine clearance, then write a recommendation for the physician."},reference_title:{vi:"Dữ liệu tương tác & hồ sơ cận lâm sàng",en:"Interaction database & laboratory record"},fields:[{id:"DDI_LEVEL",label:{vi:"Mức độ tương tác thuốc",en:"Drug interaction severity"},initial:"MODERATE",expected:"CONTRAINDICATED",choices:["MINOR","MODERATE","CONTRAINDICATED"],reference:"Cơ sở dữ liệu tương tác thuốc",ref_value:{vi:"Clarithromycin (ức chế mạnh CYP3A4) + simvastatin: chống chỉ định phối hợp (CONTRAINDICATED), nguy cơ tiêu cơ vân",en:"Clarithromycin (strong CYP3A4 inhibitor) + simvastatin: CONTRAINDICATED combination, rhabdomyolysis risk"},hint:{vi:"Simvastatin chuyển hóa chủ yếu qua CYP3A4; chất ức chế mạnh làm nồng độ statin tăng nhiều lần.",en:"Simvastatin is mainly cleared by CYP3A4; a strong inhibitor raises statin levels several-fold."}},{id:"CRCL",label:{vi:"Độ thanh thải creatinin (mL/phút)",en:"Creatinine clearance (mL/min)"},initial:"80",expected:"68",reference:"Phiếu xét nghiệm & sinh hiệu",ref_value:{vi:"Nữ, 76 tuổi, cân nặng thực 72 kg, creatinin huyết thanh 0,8 mg/dL",en:"Female, 76 years, actual body weight 72 kg, serum creatinine 0.8 mg/dL"},hint:{vi:"Công thức Cockcroft-Gault có hệ số hiệu chỉnh riêng cho người bệnh nữ.",en:"The Cockcroft-Gault formula has a correction factor for female patients."}}],sop32:{vi:"Cockcroft-Gault: CrCl (mL/phút) = (140 - tuổi) x cân nặng (kg) / (72 x creatinin huyết thanh mg/dL); nhân thêm 0,85 nếu là nữ. Ghi kết quả vào phiếu can thiệp trước khi đề xuất liều.",en:"Cockcroft-Gault: CrCl (mL/min) = (140 - age) x weight (kg) / (72 x serum creatinine mg/dL); multiply by 0.85 for women. Record it on the intervention form before recommending a dose."},context:{label:"HIS / DL-3308",metrics:[{label:{vi:"Tuổi (nữ)",en:"Age (female)"},value:"76"},{label:{vi:"Cân nặng",en:"Weight"},value:"72 kg"},{label:{vi:"Creatinin huyết thanh",en:"Serum creatinine"},value:"0.8 mg/dL"},{label:{vi:"Thuốc đang dùng",en:"Current statin"},value:"simvastatin 40 mg"}]},crisis:{vi:"Bác sĩ điều trị nhắn: “Cứ cấp phát nguyên đơn, bà ấy dùng simvastatin lâu rồi không sao. Đừng ghi phiếu can thiệp kẻo khoa bị trừ điểm chất lượng, có gì tôi chịu.”",en:"The attending physician messages you: “Dispense the order as written, she has taken simvastatin for years without problems. Do not file an intervention form or the ward loses quality points. I will take responsibility.”"},options:{safe:{vi:"Không cấp phát phối hợp chống chỉ định, trao đổi trực tiếp với bác sĩ, đề xuất tạm ngừng simvastatin trong đợt kháng sinh hoặc đổi kháng sinh phù hợp, ghi phiếu can thiệp và báo Trưởng khoa Dược.",en:"Do not dispense the contraindicated pair, talk to the physician directly, propose pausing simvastatin during the antibiotic course or a suitable alternative, file the intervention and inform the Head of Pharmacy."},shortcut:{vi:"Cấp phát nguyên đơn theo lời bác sĩ và không ghi phiếu can thiệp.",en:"Dispense the order as the physician says and skip the intervention form."},wait:{vi:"Giữ đơn lại không xử lý và chờ bác sĩ tự phát hiện tương tác.",en:"Hold the order without action and wait for the physician to notice the interaction."}},questions:{vi:["Vì sao phối hợp clarithromycin với simvastatin được xếp CONTRAINDICATED và CrCl 68 mL/phút có ý nghĩa gì với người bệnh này?","Bạn trao đổi với bác sĩ và ghi nhận can thiệp thế nào để vừa an toàn người bệnh vừa đúng quy định dược lâm sàng?"],en:["Why is clarithromycin with simvastatin rated CONTRAINDICATED, and what does a CrCl of 68 mL/min mean for this patient?","How do you discuss it with the physician and document the intervention so the patient is safe and pharmacy rules are met?"]},hints:{vi:["Tra cơ chế tương tác qua enzym chuyển hóa và đối chiếu mức độ trong cơ sở dữ liệu gốc.","Kiểm tra giới tính người bệnh trước khi áp dụng công thức Cockcroft-Gault ở SOP mục 3.2.","Đọc lại SOP mục 4.2: tương tác nguy hiểm phải được can thiệp, ghi nhận và báo cáo, không bỏ qua theo lời nhắn."],en:["Look up the metabolic mechanism and match the severity in the source database.","Check the patient's sex before applying Cockcroft-Gault in SOP 3.2.","Re-read SOP 4.2: a dangerous interaction must be acted on, documented and escalated, never ignored on request."]}},learning:{summary:{vi:"Dược sĩ lâm sàng và dược sĩ cộng đồng bảo đảm người bệnh dùng thuốc an toàn, hợp lý và hiệu quả. Tại bệnh viện, dược sĩ duyệt đơn, phát hiện tương tác, hiệu chỉnh liều theo chức năng gan thận, theo dõi phản ứng có hại và tham gia hội chẩn. Tại nhà thuốc, dược sĩ tư vấn, bán thuốc theo đơn đúng quy định và hướng dẫn người bệnh tuân thủ điều trị.",en:"Clinical and community pharmacists make sure patients use medicines safely, rationally and effectively. In hospital they review orders, detect interactions, adjust doses to renal and hepatic function, monitor adverse reactions and join ward rounds. In community pharmacies they counsel patients, dispense prescription-only medicines lawfully and support adherence."},responsibilities:{vi:["Duyệt đơn thuốc: chỉ định, liều, đường dùng, tương tác, chống chỉ định trước khi cấp phát.","Hiệu chỉnh liều theo chức năng thận, gan, tuổi và cân nặng của người bệnh.","Theo dõi, ghi nhận và báo cáo phản ứng có hại của thuốc (ADR) theo quy định.","Tư vấn cho bác sĩ, điều dưỡng và người bệnh về cách dùng, bảo quản và tuân thủ điều trị.","Tham gia Hội đồng Thuốc và điều trị, xây dựng danh mục và hướng dẫn sử dụng kháng sinh."],en:["Review orders for indication, dose, route, interactions and contraindications before dispensing.","Adjust doses for renal and hepatic function, age and body weight.","Monitor, record and report adverse drug reactions (ADR) as required.","Advise physicians, nurses and patients on use, storage and adherence.","Serve on the Drug and Therapeutics Committee and help build the formulary and antibiotic guidance."]},competencies:[{name:{vi:"Dược lý lâm sàng",en:"Clinical pharmacology"},desc:{vi:"Nắm dược động học, dược lực học và cơ chế tương tác để đánh giá nguy cơ trên từng người bệnh.",en:"Apply pharmacokinetics, pharmacodynamics and interaction mechanisms to judge risk for each patient."}},{name:{vi:"Tính toán liều",en:"Dose calculation"},desc:{vi:"Tính CrCl, liều theo cân nặng, diện tích da và hiệu chỉnh liều chính xác.",en:"Calculate CrCl, weight- and BSA-based doses and dose adjustments accurately."}},{name:{vi:"Tra cứu bằng chứng",en:"Evidence retrieval"},desc:{vi:"Dùng dược thư, tờ hướng dẫn sử dụng và cơ sở dữ liệu tương tác tin cậy, ghi rõ nguồn.",en:"Use formularies, product labels and reliable interaction databases and cite the source."}},{name:{vi:"Giao tiếp chuyên môn",en:"Professional communication"},desc:{vi:"Đề xuất can thiệp ngắn gọn, có căn cứ và phương án thay thế để bác sĩ dễ chấp nhận.",en:"Make concise, evidence-based recommendations with alternatives that physicians can accept."}},{name:{vi:"Đạo đức hành nghề",en:"Professional ethics"},desc:{vi:"Đặt an toàn người bệnh lên trước, không bán thuốc kê đơn khi không có đơn, không bỏ qua cảnh báo.",en:"Put patient safety first, never sell prescription-only drugs without a prescription or ignore alerts."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 và các văn bản hướng dẫn hiện hành.","Nghị định 131/2020/NĐ-CP về tổ chức, hoạt động dược lâm sàng của cơ sở khám bệnh, chữa bệnh.","Thông tư 02/2018/TT-BYT về Thực hành tốt cơ sở bán lẻ thuốc (GPP).","Công thức Cockcroft-Gault và nguyên tắc hiệu chỉnh liều theo chức năng thận.","Tương tác dược động học qua hệ enzym CYP450, đặc biệt CYP3A4 và CYP2C9.","Tiêu chí Beers về thuốc có nguy cơ không phù hợp ở người cao tuổi."],en:["Pharmacy Law No. 105/2016/QH13 and its current implementing documents.","Decree 131/2020/ND-CP on clinical pharmacy organization and practice in healthcare facilities.","Circular 02/2018/TT-BYT on Good Pharmacy Practice for retail outlets (GPP).","The Cockcroft-Gault formula and renal dose adjustment principles.","Pharmacokinetic interactions via CYP450 enzymes, especially CYP3A4 and CYP2C9.","The Beers Criteria for potentially inappropriate medications in older adults."]},tools:["Phần mềm duyệt đơn trên HIS","Cơ sở dữ liệu tương tác thuốc","Dược thư Quốc gia Việt Nam","Công cụ tính liều theo chức năng thận","Phần mềm quản lý nhà thuốc GPP"],kpis:{vi:["Tỷ lệ đơn nội trú được duyệt trước khi cấp phát.","Tỷ lệ can thiệp dược được bác sĩ chấp nhận.","Số ADR được phát hiện và báo cáo đúng hạn.","Số sai sót thuốc đến người bệnh do bỏ sót tương tác (mục tiêu bằng 0)."],en:["Share of inpatient orders reviewed before dispensing.","Share of pharmacist interventions accepted by physicians.","ADRs detected and reported on time.","Medication errors reaching patients from missed interactions (target zero)."]},day:[{time:"07:30",vi:"Duyệt đơn mới trên HIS, lọc cảnh báo tương tác và liều cao.",en:"Review new orders in the HIS and screen interaction and high-dose alerts."},{time:"09:00",vi:"Đi buồng cùng bác sĩ, xem xét nghiệm chức năng thận, gan của người bệnh nặng.",en:"Join ward rounds and check renal and liver results of high-risk patients."},{time:"11:00",vi:"Ghi phiếu can thiệp dược, đề xuất hiệu chỉnh liều hoặc thuốc thay thế.",en:"File intervention forms proposing dose changes or alternatives."},{time:"14:00",vi:"Tư vấn người bệnh ra viện về cách dùng thuốc và dấu hiệu cần tái khám.",en:"Counsel discharged patients on how to take medicines and warning signs."},{time:"16:00",vi:"Tổng hợp ADR, cập nhật bản tin thông tin thuốc cho các khoa.",en:"Compile ADR reports and update the drug information bulletin for wards."}],mistakes:{vi:["Quên hệ số 0,85 cho người bệnh nữ khi tính Cockcroft-Gault.","Chỉ xem cảnh báo của phần mềm mà không đánh giá cơ chế và bối cảnh người bệnh.","Cấp phát theo lời nhắn miệng dù đơn có phối hợp chống chỉ định."],en:["Forgetting the 0.85 factor for women in Cockcroft-Gault.","Relying on software alerts without judging the mechanism and the patient's context.","Dispensing on a verbal request despite a contraindicated combination."]},career:[{vi:"Dược sĩ nhà thuốc / dược sĩ cấp phát",en:"Community / dispensing pharmacist"},{vi:"Dược sĩ lâm sàng",en:"Clinical pharmacist"},{vi:"Dược sĩ lâm sàng chuyên khoa / Trưởng bộ phận dược lâm sàng",en:"Specialist clinical pharmacist / Clinical pharmacy lead"},{vi:"Trưởng khoa Dược bệnh viện",en:"Hospital Head of Pharmacy"}],glossary:[{term:"CrCl",vi:"Độ thanh thải creatinin, ước tính chức năng lọc của thận để hiệu chỉnh liều thuốc.",en:"Creatinine clearance, an estimate of renal filtration used to adjust drug doses."},{term:"ADR",vi:"Phản ứng có hại của thuốc: đáp ứng độc hại, không mong muốn ở liều thông thường.",en:"Adverse drug reaction: a harmful, unintended response at normal doses."},{term:"CYP3A4",vi:"Enzym gan chuyển hóa nhiều thuốc; bị ức chế bởi clarithromycin, ketoconazol, nước bưởi chùm.",en:"Liver enzyme that metabolizes many drugs; inhibited by clarithromycin, ketoconazole and grapefruit juice."},{term:"Can thiệp dược",vi:"Đề xuất của dược sĩ nhằm thay đổi điều trị để giải quyết vấn đề liên quan đến thuốc.",en:"A pharmacist recommendation that changes therapy to resolve a drug-related problem."},{term:"GPP",vi:"Thực hành tốt cơ sở bán lẻ thuốc: chuẩn về nhân sự, cơ sở, quy trình và tư vấn tại nhà thuốc.",en:"Good Pharmacy Practice: standards for staff, premises, procedures and counselling in pharmacies."}],quiz:[{q:{vi:"Nam 68 tuổi, 60 kg, creatinin huyết thanh 1,5 mg/dL. CrCl theo Cockcroft-Gault là bao nhiêu?",en:"A 68-year-old man, 60 kg, serum creatinine 1.5 mg/dL. What is his Cockcroft-Gault CrCl?"},options:{vi:["34 mL/phút","48 mL/phút","40 mL/phút","60 mL/phút"],en:["34 mL/min","48 mL/min","40 mL/min","60 mL/min"]},answer:2,explain:{vi:"(140 - 68) x 60 / (72 x 1,5) = 4320 / 108 = 40 mL/phút; nam không nhân 0,85.",en:"(140 - 68) x 60 / (72 x 1.5) = 4320 / 108 = 40 mL/min; no 0.85 factor for men."}},{q:{vi:"Xử trí hợp lý khi người bệnh dùng simvastatin cần đợt clarithromycin là gì?",en:"What is a sound approach when a patient on simvastatin needs a course of clarithromycin?"},options:{vi:["Tạm ngừng simvastatin trong đợt kháng sinh hoặc chọn kháng sinh khác","Tăng liều simvastatin","Dùng cả hai và không theo dõi","Ngừng hẳn statin vĩnh viễn"],en:["Pause simvastatin during the course or choose another antibiotic","Increase the simvastatin dose","Give both without monitoring","Stop the statin permanently"]},answer:0,explain:{vi:"Phối hợp chống chỉ định do nguy cơ tiêu cơ vân; tạm ngừng statin hoặc đổi kháng sinh là phương án an toàn.",en:"The pair is contraindicated due to rhabdomyolysis risk; pausing the statin or switching antibiotic is safe."}},{q:{vi:"Khách đến nhà thuốc xin mua kháng sinh không có đơn vì “lần trước uống khỏi”. Bạn làm gì?",en:"A customer asks to buy an antibiotic without a prescription because “it worked last time”. What do you do?"},options:{vi:["Bán số lượng ít để khách đỡ phiền","Bán loại kháng sinh rẻ hơn","Bán nếu khách cam kết đi khám sau","Từ chối bán, tư vấn triệu chứng và hướng dẫn đi khám"],en:["Sell a small amount to please them","Sell a cheaper antibiotic","Sell if they promise to see a doctor later","Decline, counsel on symptoms and refer them to a doctor"]},answer:3,explain:{vi:"Kháng sinh là thuốc kê đơn; bán không đơn vi phạm quy định và thúc đẩy kháng kháng sinh.",en:"Antibiotics are prescription-only; selling without a prescription is unlawful and drives resistance."}},{q:{vi:"Tiêu chí Beers được dùng để làm gì?",en:"What are the Beers Criteria used for?"},options:{vi:["Tính liều cho trẻ em","Nhận diện thuốc có nguy cơ không phù hợp ở người cao tuổi","Phân loại thuốc gây nghiện","Đánh giá giá thuốc đấu thầu"],en:["Pediatric dosing","Identifying potentially inappropriate drugs in older adults","Classifying narcotics","Assessing tender prices"]},answer:1,explain:{vi:"Beers liệt kê thuốc nên tránh hoặc thận trọng ở người cao tuổi để giảm biến cố bất lợi.",en:"Beers lists drugs to avoid or use with caution in older adults to reduce adverse events."}}]}},"KK-712":{scenario:{company:"Luc Bao Pharmaceuticals",supervisor:{name:"Hoàng Gia Linh",role:{vi:"Giám đốc Đăng ký thuốc",en:"Regulatory Affairs Director"}},ref_code:"VAR-2451",title:{vi:"Đúng phân loại. Đúng dữ liệu. Đúng hạn dùng.",en:"Right category. Real data. Justified shelf life."},brief:{vi:"Đây là tình huống đào tạo. Bạn chuẩn bị hồ sơ thay đổi VAR-2451 cho viên nén bao phim Lodivan 10 mg (sản phẩm mô phỏng) khi chuyển sản xuất thành phẩm sang nhà máy mới. Dữ liệu độ ổn định tại nhà máy mới: dài hạn 30°C/75%RH đủ 21 tháng, lão hóa cấp tốc 40°C/75%RH đủ 6 tháng, đều không có thay đổi đáng kể. Đối chiếu tờ khai thay đổi nháp với phiếu đánh giá đã duyệt, sửa phân loại thay đổi và hạn dùng đề xuất (tháng), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are preparing variation file VAR-2451 for Lodivan 10 mg film-coated tablets (a simulated product) after moving finished-product manufacturing to a new plant. Stability data from the new plant: long-term 30°C/75%RH for 21 months and accelerated 40°C/75%RH for 6 months, both with no significant change. Compare the draft variation form with the approved assessment, correct the variation category and the proposed shelf life (months), then write an evidence-based report."},reference_title:{vi:"Phiếu đánh giá thay đổi & tóm tắt độ ổn định",en:"Variation assessment & stability summary"},fields:[{id:"VAR_CLASS",label:{vi:"Phân loại thay đổi",en:"Variation category"},initial:"MiV-N",expected:"MaV",choices:["MaV","MiV-PA","MiV-N"],reference:"Phiếu đánh giá thay đổi",ref_value:{vi:"Thay đổi hoặc bổ sung cơ sở sản xuất thành phẩm: thay đổi lớn (MaV), phải được phê duyệt trước khi áp dụng",en:"Change or addition of a finished-product manufacturing site: major variation (MaV), prior approval required"},hint:{vi:"Đổi nơi sản xuất thành phẩm ảnh hưởng trực tiếp chất lượng, không phải thay đổi hành chính chỉ cần thông báo.",en:"Moving finished-product manufacturing directly affects quality; it is not an administrative notification."}},{id:"SHELF_LIFE",label:{vi:"Hạn dùng đề xuất (tháng)",en:"Proposed shelf life (months)"},initial:"36",expected:"33",reference:"Tóm tắt dữ liệu độ ổn định",ref_value:{vi:"Dài hạn 30°C/75%RH: 21 tháng, không thay đổi đáng kể; cấp tốc: 6 tháng, không thay đổi đáng kể",en:"Long-term 30°C/75%RH: 21 months, no significant change; accelerated: 6 months, no significant change"},hint:{vi:"Ngoại suy hạn dùng bị giới hạn bởi hai điều kiện, lấy giá trị nhỏ hơn.",en:"Shelf-life extrapolation is capped by two limits; take the smaller one."}}],sop32:{vi:"Theo nguyên tắc ICH Q1E áp dụng trong bài: khi dữ liệu ít thay đổi, hạn dùng đề xuất tối đa = giá trị nhỏ hơn giữa (2 x thời gian dữ liệu dài hạn) và (thời gian dữ liệu dài hạn + 12 tháng).",en:"Per the ICH Q1E principle used here: when data show little change, the maximum proposed shelf life = the smaller of (2 x long-term data period) and (long-term data period + 12 months)."},context:{label:"RIM / VAR-2451",metrics:[{label:{vi:"Dữ liệu dài hạn (tháng)",en:"Long-term data (months)"},value:"21"},{label:{vi:"Dữ liệu cấp tốc (tháng)",en:"Accelerated data (months)"},value:"6"},{label:{vi:"Vùng khí hậu",en:"Climatic zone"},value:"IVb"},{label:{vi:"Hạn dùng bao bì cũ (tháng)",en:"Old pack shelf life (months)"},value:"36"}]},crisis:{vi:"Giám đốc kinh doanh nhắn: “Ghi 36 tháng cho khớp 200.000 hộp đã in sẵn. Trong báo cáo độ ổn định cứ ghi là đã có dữ liệu 24 tháng, nộp trước rồi bổ sung sau, chẳng ai soát kỹ đâu.”",en:"The sales director messages you: “Put 36 months to match the 200,000 cartons already printed. In the stability report just say we have 24 months of data, file now and add data later, nobody checks closely.”"},options:{safe:{vi:"Từ chối khai sai dữ liệu, nộp hạn dùng 30 tháng kèm cam kết tiếp tục theo dõi độ ổn định, báo Giám đốc Đăng ký và QA, xử lý bao bì đã in qua quy trình kiểm soát thay đổi.",en:"Refuse to misstate data, file a 30-month shelf life with an ongoing stability commitment, inform the RA Director and QA, and handle printed cartons through change control."},shortcut:{vi:"Ghi 36 tháng và dữ liệu 24 tháng để kịp nộp, sau này bổ sung số liệu thật.",en:"Enter 36 months and 24 months of data to file on time and add the real data later."},wait:{vi:"Dừng soạn hồ sơ và chờ kinh doanh với nhà máy tự thống nhất hạn dùng.",en:"Stop drafting and wait for Sales and the plant to agree on the shelf life."}},questions:{vi:["Vì sao thay đổi này thuộc MaV và hạn dùng tối đa chỉ là 30 tháng? Dẫn chứng từ phiếu đánh giá và dữ liệu độ ổn định.","Bạn xử lý số bao bì đã in hạn dùng 36 tháng và lộ trình xin kéo dài hạn dùng thế nào cho hợp lệ?"],en:["Why is this an MaV and why is the shelf life capped at 30 months? Cite the assessment and the stability data.","How do you handle cartons printed with 36 months and plan a lawful shelf-life extension?"]},hints:{vi:["Xác định thay đổi tác động đến chất lượng thành phẩm hay chỉ là thông tin hành chính.","Tính cả hai giới hạn ngoại suy ở SOP mục 3.2 rồi chọn giá trị nhỏ hơn.","Đọc lại SOP mục 4.2: không bao giờ khai dữ liệu chưa có; mọi áp lực phải báo cáo người có thẩm quyền."],en:["Decide whether the change affects finished-product quality or is only administrative.","Compute both extrapolation limits in SOP 3.2 and take the smaller one.","Re-read SOP 4.2: never declare data you do not have; escalate any pressure to the responsible person."]}},learning:{summary:{vi:"Chuyên viên đăng ký thuốc và trang thiết bị y tế (RA) chuẩn bị, nộp và theo dõi hồ sơ cấp phép lưu hành, gia hạn và thay đổi sản phẩm với cơ quan quản lý. Người làm nghề hiểu cấu trúc hồ sơ ACTD/CTD, yêu cầu chất lượng, an toàn, hiệu quả, phân loại thay đổi và phân loại rủi ro thiết bị. Giá trị cốt lõi là đưa sản phẩm ra thị trường đúng hạn mà vẫn trung thực tuyệt đối về dữ liệu.",en:"A regulatory affairs (RA) specialist for medicines and medical devices prepares, submits and tracks marketing authorizations, renewals and variations with the regulator. The role requires knowing the ACTD/CTD dossier structure, quality, safety and efficacy requirements, variation categories and device risk classes. Its core value is bringing products to market on time with absolute data integrity."},responsibilities:{vi:["Lập hồ sơ đăng ký lưu hành mới, gia hạn và thay đổi theo định dạng ACTD/CTD.","Phân loại thay đổi, xác định tài liệu cần nộp và thời điểm được phép áp dụng.","Rà soát dữ liệu chất lượng, độ ổn định, tương đương sinh học và nhãn, tờ hướng dẫn sử dụng.","Phân loại mức độ rủi ro trang thiết bị y tế và chuẩn bị hồ sơ công bố hoặc đăng ký lưu hành.","Theo dõi công văn, trả lời yêu cầu bổ sung và quản lý hiệu lực giấy phép trên hệ thống."],en:["Compile new, renewal and variation dossiers in ACTD/CTD format.","Classify variations, define required documents and when the change may be implemented.","Review quality, stability, bioequivalence data and labels and package inserts.","Classify medical device risk and prepare declaration or registration files.","Track official letters, answer deficiency requests and manage licence validity in the system."]},competencies:[{name:{vi:"Pháp quy dược & thiết bị",en:"Drug & device regulation"},desc:{vi:"Nắm quy định đăng ký thuốc, trang thiết bị y tế và hướng dẫn ASEAN, ICH liên quan.",en:"Know drug and device registration rules and the related ASEAN and ICH guidance."}},{name:{vi:"Biên soạn hồ sơ kỹ thuật",en:"Technical dossier writing"},desc:{vi:"Tổ chức hồ sơ ACTD/CTD mạch lạc, nhất quán giữa các phần chất lượng, lâm sàng và nhãn.",en:"Build coherent ACTD/CTD dossiers that stay consistent across quality, clinical and labelling parts."}},{name:{vi:"Đánh giá dữ liệu khoa học",en:"Scientific data review"},desc:{vi:"Đọc hiểu dữ liệu độ ổn định, thẩm định quy trình và tiêu chuẩn chất lượng để phát hiện lỗ hổng.",en:"Read stability, validation and specification data to spot gaps."}},{name:{vi:"Quản lý tiến độ",en:"Timeline management"},desc:{vi:"Lập kế hoạch nộp, theo dõi thời hạn trả lời và hiệu lực giấy phép, tránh gián đoạn cung ứng.",en:"Plan submissions, track response deadlines and licence expiry to avoid supply gaps."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Chỉ khai dữ liệu có thật, đầy đủ và truy xuất được; từ chối mọi yêu cầu chỉnh sửa sai sự thật.",en:"Declare only real, complete, traceable data and refuse any request to misstate it."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 về đăng ký lưu hành thuốc và nguyên liệu làm thuốc.","Thông tư 08/2022/TT-BYT quy định việc đăng ký lưu hành thuốc, nguyên liệu làm thuốc.","Nghị định 98/2021/NĐ-CP về quản lý trang thiết bị y tế, phân loại rủi ro A, B, C, D.","Hồ sơ kỹ thuật chung ASEAN (ACTD) và định dạng CTD của ICH.","ICH Q1A(R2), Q1E về nghiên cứu độ ổn định; điều kiện vùng khí hậu IVb 30°C/75%RH.","Hướng dẫn thay đổi ASEAN: MaV, MiV-PA, MiV-N."],en:["Pharmacy Law No. 105/2016/QH13 on marketing authorization of medicines and starting materials.","Circular 08/2022/TT-BYT on registration of medicines and pharmaceutical starting materials.","Decree 98/2021/ND-CP on medical device management with risk classes A, B, C and D.","The ASEAN Common Technical Dossier (ACTD) and the ICH CTD format.","ICH Q1A(R2) and Q1E on stability testing; climatic zone IVb at 30°C/75%RH.","The ASEAN variation guideline: MaV, MiV-PA and MiV-N."]},tools:["Cổng dịch vụ công trực tuyến ngành y tế","Hệ thống quản lý thông tin đăng ký (RIM)","Phần mềm biên soạn hồ sơ CTD/ACTD","Phần mềm phân tích dữ liệu độ ổn định","Microsoft Excel"],kpis:{vi:["Tỷ lệ hồ sơ được chấp thuận không phải bổ sung lần hai.","Số sản phẩm gián đoạn lưu hành do hết hạn giấy phép (mục tiêu bằng 0).","Thời gian trung bình trả lời công văn yêu cầu bổ sung.","Số phát hiện về tính toàn vẹn dữ liệu khi thanh tra, đánh giá (mục tiêu bằng 0)."],en:["Share of dossiers approved without a second deficiency round.","Products disrupted by expired licences (target zero).","Average time to answer deficiency letters.","Data integrity findings in inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Kiểm tra công văn mới, hạn trả lời và lịch hết hiệu lực giấy phép.",en:"Check new official letters, response deadlines and licence expiry dates."},{time:"09:30",vi:"Họp với QA và nhà máy về kế hoạch thay đổi, phân loại và tài liệu cần nộp.",en:"Meet QA and the plant on planned changes, their category and required documents."},{time:"11:00",vi:"Rà soát báo cáo độ ổn định, tính hạn dùng đề xuất có căn cứ.",en:"Review stability reports and justify the proposed shelf life."},{time:"14:00",vi:"Biên soạn, kiểm tra chéo hồ sơ ACTD và bản dịch nhãn, tờ hướng dẫn sử dụng.",en:"Compile and cross-check the ACTD file and translated labels and inserts."},{time:"16:30",vi:"Nộp hồ sơ trực tuyến, cập nhật hệ thống RIM và báo cáo tiến độ.",en:"Submit online, update the RIM system and report progress."}],mistakes:{vi:["Xếp thay đổi cơ sở sản xuất vào loại chỉ cần thông báo và áp dụng trước khi được duyệt.","Nhân đôi thời gian dữ liệu dài hạn mà quên giới hạn cộng tối đa 12 tháng.","Khai dữ liệu độ ổn định chưa có hoặc bỏ bớt kết quả không đạt để kịp hạn nộp."],en:["Treating a manufacturing site change as a notification and implementing it before approval.","Doubling the long-term period while forgetting the 12-month cap.","Declaring stability data that does not exist or dropping failing results to meet a deadline."]},career:[{vi:"Trợ lý đăng ký thuốc",en:"Regulatory affairs assistant"},{vi:"Chuyên viên đăng ký thuốc & trang thiết bị y tế",en:"Regulatory affairs specialist"},{vi:"Trưởng nhóm đăng ký / Chuyên gia pháp quy cấp cao",en:"RA team lead / Senior regulatory expert"},{vi:"Giám đốc Đăng ký & Pháp quy khu vực",en:"Regional Head of Regulatory Affairs"}],glossary:[{term:"ACTD",vi:"Hồ sơ kỹ thuật chung ASEAN gồm các phần hành chính, chất lượng, tiền lâm sàng và lâm sàng.",en:"ASEAN Common Technical Dossier with administrative, quality, nonclinical and clinical parts."},{term:"MaV",vi:"Thay đổi lớn: ảnh hưởng đáng kể đến chất lượng, an toàn, hiệu quả, cần phê duyệt trước.",en:"Major variation with a significant impact on quality, safety or efficacy; prior approval needed."},{term:"MiV-N",vi:"Thay đổi nhỏ chỉ cần thông báo, thường là thông tin hành chính không ảnh hưởng chất lượng.",en:"Minor variation by notification, usually administrative with no quality impact."},{term:"Shelf life",vi:"Hạn dùng: khoảng thời gian thuốc giữ nguyên tiêu chuẩn chất lượng trong điều kiện bảo quản ghi trên nhãn.",en:"The period a medicine stays within specification under the labelled storage conditions."},{term:"Zone IVb",vi:"Vùng khí hậu nóng, rất ẩm; điều kiện nghiên cứu độ ổn định dài hạn 30°C/75%RH.",en:"Hot, very humid climatic zone with long-term stability testing at 30°C/75%RH."}],quiz:[{q:{vi:"Dữ liệu dài hạn 24 tháng ít thay đổi, cấp tốc đạt. Theo nguyên tắc ICH Q1E, hạn dùng đề xuất tối đa là bao nhiêu?",en:"Long-term data cover 24 months with little change and accelerated data pass. Per ICH Q1E, what is the maximum proposed shelf life?"},options:{vi:["24 tháng","48 tháng","60 tháng","36 tháng"],en:["24 months","48 months","60 months","36 months"]},answer:3,explain:{vi:"Nhỏ hơn giữa 2 x 24 = 48 và 24 + 12 = 36, nên tối đa 36 tháng.",en:"The smaller of 2 x 24 = 48 and 24 + 12 = 36, so 36 months at most."}},{q:{vi:"Trang thiết bị y tế tại Việt Nam được phân loại rủi ro như thế nào?",en:"How are medical devices risk-classified in Vietnam?"},options:{vi:["3 loại I, II, III","4 loại A, B, C, D với D rủi ro cao nhất","2 loại có và không xâm lấn","Theo giá trị nhập khẩu"],en:["3 classes I, II, III","4 classes A, B, C, D with D the highest risk","2 classes, invasive or not","By import value"]},answer:1,explain:{vi:"Nghị định 98/2021/NĐ-CP chia trang thiết bị y tế thành loại A, B, C, D theo mức độ rủi ro tăng dần.",en:"Decree 98/2021/ND-CP groups devices into classes A, B, C and D by increasing risk."}},{q:{vi:"Cấp trên đề nghị ghi là đã có dữ liệu 24 tháng dù mới có 21 tháng. Bạn làm gì?",en:"Your manager asks you to state 24 months of data when only 21 exist. What do you do?"},options:{vi:["Từ chối, nộp đúng dữ liệu và báo cáo người có thẩm quyền","Ghi theo yêu cầu rồi bổ sung sau","Ghi mập mờ “khoảng 2 năm”","Hoãn nộp vô thời hạn"],en:["Refuse, file the true data and escalate","Comply and update later","Write a vague “about 2 years”","Postpone filing indefinitely"]},answer:0,explain:{vi:"Khai dữ liệu không có thật là vi phạm tính toàn vẹn dữ liệu và có thể bị thu hồi giấy phép.",en:"Declaring non-existent data breaches data integrity and can lead to licence withdrawal."}},{q:{vi:"Điều kiện nghiên cứu độ ổn định dài hạn cho vùng khí hậu IVb là gì?",en:"What are the long-term stability conditions for climatic zone IVb?"},options:{vi:["25°C/60%RH","40°C/75%RH","30°C/75%RH","5°C ± 3°C"],en:["25°C/60%RH","40°C/75%RH","30°C/75%RH","5°C ± 3°C"]},answer:2,explain:{vi:"Vùng IVb (nóng, rất ẩm) như Việt Nam dùng 30°C/75%RH; 40°C/75%RH là điều kiện lão hóa cấp tốc.",en:"Zone IVb (hot, very humid) such as Vietnam uses 30°C/75%RH; 40°C/75%RH is the accelerated condition."}}]}},"KK-713":{scenario:{company:"Huong Giang Pharma Plant",supervisor:{name:"Vương Đức Thành",role:{vi:"Giám đốc Đảm bảo Chất lượng",en:"Head of Quality Assurance"}},ref_code:"BMR-7720",title:{vi:"Đủ hồ sơ. Khớp đối chiếu. Mới xuất xưởng.",en:"Complete records. Reconciled labels. Then release."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát hồ sơ lô BMR-7720 (viên nang Cefaxin 500 mg, sản phẩm mô phỏng) trước khi trình xuất xưởng. Kho cấp 12500 nhãn đã in số lô và hạn dùng. Theo biên bản đóng gói: dán trên hộp thành phẩm 11836, dán trên mẫu kiểm nghiệm và mẫu lưu 24, hủy có biên bản 412, trả kho 175. Đối chiếu phiếu rà soát nháp với hồ sơ gốc, sửa tình trạng lô và số nhãn chênh lệch chưa giải trình, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You review batch record BMR-7720 (Cefaxin 500 mg capsules, a simulated product) before release. The warehouse issued 12500 labels pre-printed with batch number and expiry. Per the packaging record: applied to finished cartons 11836, applied to QC and retention samples 24, destroyed with a record 412, returned to stock 175. Compare the draft review sheet with the source records, correct the batch status and the unexplained label discrepancy, then write an evidence-based report."},reference_title:{vi:"Hồ sơ lô & quy trình xuất xưởng đã duyệt",en:"Batch record & approved release procedure"},fields:[{id:"LOT_STATUS",label:{vi:"Tình trạng lô",en:"Batch status"},initial:"RELEASED",expected:"QUARANTINE",choices:["RELEASED","QUARANTINE","REJECTED"],reference:"Quy trình xuất xưởng lô",ref_value:{vi:"Lô có sai lệch đang mở phải giữ biệt trữ (QUARANTINE) đến khi điều tra xong; chỉ loại bỏ khi có kết luận",en:"A batch with an open deviation stays in QUARANTINE until investigated; reject only on a conclusion"},hint:{vi:"Chưa có kết luận điều tra thì không được xuất xưởng, nhưng cũng chưa đủ căn cứ loại bỏ lô.",en:"Without an investigation conclusion the batch cannot be released, nor is there a basis to reject it yet."}},{id:"LABEL_GAP",label:{vi:"Số nhãn chênh lệch chưa giải trình",en:"Unexplained label discrepancy"},initial:"0",expected:"53",reference:"Biên bản đối chiếu bao bì in",ref_value:{vi:"Nhận 12500; dán thành phẩm 11836; dán mẫu 24; hủy có biên bản 412; trả kho 175",en:"Issued 12500; finished cartons 11836; samples 24; destroyed with record 412; returned 175"},hint:{vi:"Cộng đủ mọi đầu ra đã có chứng từ rồi so với số nhãn đã nhận từ kho.",en:"Add every documented outflow and compare it with the labels issued by the warehouse."}}],sop32:{vi:"Đối chiếu bao bì in: chênh lệch = số nhận - (dán thành phẩm + dán mẫu + hủy có biên bản + trả kho). Tiêu chí chấp nhận bằng 0; khác 0 phải mở sai lệch và điều tra trước khi xuất xưởng.",en:"Printed packaging reconciliation: discrepancy = issued - (finished cartons + samples + destroyed with record + returned). Acceptance is zero; any gap opens a deviation and investigation before release."},context:{label:"eQMS / BMR-7720",metrics:[{label:{vi:"Nhãn nhận từ kho",en:"Labels issued"},value:"12500"},{label:{vi:"Dán thành phẩm",en:"Finished cartons"},value:"11836"},{label:{vi:"Hủy / trả kho",en:"Destroyed / returned"},value:"412 / 175"},{label:{vi:"Hạn giao gói thầu (sáng mai)",en:"Tender delivery (tomorrow)"},value:"08:00"}]},crisis:{vi:"Giám đốc sản xuất nhắn: “Lô này phải giao gói thầu bệnh viện sáng mai. Cứ ghi chênh lệch 0, coi như nhãn rơi vãi đã hủy, ký phiếu xuất xưởng đi, điều tra sau cũng được.”",en:"The production director messages you: “This batch must go to the hospital tender tomorrow morning. Write zero discrepancy, assume the stray labels were destroyed, sign the release and investigate later.”"},options:{safe:{vi:"Không ký xuất xưởng, giữ lô biệt trữ, mở sai lệch và tìm nhãn thất lạc tại dây chuyền, báo Giám đốc QA và người chịu trách nhiệm xuất xưởng, đề nghị cung ứng thông báo khách hàng lịch giao mới.",en:"Do not sign the release, keep the batch quarantined, open a deviation and search the line for the missing labels, inform the Head of QA and the release authority, and ask supply chain to agree a new delivery date."},shortcut:{vi:"Ghi chênh lệch 0, ký xuất xưởng để kịp giao rồi điều tra sau.",en:"Record zero discrepancy, sign the release to deliver on time and investigate later."},wait:{vi:"Để phiếu rà soát dang dở và chờ Giám đốc sản xuất tự xử lý.",en:"Leave the review sheet unfinished and let the production director deal with it."}},questions:{vi:["Trình bày cách tính 53 nhãn chênh lệch và vì sao lô phải ở trạng thái QUARANTINE thay vì RELEASED hay REJECTED.","Kế hoạch điều tra sai lệch và CAPA của bạn là gì để ngăn nhãn in sẵn số lô bị thất lạc ra ngoài?"],en:["Show how you got 53 missing labels and why the batch must be QUARANTINE rather than RELEASED or REJECTED.","What deviation investigation and CAPA would you run to stop pre-printed labels from going missing?"]},hints:{vi:["Đối chiếu trạng thái lô trên phiếu nháp với quy định về sai lệch đang mở trong quy trình xuất xưởng.","Liệt kê đủ bốn đầu ra có chứng từ ở SOP mục 3.2 trước khi trừ khỏi số nhãn nhận.","Đọc lại SOP mục 4.2: áp lực giao hàng không bao giờ là lý do xuất xưởng lô có sai lệch chưa điều tra."],en:["Compare the draft batch status with the open-deviation rule in the release procedure.","List all four documented outflows in SOP 3.2 before subtracting from the issued labels.","Re-read SOP 4.2: delivery pressure is never a reason to release a batch with an uninvestigated deviation."]}},learning:{summary:{vi:"Chuyên viên đảm bảo và kiểm soát chất lượng nhà máy dược phẩm GMP bảo đảm mỗi lô thuốc được sản xuất, kiểm nghiệm và xuất xưởng đúng hồ sơ đăng ký và nguyên tắc GMP. Người làm nghề rà soát hồ sơ lô, quản lý sai lệch, CAPA, kiểm soát thay đổi, điều tra kết quả ngoài tiêu chuẩn và bảo vệ tính toàn vẹn dữ liệu. Quyết định của QA trực tiếp bảo vệ sức khỏe người bệnh.",en:"A pharmaceutical QA/QC specialist in a GMP plant makes sure every batch is made, tested and released in line with the marketing authorization and GMP. The role reviews batch records, manages deviations, CAPA and change control, investigates out-of-specification results and protects data integrity. QA decisions directly protect patients' health."},responsibilities:{vi:["Rà soát hồ sơ lô sản xuất, đóng gói và kết quả kiểm nghiệm trước khi trình xuất xưởng.","Tiếp nhận, phân loại, điều tra sai lệch và theo dõi CAPA đến khi đóng.","Quản lý kiểm soát thay đổi, thẩm định quy trình, thẩm định vệ sinh và hiệu chuẩn thiết bị.","Điều tra kết quả OOS, OOT tại phòng kiểm nghiệm theo quy trình nhiều giai đoạn.","Tổ chức tự thanh tra, đánh giá nhà cung cấp và chuẩn bị cho thanh tra GMP."],en:["Review manufacturing and packaging records and test results before release.","Log, classify and investigate deviations and follow CAPA to closure.","Manage change control, process and cleaning validation and equipment calibration.","Investigate OOS and OOT laboratory results through a phased procedure.","Run self-inspections, supplier audits and prepare for GMP inspections."]},competencies:[{name:{vi:"Nguyên tắc GMP",en:"GMP principles"},desc:{vi:"Áp dụng yêu cầu GMP về nhân sự, nhà xưởng, sản xuất, kiểm tra chất lượng và hồ sơ tài liệu.",en:"Apply GMP requirements for people, premises, production, quality control and documentation."}},{name:{vi:"Điều tra & CAPA",en:"Investigation & CAPA"},desc:{vi:"Dùng 5 Why, biểu đồ xương cá để tìm nguyên nhân gốc và đề xuất hành động khắc phục, phòng ngừa hiệu quả.",en:"Use 5 Why and fishbone tools to find root causes and define effective corrective and preventive actions."}},{name:{vi:"Quản lý rủi ro chất lượng",en:"Quality risk management"},desc:{vi:"Đánh giá mức độ nghiêm trọng, khả năng xảy ra và phát hiện để ưu tiên kiểm soát theo ICH Q9.",en:"Rate severity, occurrence and detectability to prioritize controls per ICH Q9."}},{name:{vi:"Toàn vẹn dữ liệu",en:"Data integrity"},desc:{vi:"Bảo đảm dữ liệu theo ALCOA+, kiểm tra nhật ký kiểm toán của hệ thống máy tính.",en:"Keep data ALCOA+ compliant and review audit trails of computerized systems."}},{name:{vi:"Bản lĩnh nghề nghiệp",en:"Professional courage"},desc:{vi:"Giữ quyết định chất lượng độc lập trước áp lực sản xuất, giao hàng và doanh thu.",en:"Hold independent quality decisions against production, delivery and revenue pressure."}}],knowledge:{vi:["Thông tư 35/2018/TT-BYT về Thực hành tốt sản xuất thuốc, nguyên liệu làm thuốc (GMP).","Hướng dẫn GMP của WHO, PIC/S và EU-GMP, trong đó có yêu cầu đối chiếu bao bì in.","ICH Q9 về quản lý rủi ro chất lượng và ICH Q10 về hệ thống chất lượng dược phẩm.","Nguyên tắc toàn vẹn dữ liệu ALCOA+ và yêu cầu với hệ thống máy tính trong GMP.","Quy trình điều tra kết quả ngoài tiêu chuẩn (OOS) theo các giai đoạn.","Thẩm định quy trình, thẩm định vệ sinh và chương trình độ ổn định liên tục."],en:["Circular 35/2018/TT-BYT on Good Manufacturing Practice for medicines and starting materials.","WHO, PIC/S and EU GMP guidance, including printed packaging reconciliation.","ICH Q9 on quality risk management and ICH Q10 on the pharmaceutical quality system.","ALCOA+ data integrity principles and GMP requirements for computerized systems.","The phased procedure for investigating out-of-specification (OOS) results.","Process validation, cleaning validation and the ongoing stability programme."]},tools:["Hệ thống quản lý chất lượng điện tử (eQMS)","Hồ sơ lô điện tử (eBMR)","Hệ thống quản lý phòng thí nghiệm (LIMS)","Phần mềm giám sát nhiệt độ, độ ẩm","Công cụ 5 Why và biểu đồ xương cá"],kpis:{vi:["Tỷ lệ lô được rà soát và xuất xưởng đúng hạn mà không sai sót hồ sơ.","Tỷ lệ sai lệch đóng đúng hạn và CAPA được xác nhận hiệu quả.","Số sai lệch lặp lại do cùng nguyên nhân gốc.","Số phát hiện nghiêm trọng trong thanh tra GMP (mục tiêu bằng 0)."],en:["Share of batches reviewed and released on time without record errors.","Deviations closed on time and CAPA verified effective.","Repeat deviations with the same root cause.","Critical findings in GMP inspections (target zero)."]},day:[{time:"07:45",vi:"Đi kiểm tra dây chuyền, xác nhận dọn quang dây chuyền trước khi đóng gói lô mới.",en:"Walk the lines and verify line clearance before packaging a new batch."},{time:"09:00",vi:"Rà soát hồ sơ lô, đối chiếu bao bì in và kết quả kiểm nghiệm.",en:"Review batch records, label reconciliation and test results."},{time:"11:00",vi:"Họp điều tra sai lệch với sản xuất và kiểm nghiệm, xác định nguyên nhân gốc.",en:"Hold a deviation investigation with production and QC to find the root cause."},{time:"14:00",vi:"Đánh giá yêu cầu thay đổi và kế hoạch thẩm định liên quan.",en:"Assess change requests and the related validation plans."},{time:"16:00",vi:"Cập nhật eQMS, theo dõi CAPA và trình hồ sơ xuất xưởng.",en:"Update the eQMS, follow up CAPA and submit release packages."}],mistakes:{vi:["Xuất xưởng lô khi sai lệch còn mở vì áp lực giao hàng.","Đối chiếu bao bì in thiếu một đầu ra như mẫu lưu hoặc nhãn trả kho.","Kiểm nghiệm lại nhiều lần đến khi đạt mà không điều tra kết quả OOS ban đầu."],en:["Releasing a batch with an open deviation under delivery pressure.","Missing an outflow such as retention samples or returned labels in reconciliation.","Retesting until a pass without investigating the original OOS result."]},career:[{vi:"Kiểm nghiệm viên / Nhân viên QA",en:"QC analyst / QA officer"},{vi:"Chuyên viên đảm bảo chất lượng GMP",en:"GMP quality assurance specialist"},{vi:"Trưởng bộ phận QA hoặc QC",en:"QA or QC manager"},{vi:"Giám đốc chất lượng / Người chịu trách nhiệm xuất xưởng",en:"Head of Quality / Batch release authority"}],glossary:[{term:"BMR",vi:"Hồ sơ lô sản xuất ghi lại toàn bộ quá trình sản xuất, kiểm tra của một lô thuốc.",en:"Batch manufacturing record documenting the full production and checks of a batch."},{term:"Deviation",vi:"Sai lệch: sự khác biệt so với quy trình, tiêu chuẩn đã duyệt, phải ghi nhận và điều tra.",en:"A departure from an approved procedure or standard that must be recorded and investigated."},{term:"CAPA",vi:"Hành động khắc phục và phòng ngừa nhằm loại bỏ nguyên nhân gốc, tránh tái diễn.",en:"Corrective and preventive action that removes root causes and prevents recurrence."},{term:"OOS",vi:"Kết quả ngoài tiêu chuẩn: kết quả kiểm nghiệm nằm ngoài tiêu chuẩn chất lượng đã duyệt.",en:"Out of specification: a test result outside the approved specification."},{term:"ALCOA+",vi:"Nguyên tắc dữ liệu quy kết được, dễ đọc, ghi đồng thời, nguyên gốc, chính xác, đầy đủ, nhất quán, bền vững, sẵn có.",en:"Data that is attributable, legible, contemporaneous, original, accurate, complete, consistent, enduring and available."}],quiz:[{q:{vi:"Nhận 5000 nhãn; dán thành phẩm 4700; dán mẫu 20; hủy có biên bản 230; trả kho 40. Số nhãn chênh lệch là bao nhiêu?",en:"5000 labels issued; 4700 on cartons; 20 on samples; 230 destroyed with record; 40 returned. What is the discrepancy?"},options:{vi:["0 nhãn","10 nhãn","50 nhãn","290 nhãn"],en:["0 labels","10 labels","50 labels","290 labels"]},answer:1,explain:{vi:"5000 - (4700 + 20 + 230 + 40) = 5000 - 4990 = 10 nhãn, phải mở sai lệch.",en:"5000 - (4700 + 20 + 230 + 40) = 5000 - 4990 = 10 labels, so a deviation is required."}},{q:{vi:"Khi có kết quả OOS, bước đầu tiên đúng là gì?",en:"What is the correct first step after an OOS result?"},options:{vi:["Kiểm lại ngay đến khi đạt","Loại bỏ lô ngay lập tức","Thay mẫu khác rồi báo cáo kết quả đạt","Điều tra phòng thí nghiệm giai đoạn I trước khi kiểm lại"],en:["Retest until it passes","Reject the batch at once","Swap the sample and report a pass","Run a phase I laboratory investigation before any retest"]},answer:3,explain:{vi:"Phải tìm sai sót phân tích có thể xác định trước; kiểm lại đến khi đạt là vi phạm GMP.",en:"First look for an assignable analytical error; testing into compliance violates GMP."}},{q:{vi:"Chữ A đầu tiên trong ALCOA nghĩa là gì?",en:"What does the first A in ALCOA stand for?"},options:{vi:["Quy kết được: biết ai làm, khi nào","Tự động hóa","Đã phê duyệt","Được lưu trữ"],en:["Attributable: who did it and when","Automated","Approved","Archived"]},answer:0,explain:{vi:"Attributable: mọi dữ liệu phải quy được cho người thực hiện và thời điểm ghi.",en:"Attributable: every record must be traceable to the person and time it was made."}},{q:{vi:"Giám đốc sản xuất yêu cầu ký xuất xưởng lô có sai lệch chưa điều tra để kịp giao. Bạn làm gì?",en:"Production asks you to release a batch with an uninvestigated deviation to meet delivery. What do you do?"},options:{vi:["Ký vì đã có lệnh cấp trên","Ký nhưng ghi chú điều tra sau","Không ký, giữ biệt trữ, điều tra và báo Giám đốc QA","Bỏ qua và nghỉ phép"],en:["Sign because a superior ordered it","Sign with a note to investigate later","Do not sign, keep it quarantined, investigate and inform the Head of QA","Ignore it and take leave"]},answer:2,explain:{vi:"Quyết định xuất xưởng phải độc lập và dựa trên hồ sơ đầy đủ; sai lệch mở thì lô phải biệt trữ.",en:"Release decisions must be independent and based on complete records; an open deviation keeps the batch quarantined."}}]}},"KK-714":{scenario:{company:"Son Tra Biomedical",supervisor:{name:"Tạ Quỳnh Anh",role:{vi:"Trưởng phòng Medical Affairs",en:"Medical Affairs Manager"}},ref_code:"CR-5093",title:{vi:"Dữ liệu cân bằng. Báo cáo kịp thời. Đạo đức trước.",en:"Balanced data. Timely reporting. Ethics first."},brief:{vi:"Đây là tình huống đào tạo. Sau buổi gặp bác sĩ tim mạch, bạn hoàn thiện báo cáo CR-5093 cho thuốc hạ lipid Vastorel (sản phẩm mô phỏng). Bác sĩ cho biết một người bệnh phải nhập viện vì đau cơ, CK tăng cao sau 2 tuần dùng thuốc. Slide trình bày dùng nghiên cứu 3 năm: biến cố tim mạch chính 12,4% ở nhóm chứng và 9,9% ở nhóm điều trị. Đối chiếu báo cáo nháp với tài liệu đã duyệt, sửa phân loại biến cố bất lợi và số NNT, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. After a cardiologist visit you complete call report CR-5093 for the lipid-lowering drug Vastorel (a simulated product). The doctor said one patient was hospitalized with muscle pain and high CK after 2 weeks on it. The slide deck uses a 3-year study: major cardiovascular events 12.4% in the control arm and 9.9% in the treatment arm. Compare the draft report with the approved materials, correct the adverse event classification and the NNT, then write an evidence-based report."},reference_title:{vi:"SOP cảnh giác dược & tóm tắt nghiên cứu đã duyệt",en:"Pharmacovigilance SOP & approved study summary"},fields:[{id:"AE_CLASS",label:{vi:"Phân loại biến cố bất lợi",en:"Adverse event classification"},initial:"NON-SERIOUS",expected:"SAE",choices:["NOT-AE","NON-SERIOUS","SAE"],reference:"SOP cảnh giác dược - tiêu chí nghiêm trọng",ref_value:{vi:"SAE (nghiêm trọng) nếu tử vong, đe dọa tính mạng, phải nhập viện hoặc kéo dài nằm viện, tàn tật, dị tật bẩm sinh",en:"SAE (serious) if death, life-threatening, hospitalization or prolonged stay, disability or congenital anomaly"},hint:{vi:"Chỉ cần một tiêu chí nghiêm trọng là đủ, không cần chứng minh chắc chắn do thuốc.",en:"One seriousness criterion is enough; causality does not need to be proven."}},{id:"NNT",label:{vi:"Số người cần điều trị (NNT)",en:"Number needed to treat (NNT)"},initial:"5",expected:"40",reference:"Tóm tắt nghiên cứu 3 năm",ref_value:{vi:"Biến cố tim mạch chính: nhóm chứng 12,4%; nhóm điều trị 9,9%; theo dõi 3 năm",en:"Major cardiovascular events: control 12.4%; treatment 9.9%; 3-year follow-up"},hint:{vi:"NNT dựa trên mức giảm nguy cơ tuyệt đối, không phải mức giảm nguy cơ tương đối.",en:"NNT is based on the absolute risk reduction, not the relative risk reduction."}}],sop32:{vi:"ARR = tỷ lệ biến cố nhóm chứng - tỷ lệ biến cố nhóm điều trị; NNT = 1 / ARR (ARR ở dạng thập phân), làm tròn lên số nguyên. Không dùng RRR thay ARR. Biến cố bất lợi phải chuyển Cảnh giác dược trong 24 giờ.",en:"ARR = control event rate - treatment event rate; NNT = 1 / ARR (as a decimal), rounded up. Never use RRR instead of ARR. Adverse events go to Pharmacovigilance within 24 hours."},context:{label:"CRM / CR-5093",metrics:[{label:{vi:"Biến cố nhóm chứng",en:"Control event rate"},value:"12.4%"},{label:{vi:"Biến cố nhóm điều trị",en:"Treatment event rate"},value:"9.9%"},{label:{vi:"Thời gian theo dõi (năm)",en:"Follow-up (years)"},value:"3"},{label:{vi:"Hạn chuyển báo cáo AE",en:"AE forwarding deadline"},value:"24 h"}]},crisis:{vi:"Quản lý vùng nhắn: “Ca nhập viện bác sĩ chỉ kể miệng, ghi là không phải AE cho gọn, cuối quý đang chạy chỉ tiêu. Tuần sau cứ nói 5 người dùng là cứu được 1, kèm phong bì cảm ơn để bác sĩ kê đều tay.”",en:"Your area manager messages you: “The doctor only mentioned that hospital case, log it as not an AE, we are chasing the quarter target. Next week say treating 5 people saves 1, and bring a thank-you envelope so the doctor keeps prescribing.”"},options:{safe:{vi:"Chuyển báo cáo AE nghiêm trọng cho Cảnh giác dược trong 24 giờ, trình bày ARR và NNT đúng tài liệu đã duyệt, từ chối mọi khoản lợi ích cho bác sĩ và báo Medical Affairs, Compliance.",en:"Forward the serious AE to Pharmacovigilance within 24 hours, present ARR and NNT exactly as approved, refuse any benefit to the doctor and inform Medical Affairs and Compliance."},shortcut:{vi:"Ghi không phải AE, giữ thông điệp “5 người cứu 1” và chuẩn bị phong bì như được giao.",en:"Log it as not an AE, keep the “treat 5, save 1” message and prepare the envelope as told."},wait:{vi:"Chưa ghi gì về ca nhập viện, đợi bác sĩ gửi hồ sơ rồi mới tính.",en:"Record nothing about the hospital case and wait for the doctor to send records first."}},questions:{vi:["Vì sao ca này là SAE và vì sao NNT là 40 chứ không phải 5? Dẫn chứng từ SOP và dữ liệu nghiên cứu.","Bạn xử lý yêu cầu đưa phong bì và thông điệp phóng đại thế nào để tuân thủ quy định thông tin thuốc và quy tắc đạo đức?"],en:["Why is this case an SAE and why is the NNT 40 rather than 5? Cite the SOP and the study data.","How do you handle the envelope request and the exaggerated message in line with drug information rules and ethics codes?"]},hints:{vi:["Đọc tiêu chí nghiêm trọng trong SOP cảnh giác dược và tìm tiêu chí khớp với ca được kể.","Tính ARR từ hai tỷ lệ biến cố trước khi áp dụng công thức NNT ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không che giấu biến cố bất lợi, không trao lợi ích để tác động kê đơn."],en:["Read the seriousness criteria in the PV SOP and find the one matching the reported case.","Work out the ARR from both event rates before applying the NNT formula in SOP 3.2.","Re-read SOP 4.2: never hide adverse events or offer benefits to influence prescribing."]}},learning:{summary:{vi:"Trình dược viên và chuyên viên tư vấn khoa học y khoa (MSL) cung cấp thông tin thuốc chính xác, cân bằng cho nhân viên y tế, hỗ trợ sử dụng thuốc hợp lý và ghi nhận phản hồi từ thực hành lâm sàng. Người làm nghề hiểu dược lý, đọc được dữ liệu nghiên cứu lâm sàng, tuân thủ quy định thông tin, quảng cáo thuốc, báo cáo biến cố bất lợi kịp thời và giữ quan hệ chuyên nghiệp, minh bạch.",en:"Medical representatives and medical science liaisons (MSL) give healthcare professionals accurate, balanced product information, support rational use and capture feedback from clinical practice. The role requires pharmacology, the ability to read clinical trial data, compliance with drug information and promotion rules, timely adverse event reporting and transparent, professional relationships."},responsibilities:{vi:["Giới thiệu thuốc theo đúng tờ hướng dẫn sử dụng và tài liệu đã được phê duyệt.","Trình bày dữ liệu lâm sàng cân bằng: hiệu quả, an toàn, chỉ định, chống chỉ định.","Ghi nhận và chuyển biến cố bất lợi, khiếu nại chất lượng cho bộ phận chuyên trách đúng hạn.","Chuyển câu hỏi ngoài chỉ định cho bộ phận Thông tin Y khoa trả lời khách quan.","Lập kế hoạch gặp khách hàng, cập nhật CRM và báo cáo hoạt động minh bạch."],en:["Present products strictly within the approved label and materials.","Show balanced clinical data: efficacy, safety, indications and contraindications.","Capture and forward adverse events and quality complaints to the right team on time.","Pass off-label questions to Medical Information for an objective answer.","Plan customer calls, update the CRM and report activities transparently."]},competencies:[{name:{vi:"Kiến thức dược lý & bệnh học",en:"Pharmacology & disease knowledge"},desc:{vi:"Hiểu cơ chế thuốc, bệnh học và vị trí của sản phẩm trong hướng dẫn điều trị.",en:"Understand drug mechanisms, disease and the product's place in treatment guidelines."}},{name:{vi:"Đọc hiểu y học chứng cứ",en:"Evidence-based medicine"},desc:{vi:"Diễn giải đúng ARR, RRR, NNT, khoảng tin cậy và giới hạn của nghiên cứu.",en:"Interpret ARR, RRR, NNT, confidence intervals and study limitations correctly."}},{name:{vi:"Cảnh giác dược",en:"Pharmacovigilance"},desc:{vi:"Nhận diện biến cố bất lợi trong mọi cuộc trao đổi và chuyển báo cáo đúng hạn.",en:"Spot adverse events in any conversation and forward them on time."}},{name:{vi:"Giao tiếp khoa học",en:"Scientific communication"},desc:{vi:"Trao đổi ngắn gọn, khách quan, trả lời câu hỏi khó bằng dữ liệu và dẫn nguồn.",en:"Communicate concisely and objectively and answer hard questions with cited data."}},{name:{vi:"Tuân thủ & đạo đức",en:"Compliance & ethics"},desc:{vi:"Không quảng cáo ngoài chỉ định, không trao lợi ích để tác động kê đơn.",en:"Never promote off-label or offer benefits to influence prescribing."}}],knowledge:{vi:["Luật Dược số 105/2016/QH13 và Nghị định 54/2017/NĐ-CP về thông tin, quảng cáo thuốc.","Quy định hiện hành về người giới thiệu thuốc và hoạt động thông tin thuốc tại cơ sở y tế.","Bộ quy tắc thực hành IFPMA về tương tác với nhân viên y tế.","ICH E2A: định nghĩa và tiêu chí biến cố bất lợi nghiêm trọng.","Y học chứng cứ: thiết kế nghiên cứu, ARR, RRR, NNT, NNH và khoảng tin cậy.","Khái niệm sử dụng ngoài chỉ định và tờ hướng dẫn sử dụng được phê duyệt."],en:["Pharmacy Law No. 105/2016/QH13 and Decree 54/2017/ND-CP on drug information and advertising.","Current rules on medical representatives and drug information activities in healthcare facilities.","The IFPMA Code of Practice on interactions with healthcare professionals.","ICH E2A definitions and seriousness criteria for adverse events.","Evidence-based medicine: study design, ARR, RRR, NNT, NNH and confidence intervals.","Off-label use and the approved product label."]},tools:["Phần mềm CRM quản lý khách hàng","Bộ trình bày điện tử đã phê duyệt","Cơ sở dữ liệu y văn PubMed","Biểu mẫu báo cáo biến cố bất lợi","Microsoft Excel / Power BI"],kpis:{vi:["Tỷ lệ biến cố bất lợi được chuyển báo cáo trong 24 giờ (mục tiêu 100%).","Số cuộc gặp có trao đổi khoa học chất lượng theo kế hoạch.","Kết quả kiểm tra tuân thủ tài liệu và hoạt động (không vi phạm).","Mức độ hài lòng của nhân viên y tế về chất lượng thông tin."],en:["Share of adverse events forwarded within 24 hours (target 100%).","Planned calls with quality scientific exchange.","Compliance audit results on materials and activities (no breaches).","Healthcare professional satisfaction with information quality."]},day:[{time:"07:30",vi:"Xem kế hoạch tuyến, đọc cập nhật y văn và tài liệu mới được duyệt.",en:"Review the territory plan, recent literature and newly approved materials."},{time:"09:00",vi:"Gặp bác sĩ tại bệnh viện theo lịch hẹn, trình bày dữ liệu đã duyệt.",en:"Meet doctors at the hospital as booked and present approved data."},{time:"11:30",vi:"Ghi nhận phản hồi, chuyển ngay biến cố bất lợi hoặc câu hỏi ngoài chỉ định.",en:"Log feedback and immediately forward adverse events or off-label questions."},{time:"14:00",vi:"Tham dự sinh hoạt khoa học tại bệnh viện theo đúng quy định.",en:"Attend a hospital scientific session in line with the rules."},{time:"17:00",vi:"Cập nhật CRM, báo cáo hoạt động và chuẩn bị kế hoạch ngày mai.",en:"Update the CRM, report activities and plan tomorrow."}],mistakes:{vi:["Dùng mức giảm nguy cơ tương đối để phóng đại hiệu quả thuốc.","Không nhận ra biến cố bất lợi khi bác sĩ chỉ kể miệng nên không báo cáo.","Trao quà, tiền hoặc chuyến đi để đổi lấy cam kết kê đơn."],en:["Using relative risk reduction to exaggerate efficacy.","Missing an adverse event because the doctor only mentioned it verbally.","Offering gifts, cash or trips in exchange for prescribing commitments."]},career:[{vi:"Trình dược viên",en:"Medical representative"},{vi:"Trình dược viên cấp cao / Chuyên viên sản phẩm",en:"Senior medical representative / Product specialist"},{vi:"Chuyên viên tư vấn khoa học y khoa (MSL)",en:"Medical science liaison (MSL)"},{vi:"Trưởng phòng Medical Affairs",en:"Head of Medical Affairs"}],glossary:[{term:"AE",vi:"Biến cố bất lợi: bất kỳ sự cố y khoa không mong muốn nào xảy ra khi dùng thuốc, chưa cần chứng minh do thuốc.",en:"Adverse event: any untoward medical occurrence during drug use, causality not required."},{term:"SAE",vi:"Biến cố bất lợi nghiêm trọng: gây tử vong, đe dọa tính mạng, nhập viện, tàn tật hoặc dị tật bẩm sinh.",en:"Serious adverse event: causing death, life threat, hospitalization, disability or congenital anomaly."},{term:"ARR",vi:"Mức giảm nguy cơ tuyệt đối: hiệu số tỷ lệ biến cố giữa nhóm chứng và nhóm điều trị.",en:"Absolute risk reduction: the difference in event rates between control and treatment."},{term:"NNT",vi:"Số người cần điều trị để ngăn một biến cố, bằng 1 chia ARR.",en:"Number needed to treat to prevent one event, equal to 1 divided by ARR."},{term:"Off-label",vi:"Sử dụng thuốc ngoài chỉ định, liều hoặc đối tượng được phê duyệt trên tờ hướng dẫn sử dụng.",en:"Use outside the indication, dose or population approved in the product label."}],quiz:[{q:{vi:"Tỷ lệ biến cố nhóm chứng 10%, nhóm điều trị 6%. NNT là bao nhiêu?",en:"Control event rate 10%, treatment 6%. What is the NNT?"},options:{vi:["NNT 4","NNT 40","NNT 2,5","NNT 25"],en:["NNT 4","NNT 40","NNT 2.5","NNT 25"]},answer:3,explain:{vi:"Mức giảm nguy cơ tuyệt đối ARR = 10% - 6% = 4% = 0,04; NNT = 1 / 0,04 = 25.",en:"ARR = 10% - 6% = 4% = 0.04; NNT = 1 / 0.04 = 25."}},{q:{vi:"Bác sĩ kể người bệnh nhập viện sau khi dùng thuốc nhưng chưa chắc do thuốc. Phân loại thế nào?",en:"A doctor says a patient was hospitalized after taking the drug but causality is unclear. How is it classified?"},options:{vi:["Không phải AE","AE nghiêm trọng, phải báo cáo","AE không nghiêm trọng","Chờ bác sĩ xác nhận rồi mới tính"],en:["Not an AE","Serious AE, must be reported","Non-serious AE","Wait for the doctor to confirm"]},answer:1,explain:{vi:"Nhập viện là tiêu chí nghiêm trọng; AE không cần chứng minh quan hệ nhân quả mới báo cáo.",en:"Hospitalization is a seriousness criterion; causality is not required to report an AE."}},{q:{vi:"Bác sĩ hỏi về dùng thuốc cho chỉ định chưa được phê duyệt. Bạn làm gì?",en:"A doctor asks about an unapproved indication. What do you do?"},options:{vi:["Ghi nhận câu hỏi và chuyển bộ phận Thông tin Y khoa trả lời","Tự trình bày dữ liệu ngoài chỉ định","Khuyên bác sĩ cứ thử","Từ chối nói chuyện tiếp"],en:["Log the question and pass it to Medical Information","Present off-label data yourself","Tell the doctor to try it","End the conversation"]},answer:0,explain:{vi:"Trình dược viên không quảng bá ngoài chỉ định; câu hỏi tự nguyện được trả lời khách quan qua kênh y khoa.",en:"Reps must not promote off-label; unsolicited questions get an objective answer via the medical channel."}},{q:{vi:"Quản lý yêu cầu đưa phong bì để bác sĩ kê đơn nhiều hơn. Phản hồi đúng là gì?",en:"Your manager asks you to give an envelope so a doctor prescribes more. What is the right response?"},options:{vi:["Đưa một lần vì là lệnh cấp trên","Đưa quà thay vì tiền","Từ chối và báo bộ phận Compliance","Nhờ đồng nghiệp đưa giúp"],en:["Do it once since it is an order","Give a gift instead of cash","Refuse and report to Compliance","Ask a colleague to deliver it"]},answer:2,explain:{vi:"Trao lợi ích để tác động kê đơn vi phạm pháp luật và quy tắc đạo đức ngành; phải từ chối và báo cáo.",en:"Benefits to influence prescribing break the law and industry codes; refuse and report."}}]}},"KK-715":{scenario:{legacy:"F"},learning:{summary:{vi:"Điều phối viên và giám sát viên nghiên cứu thử nghiệm lâm sàng (CRA) bảo đảm thử nghiệm được thực hiện đúng đề cương, đúng GCP và quy định, quyền lợi và an toàn của người tham gia được bảo vệ, dữ liệu chính xác và kiểm chứng được với hồ sơ nguồn. Người làm nghề khởi động điểm nghiên cứu, giám sát định kỳ, kiểm tra dữ liệu nguồn, theo dõi biến cố bất lợi và quản lý thuốc nghiên cứu.",en:"A clinical research associate (CRA) makes sure a trial follows the protocol, GCP and regulations, that participants' rights and safety are protected and that data are accurate and verifiable against source records. The role initiates sites, runs monitoring visits, performs source data verification, tracks adverse events and oversees investigational product accountability."},responsibilities:{vi:["Đánh giá, khởi động điểm nghiên cứu và đào tạo nhóm nghiên cứu về đề cương, quy trình.","Giám sát định kỳ: kiểm tra phiếu chấp thuận tham gia, tiêu chí lựa chọn và tuân thủ đề cương.","Kiểm tra dữ liệu nguồn (SDV), đặt và theo dõi câu hỏi dữ liệu trên hệ thống EDC.","Theo dõi báo cáo biến cố bất lợi nghiêm trọng đúng hạn và đối chiếu với hồ sơ bệnh án.","Kiểm kê thuốc nghiên cứu, hồ sơ thử nghiệm (TMF) và lập báo cáo giám sát."],en:["Qualify and initiate sites and train study teams on the protocol and procedures.","Run routine monitoring: check informed consent, eligibility and protocol compliance.","Perform source data verification (SDV) and raise and follow data queries in the EDC.","Track timely SAE reporting and reconcile it with medical records.","Reconcile investigational product, review the trial master file (TMF) and write monitoring reports."]},competencies:[{name:{vi:"GCP & đạo đức nghiên cứu",en:"GCP & research ethics"},desc:{vi:"Áp dụng nguyên tắc GCP, bảo vệ quyền, an toàn, sự tự nguyện và bảo mật của người tham gia.",en:"Apply GCP and protect participants' rights, safety, voluntariness and confidentiality."}},{name:{vi:"Kiểm tra dữ liệu nguồn",en:"Source data verification"},desc:{vi:"So khớp dữ liệu trên CRF với hồ sơ nguồn, phát hiện sai lệch và dữ liệu thiếu căn cứ.",en:"Match CRF data with source records and detect discrepancies and unsupported entries."}},{name:{vi:"Theo dõi an toàn",en:"Safety oversight"},desc:{vi:"Nhận diện SAE, SUSAR và bảo đảm báo cáo đúng thời hạn theo quy định.",en:"Recognize SAEs and SUSARs and ensure reporting within regulatory timelines."}},{name:{vi:"Giám sát dựa trên rủi ro",en:"Risk-based monitoring"},desc:{vi:"Tập trung nguồn lực vào dữ liệu, quy trình trọng yếu và tín hiệu rủi ro của từng điểm nghiên cứu.",en:"Focus effort on critical data, processes and each site's risk signals."}},{name:{vi:"Giao tiếp & liêm chính",en:"Communication & integrity"},desc:{vi:"Làm việc tôn trọng với nghiên cứu viên nhưng không chấp nhận ký lùi ngày hay sửa dữ liệu.",en:"Work respectfully with investigators but never accept backdating or altered data."}}],knowledge:{vi:["Hướng dẫn ICH E6 về Thực hành tốt thử nghiệm lâm sàng (GCP), phiên bản R3.","Thông tư 29/2018/TT-BYT quy định về thử thuốc trên lâm sàng tại Việt Nam.","Tuyên bố Helsinki của Hiệp hội Y khoa Thế giới về nguyên tắc đạo đức trong nghiên cứu y học.","ICH E2A về định nghĩa SAE, SUSAR và thời hạn báo cáo nhanh 7 ngày, 15 ngày.","Quy định hiện hành về Hội đồng đạo đức trong nghiên cứu y sinh học và phiếu chấp thuận tham gia.","Nguyên tắc toàn vẹn dữ liệu ALCOA+ áp dụng cho hồ sơ nguồn và dữ liệu điện tử."],en:["ICH E6 Good Clinical Practice (GCP), revision R3.","Circular 29/2018/TT-BYT on clinical trials of medicines in Vietnam.","The World Medical Association Declaration of Helsinki on ethical principles for medical research.","ICH E2A on SAE and SUSAR definitions and the 7-day and 15-day expedited reporting timelines.","Current rules on biomedical research ethics committees and informed consent.","ALCOA+ data integrity principles for source records and electronic data."]},tools:["Hệ thống thu thập dữ liệu điện tử (EDC)","Hệ thống quản lý thử nghiệm (CTMS)","Hồ sơ thử nghiệm điện tử (eTMF)","Hệ thống phân bổ ngẫu nhiên (IRT)","Microsoft Excel"],kpis:{vi:["Tỷ lệ báo cáo giám sát nộp đúng hạn sau mỗi lần giám sát.","Thời gian trung bình đóng câu hỏi dữ liệu trên EDC.","Tỷ lệ SAE được báo cáo trong thời hạn quy định (mục tiêu 100%).","Số phát hiện nghiêm trọng khi thanh tra, đánh giá điểm nghiên cứu (mục tiêu bằng 0)."],en:["Share of monitoring reports submitted on time after each visit.","Average time to close data queries in the EDC.","Share of SAEs reported within the required timeline (target 100%).","Critical findings in site inspections or audits (target zero)."]},day:[{time:"08:00",vi:"Rà soát chỉ số rủi ro, câu hỏi dữ liệu tồn đọng và mục tiêu chuyến giám sát.",en:"Review risk indicators, open queries and the visit objectives."},{time:"09:30",vi:"Kiểm tra phiếu chấp thuận tham gia và tiêu chí lựa chọn của người tham gia mới.",en:"Check consent forms and eligibility of newly enrolled participants."},{time:"11:00",vi:"Kiểm tra dữ liệu nguồn, đối chiếu bệnh án với CRF và đặt câu hỏi dữ liệu.",en:"Perform SDV, match medical records with the CRF and raise queries."},{time:"14:00",vi:"Kiểm kê thuốc nghiên cứu, nhiệt độ bảo quản và hồ sơ tại điểm nghiên cứu.",en:"Reconcile investigational product, storage temperatures and site files."},{time:"16:30",vi:"Họp kết thúc với nghiên cứu viên chính, thống nhất hành động khắc phục.",en:"Hold the close-out meeting with the principal investigator and agree actions."}],mistakes:{vi:["Chỉ kiểm tra dữ liệu trên EDC mà không đối chiếu hồ sơ nguồn gốc.","Bỏ qua việc người tham gia được tuyển trước ngày ký phiếu chấp thuận.","Kết luận dữ liệu đã xác minh khi mới có một nguồn kiểm tra."],en:["Checking EDC data without comparing it to the original source.","Missing that a participant was enrolled before signing consent.","Marking data verified when only one check has been done."]},career:[{vi:"Điều phối viên nghiên cứu tại điểm (CRC)",en:"Clinical research coordinator (CRC)"},{vi:"Giám sát viên nghiên cứu lâm sàng (CRA)",en:"Clinical research associate (CRA)"},{vi:"CRA cấp cao / Trưởng nhóm giám sát",en:"Senior CRA / Lead CRA"},{vi:"Quản lý dự án thử nghiệm lâm sàng",en:"Clinical project manager"}],glossary:[{term:"GCP",vi:"Thực hành tốt thử nghiệm lâm sàng: chuẩn mực đạo đức và khoa học cho thiết kế, thực hiện, ghi nhận và báo cáo thử nghiệm.",en:"Good Clinical Practice: the ethical and scientific standard for designing, conducting, recording and reporting trials."},{term:"SDV",vi:"Kiểm tra dữ liệu nguồn: so khớp dữ liệu trên phiếu thu thập với hồ sơ gốc.",en:"Source data verification: matching case report form data with original records."},{term:"CRF",vi:"Phiếu thu thập dữ liệu ca bệnh theo đề cương, dạng giấy hoặc điện tử.",en:"Case report form collecting protocol data, on paper or electronically."},{term:"SUSAR",vi:"Phản ứng có hại nghiêm trọng, không mong đợi, nghi ngờ do thuốc nghiên cứu, phải báo cáo nhanh.",en:"Suspected unexpected serious adverse reaction requiring expedited reporting."},{term:"Informed consent",vi:"Chấp thuận tham gia tự nguyện sau khi được giải thích đầy đủ, ký trước mọi thủ tục nghiên cứu.",en:"Voluntary agreement after full explanation, signed before any study procedure."}],quiz:[{q:{vi:"Kiểm tra 400 trường dữ liệu, phát hiện 12 trường không khớp hồ sơ nguồn. Tỷ lệ sai lệch là bao nhiêu?",en:"You verify 400 data fields and 12 do not match source. What is the discrepancy rate?"},options:{vi:["0,3%","12%","3%","33%"],en:["0.3%","12%","3%","33%"]},answer:2,explain:{vi:"Tỷ lệ = 12 / 400 = 0,03 = 3%; cần phân tích nguyên nhân nếu vượt ngưỡng của kế hoạch giám sát.",en:"Rate = 12 / 400 = 0.03 = 3%; analyse causes if it exceeds the monitoring plan threshold."}},{q:{vi:"Nghiên cứu viên muốn ký lùi ngày phiếu chấp thuận cho một người tham gia đã được lấy máu. Bạn làm gì?",en:"An investigator wants to backdate a consent form for a participant whose blood was already drawn. What do you do?"},options:{vi:["Từ chối, ghi nhận sai lệch đề cương, báo nhà tài trợ và yêu cầu xử lý theo quy định","Đồng ý vì người tham gia đã đồng ý miệng","Tự sửa ngày trên bản sao","Bỏ qua vì chỉ là thủ tục"],en:["Refuse, log a protocol deviation, inform the sponsor and require proper handling","Agree since verbal consent was given","Fix the date on the copy yourself","Ignore it as paperwork"]},answer:0,explain:{vi:"Chấp thuận phải ký trước mọi thủ tục; ký lùi ngày là làm sai hồ sơ và vi phạm GCP.",en:"Consent must precede any procedure; backdating falsifies records and breaches GCP."}},{q:{vi:"Theo ICH E2A, SUSAR gây tử vong hoặc đe dọa tính mạng phải báo cáo nhanh cho cơ quan quản lý trong bao lâu?",en:"Under ICH E2A, how fast must a fatal or life-threatening SUSAR be reported to regulators?"},options:{vi:["30 ngày","15 ngày","Trong báo cáo năm","7 ngày theo lịch"],en:["30 days","15 days","In the annual report","7 calendar days"]},answer:3,explain:{vi:"SUSAR gây tử vong hoặc đe dọa tính mạng: 7 ngày; các SUSAR khác: 15 ngày.",en:"Fatal or life-threatening SUSARs: 7 days; other SUSARs: 15 days."}},{q:{vi:"Dữ liệu nguồn là gì?",en:"What are source data?"},options:{vi:["Dữ liệu đã nhập vào EDC","Thông tin gốc ghi nhận lần đầu trong bệnh án, phiếu xét nghiệm","Bảng tổng hợp của nhà tài trợ","Báo cáo thống kê cuối cùng"],en:["Data entered in the EDC","Original information first recorded in charts and lab reports","The sponsor's summary tables","The final statistical report"]},answer:1,explain:{vi:"Dữ liệu nguồn là thông tin gốc trong hồ sơ nguồn, cần thiết để tái dựng và đánh giá thử nghiệm.",en:"Source data are the original records needed to reconstruct and evaluate the trial."}}]}},"KK-716":{scenario:{company:"Tan Hung Thinh General Hospital",supervisor:{name:"Phan Thị Hồng Nhung",role:{vi:"Điều dưỡng trưởng khoa Nội",en:"Internal Medicine Nurse Manager"}},ref_code:"NB-5170",title:{vi:"Đánh giá đúng. Truyền đúng. Báo cáo trung thực.",en:"Assess right. Infuse right. Report honestly."},brief:{vi:"Đây là tình huống đào tạo. Bạn nhận ca chiều tại khoa Nội cho người bệnh nữ 81 tuổi (hồ sơ NB-5170), viêm phổi, đái tháo đường, đang truyền dịch, đi lại bằng khung tập đi. Y lệnh: natri clorid 0,9% 1200 mL truyền tĩnh mạch trong 10 giờ, dây truyền loại 20 giọt/mL. Đối chiếu phiếu chăm sóc nháp với hồ sơ gốc, sửa mức nguy cơ té ngã theo thang Morse và tốc độ truyền (giọt/phút), rồi lập báo cáo bàn giao có căn cứ.",en:"This is a training scenario. You take over the afternoon shift on the medical ward for an 81-year-old woman (record NB-5170) with pneumonia and diabetes, on an IV infusion and walking with a frame. Order: sodium chloride 0.9% 1200 mL IV over 10 hours with a 20 drops/mL giving set. Compare the draft care sheet with the source record, correct the Morse fall risk level and the infusion rate (drops/min), then write an evidence-based handover report."},reference_title:{vi:"Phiếu đánh giá Morse & y lệnh điều trị",en:"Morse assessment & medical order"},fields:[{id:"FALL_RISK",label:{vi:"Mức nguy cơ té ngã (Morse)",en:"Fall risk level (Morse)"},initial:"MODERATE",expected:"HIGH",choices:["LOW","MODERATE","HIGH"],reference:"Phiếu đánh giá thang Morse",ref_value:{vi:"Tiền sử ngã 0; chẩn đoán phụ 15; khung tập đi 15; đường truyền TM 20; dáng đi yếu 10; nhận thức 0; HIGH từ 45",en:"Fall history 0; secondary diagnosis 15; frame 15; IV line 20; weak gait 10; mental status 0; HIGH from 45"},hint:{vi:"Cộng đủ sáu mục của thang Morse, kể cả điểm cho đường truyền tĩnh mạch đang lưu.",en:"Add all six Morse items, including the points for the IV line in place."}},{id:"DRIP_RATE",label:{vi:"Tốc độ truyền (giọt/phút)",en:"Infusion rate (drops/min)"},initial:"120",expected:"40",reference:"Y lệnh truyền dịch",ref_value:{vi:"Natri clorid 0,9% 1200 mL, truyền tĩnh mạch trong 10 giờ; dây truyền 20 giọt/mL",en:"Sodium chloride 0.9% 1200 mL IV over 10 hours; giving set 20 drops/mL"},hint:{vi:"Số trên bản nháp là tốc độ mL/giờ, chưa quy đổi sang giọt/phút theo loại dây truyền.",en:"The draft figure is a mL/hour rate, not yet converted to drops/min for the giving set."}}],sop32:{vi:"Tốc độ truyền (giọt/phút) = thể tích (mL) x số giọt/mL của dây truyền / thời gian truyền (phút). Không ghi tốc độ mL/giờ vào ô giọt/phút; kiểm tra lại tốc độ mỗi lần thăm người bệnh.",en:"Infusion rate (drops/min) = volume (mL) x drops/mL of the giving set / infusion time (min). Never enter a mL/hour rate in the drops/min box; recheck the rate at every patient round."},context:{label:"EMR / NB-5170",metrics:[{label:{vi:"Thể tích dịch truyền",en:"Infusion volume"},value:"1200 mL"},{label:{vi:"Thời gian truyền",en:"Infusion time"},value:"10 h"},{label:{vi:"Dây truyền (giọt/mL)",en:"Giving set (drops/mL)"},value:"20"},{label:{vi:"Tuổi người bệnh",en:"Patient age"},value:"81"}]},crisis:{vi:"Điều dưỡng ca trước nhắn: “13 giờ bà ấy suýt ngã khi tự đi vệ sinh, em đỡ kịp. Đừng ghi báo cáo sự cố nhé, khoa đang thi đua không có sự cố. Chị ký giúp em luôn phiếu đánh giá Morse lúc nhập viện.”",en:"The previous shift nurse messages you: “At 1 pm she nearly fell walking to the toilet alone, I caught her. Please do not file an incident report, the ward is competing for zero incidents. And sign the admission Morse form for me.”"},options:{safe:{vi:"Báo cáo sự cố suýt xảy ra theo quy định, đánh giá lại Morse, áp dụng biện pháp phòng ngã, báo điều dưỡng trưởng và bác sĩ điều trị; không ký thay phiếu của người khác.",en:"File the near-miss report as required, reassess the Morse score, apply fall precautions, inform the nurse manager and the attending doctor, and never sign another nurse's form."},shortcut:{vi:"Không báo cáo sự cố và ký giúp phiếu Morse cho đồng nghiệp để giữ thành tích khoa.",en:"Skip the incident report and sign the Morse form for your colleague to protect the ward record."},wait:{vi:"Không làm gì thêm, đợi xem người bệnh có ngã thật rồi mới báo.",en:"Do nothing more and report only if the patient actually falls."}},questions:{vi:["Vì sao người bệnh ở mức HIGH và tốc độ đúng là 40 giọt/phút? Trình bày từ phiếu Morse và y lệnh.","Bạn bàn giao, báo cáo sự cố suýt ngã và áp dụng biện pháp phòng ngã thế nào để bảo vệ người bệnh?"],en:["Why is the patient HIGH risk and why is the correct rate 40 drops/min? Show it from the Morse form and the order.","How do you hand over, report the near fall and apply fall precautions to protect the patient?"]},hints:{vi:["Kiểm tra từng mục của thang Morse trên phiếu gốc, chú ý đường truyền tĩnh mạch và chẩn đoán phụ.","Đổi thời gian truyền sang phút và nhân với số giọt/mL ở SOP mục 3.2.","Đọc lại SOP mục 4.2: sự cố suýt xảy ra cũng phải báo cáo; không ký thay hồ sơ của người khác."],en:["Check every Morse item on the source form, especially the IV line and secondary diagnosis.","Convert the infusion time to minutes and multiply by drops/mL in SOP 3.2.","Re-read SOP 4.2: near misses must be reported too; never sign someone else's record."]}},learning:{summary:{vi:"Điều dưỡng lâm sàng chăm sóc người bệnh toàn diện suốt quá trình điều trị: đánh giá, lập kế hoạch, thực hiện y lệnh, theo dõi diễn biến và giáo dục sức khỏe. Người làm nghề phải dùng thuốc an toàn, tính toán chính xác, phòng ngừa té ngã, loét tì đè và nhiễm khuẩn, ghi chép trung thực và phát hiện sớm dấu hiệu bất thường để báo bác sĩ kịp thời.",en:"A clinical nurse provides holistic care throughout treatment: assessing, planning, carrying out orders, monitoring progress and educating patients. The role demands safe medication practice, accurate calculations, prevention of falls, pressure injuries and infection, honest documentation and early recognition of deterioration so the doctor is alerted in time."},responsibilities:{vi:["Nhận định người bệnh, đánh giá nguy cơ té ngã, loét tì đè và lập kế hoạch chăm sóc.","Thực hiện y lệnh thuốc, truyền dịch theo nguyên tắc 5 đúng và kiểm tra đối chiếu.","Theo dõi dấu hiệu sinh tồn, phát hiện sớm diễn biến xấu và báo bác sĩ.","Ghi chép phiếu chăm sóc, bàn giao ca đầy đủ, trung thực, đúng thời điểm.","Tư vấn, giáo dục sức khỏe cho người bệnh, người nhà và báo cáo sự cố y khoa."],en:["Assess patients, rate fall and pressure injury risk and plan care.","Give medicines and infusions under the five rights with cross-checks.","Monitor vital signs, recognize deterioration early and alert the doctor.","Keep care records and shift handovers complete, honest and timely.","Educate patients and families and report patient safety incidents."]},competencies:[{name:{vi:"Nhận định lâm sàng",en:"Clinical assessment"},desc:{vi:"Dùng thang điểm Morse, Braden, đau, dấu hiệu sinh tồn để phát hiện nguy cơ và ưu tiên chăm sóc.",en:"Use Morse, Braden, pain scores and vital signs to spot risks and prioritize care."}},{name:{vi:"Dùng thuốc an toàn",en:"Medication safety"},desc:{vi:"Áp dụng 5 đúng, tính liều và tốc độ truyền chính xác, kiểm tra kép thuốc nguy cơ cao.",en:"Apply the five rights, calculate doses and rates accurately and double-check high-alert drugs."}},{name:{vi:"Kiểm soát nhiễm khuẩn",en:"Infection control"},desc:{vi:"Tuân thủ vệ sinh tay, kỹ thuật vô khuẩn và quy trình chăm sóc đường truyền.",en:"Follow hand hygiene, aseptic technique and IV line care bundles."}},{name:{vi:"Giao tiếp & bàn giao",en:"Communication & handover"},desc:{vi:"Bàn giao có cấu trúc (như SBAR), trao đổi rõ ràng với bác sĩ, người bệnh và gia đình.",en:"Give structured handovers (such as SBAR) and communicate clearly with doctors, patients and families."}},{name:{vi:"Trung thực nghề nghiệp",en:"Professional honesty"},desc:{vi:"Ghi đúng những gì đã làm và quan sát, báo cáo sự cố để học hỏi, không ký thay.",en:"Record only what was done and observed, report incidents to learn and never sign for others."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 về quyền, nghĩa vụ người hành nghề và người bệnh.","Thông tư 31/2021/TT-BYT quy định hoạt động điều dưỡng trong bệnh viện.","Nguyên tắc dùng thuốc an toàn 5 đúng và kiểm tra kép thuốc nguy cơ cao.","Thang Morse đánh giá nguy cơ té ngã và thang Braden đánh giá nguy cơ loét tì đè.","Năm thời điểm vệ sinh tay của WHO và phòng ngừa nhiễm khuẩn liên quan đường truyền.","Quy định hiện hành về phòng ngừa và báo cáo sự cố y khoa trong cơ sở khám chữa bệnh."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 on practitioner and patient rights and duties.","Circular 31/2021/TT-BYT on nursing practice in hospitals.","The five rights of medication safety and double checks for high-alert drugs.","The Morse Fall Scale and the Braden Scale for pressure injury risk.","The WHO five moments for hand hygiene and prevention of line-related infections.","Current rules on preventing and reporting patient safety incidents in healthcare facilities."]},tools:["Bệnh án điện tử (EMR)","Máy truyền dịch và bơm tiêm điện","Monitor theo dõi dấu hiệu sinh tồn","Máy đo đường huyết mao mạch","Thang điểm Morse và Braden"],kpis:{vi:["Tỷ lệ té ngã trên 1000 ngày nằm viện của khoa.","Tỷ lệ người bệnh được đánh giá nguy cơ trong 24 giờ đầu nhập viện.","Số sai sót dùng thuốc đến người bệnh (mục tiêu bằng 0).","Tỷ lệ tuân thủ vệ sinh tay qua giám sát trực tiếp."],en:["Ward falls per 1000 patient-days.","Share of patients risk-assessed within 24 hours of admission.","Medication errors reaching patients (target zero).","Hand hygiene compliance measured by direct observation."]},day:[{time:"13:00",vi:"Nhận bàn giao ca theo SBAR, kiểm tra người bệnh nặng và đường truyền.",en:"Take an SBAR handover and check high-risk patients and IV lines."},{time:"14:00",vi:"Thực hiện y lệnh thuốc, tính và chỉnh tốc độ truyền dịch.",en:"Give ordered medicines and calculate and set infusion rates."},{time:"15:30",vi:"Đánh giá lại nguy cơ té ngã, loét tì đè và áp dụng biện pháp phòng ngừa.",en:"Reassess fall and pressure injury risk and apply prevention measures."},{time:"17:00",vi:"Theo dõi dấu hiệu sinh tồn, đường huyết và báo bác sĩ khi có bất thường.",en:"Monitor vital signs and glucose and alert the doctor on abnormal findings."},{time:"19:30",vi:"Hoàn thiện phiếu chăm sóc, báo cáo sự cố nếu có và bàn giao ca tối.",en:"Complete care records, report any incidents and hand over to the night shift."}],mistakes:{vi:["Ghi tốc độ mL/giờ vào ô giọt/phút hoặc dùng sai số giọt/mL của dây truyền.","Bỏ sót điểm đường truyền tĩnh mạch khi tính thang Morse.","Không báo cáo sự cố suýt xảy ra vì sợ ảnh hưởng thi đua."],en:["Entering a mL/hour rate as drops/min or using the wrong drops/mL for the set.","Leaving out the IV line points when scoring the Morse scale.","Not reporting near misses for fear of hurting ward performance."]},career:[{vi:"Điều dưỡng viên",en:"Staff nurse"},{vi:"Điều dưỡng chính / Điều dưỡng chuyên khoa",en:"Senior nurse / Specialist nurse"},{vi:"Điều dưỡng trưởng khoa",en:"Ward nurse manager"},{vi:"Trưởng phòng Điều dưỡng bệnh viện",en:"Hospital Director of Nursing"}],glossary:[{term:"Morse Fall Scale",vi:"Thang đánh giá nguy cơ té ngã gồm sáu mục: tiền sử ngã, chẩn đoán phụ, dụng cụ hỗ trợ, đường truyền, dáng đi, nhận thức.",en:"Fall risk tool with six items: fall history, secondary diagnosis, aid, IV line, gait and mental status."},{term:"SBAR",vi:"Cấu trúc bàn giao: tình huống, bối cảnh, nhận định, đề xuất.",en:"Handover structure: situation, background, assessment, recommendation."},{term:"5 đúng",vi:"Đúng người bệnh, đúng thuốc, đúng liều, đúng đường dùng, đúng thời gian.",en:"Right patient, right drug, right dose, right route and right time."},{term:"Near miss",vi:"Sự cố suýt xảy ra: tình huống có thể gây hại nhưng được ngăn chặn kịp thời.",en:"An event that could have caused harm but was stopped in time."},{term:"Braden Scale",vi:"Thang đánh giá nguy cơ loét tì đè dựa trên cảm giác, độ ẩm, hoạt động, khả năng vận động, dinh dưỡng, ma sát và trượt.",en:"Pressure injury risk tool based on sensation, moisture, activity, mobility, nutrition and friction or shear."}],quiz:[{q:{vi:"Y lệnh 1000 mL truyền trong 10 giờ, dây truyền 15 giọt/mL. Tốc độ là bao nhiêu giọt/phút?",en:"Order: 1000 mL over 10 hours with a 15 drops/mL set. What is the rate in drops/min?"},options:{vi:["100 giọt/phút","33 giọt/phút","25 giọt/phút","150 giọt/phút"],en:["100 drops/min","33 drops/min","25 drops/min","150 drops/min"]},answer:2,explain:{vi:"1000 x 15 / 600 phút = 25 giọt/phút; 100 là tốc độ mL/giờ.",en:"1000 x 15 / 600 min = 25 drops/min; 100 is the mL/hour rate."}},{q:{vi:"Người bệnh đang lưu đường truyền tĩnh mạch được cộng bao nhiêu điểm trên thang Morse?",en:"How many Morse points does an IV line in place add?"},options:{vi:["20 điểm","10 điểm","15 điểm","25 điểm"],en:["20 points","10 points","15 points","25 points"]},answer:0,explain:{vi:"Mục đường truyền tĩnh mạch hoặc kim lưu được tính 20 điểm trên thang Morse.",en:"An IV or saline lock scores 20 points on the Morse scale."}},{q:{vi:"Đồng nghiệp nhờ bạn không báo cáo một lần người bệnh suýt ngã. Bạn làm gì?",en:"A colleague asks you not to report a near fall. What do you do?"},options:{vi:["Đồng ý vì người bệnh không bị thương","Chỉ nhắc miệng trong ca","Chờ người bệnh ngã thật mới báo","Báo cáo sự cố suýt xảy ra và tăng cường phòng ngã"],en:["Agree since there was no injury","Mention it verbally on shift only","Report only if the patient really falls","Report the near miss and strengthen fall precautions"]},answer:3,explain:{vi:"Báo cáo sự cố suýt xảy ra giúp phòng ngừa tổn thương thật; che giấu là vi phạm an toàn người bệnh.",en:"Reporting near misses prevents real harm; hiding them breaches patient safety."}},{q:{vi:"Thời điểm nào thuộc 5 thời điểm vệ sinh tay của WHO?",en:"Which is one of the WHO five moments for hand hygiene?"},options:{vi:["Chỉ khi tay bẩn nhìn thấy","Sau khi tiếp xúc vùng xung quanh người bệnh","Chỉ khi kết thúc ca làm việc","Trước khi ghi hồ sơ tại quầy"],en:["Only when hands look dirty","After touching patient surroundings","Only at the end of the shift","Before charting at the desk"]},answer:1,explain:{vi:"Năm thời điểm gồm trước, sau tiếp xúc người bệnh, trước thủ thuật vô khuẩn, sau phơi nhiễm dịch và sau tiếp xúc vùng xung quanh.",en:"The moments are before and after patient contact, before aseptic tasks, after fluid exposure and after touching surroundings."}}]}},"KK-717":{scenario:{company:"Kim Son Medical Laboratory Center",supervisor:{name:"Lê Hữu Phước",role:{vi:"Trưởng khoa Xét nghiệm",en:"Head of Laboratory"}},ref_code:"QC-0611",title:{vi:"QC đạt mới trả kết quả. Tính đúng hệ số pha loãng.",en:"Pass QC before reporting. Apply the dilution factor."},brief:{vi:"Đây là tình huống đào tạo. Ca sáng tại phòng xét nghiệm, bạn rà soát phiếu duyệt kết quả QC-0611. Mẫu nội kiểm glucose mức 2 (trung bình 7,0 mmol/L, SD 0,2) cho kết quả 7,7 mmol/L. Mẫu beta-hCG của một người bệnh vượt dải tuyến tính nên được pha loãng thủ công 10 lần (1 phần mẫu + 9 phần dịch pha loãng), máy đọc 1846 mIU/mL trên mẫu đã pha. Đối chiếu phiếu nháp với hồ sơ gốc, sửa kết luận nội kiểm và kết quả hCG trả lâm sàng, rồi lập báo cáo.",en:"This is a training scenario. On the morning shift you review result approval sheet QC-0611. The level 2 glucose control (mean 7.0 mmol/L, SD 0.2) reads 7.7 mmol/L. A patient's beta-hCG sample exceeded the linear range and was manually diluted 10-fold (1 part sample + 9 parts diluent); the analyzer reads 1846 mIU/mL on the diluted sample. Compare the draft sheet with the source records, correct the QC conclusion and the hCG result to report, then write a report."},reference_title:{vi:"Biểu đồ Levey-Jennings & nhật ký pha loãng",en:"Levey-Jennings chart & dilution log"},fields:[{id:"QC_RULE",label:{vi:"Kết luận lượt chạy nội kiểm",en:"QC run conclusion"},initial:"WARNING-1-2s",expected:"REJECT-1-3s",choices:["ACCEPT","WARNING-1-2s","REJECT-1-3s"],reference:"Biểu đồ Levey-Jennings glucose",ref_value:{vi:"Glucose mức 2: trung bình 7,0 mmol/L; SD 0,2; kết quả hôm nay 7,7 mmol/L",en:"Glucose level 2: mean 7.0 mmol/L; SD 0.2; today's result 7.7 mmol/L"},hint:{vi:"Tính kết quả lệch bao nhiêu SD so với trung bình rồi áp dụng quy tắc loại bỏ của Westgard.",en:"Work out how many SDs the result is from the mean, then apply the Westgard rejection rule."}},{id:"HCG_RESULT",label:{vi:"Kết quả beta-hCG trả lâm sàng (mIU/mL)",en:"Reported beta-hCG (mIU/mL)"},initial:"1846",expected:"18460",reference:"Nhật ký pha loãng mẫu",ref_value:{vi:"Pha loãng thủ công 1 phần mẫu + 9 phần dịch pha loãng; máy đọc 1846 mIU/mL trên mẫu đã pha",en:"Manual dilution 1 part sample + 9 parts diluent; analyzer reads 1846 mIU/mL on the diluted sample"},hint:{vi:"Pha loãng thủ công thì máy không tự nhân hệ số; người duyệt phải nhân trước khi trả kết quả.",en:"With manual dilution the analyzer does not apply the factor; the reviewer must multiply before reporting."}}],sop32:{vi:"Kết quả trả = giá trị máy đọc trên mẫu đã pha x hệ số pha loãng; hệ số = (thể tích mẫu + thể tích dịch pha loãng) / thể tích mẫu. Ghi rõ hệ số trên LIS.",en:"Reported result = analyzer reading on the diluted sample x dilution factor; factor = (sample volume + diluent volume) / sample volume. Record the factor in the LIS."},context:{label:"LIS / QC-0611",metrics:[{label:{vi:"QC glucose mức 2",en:"Glucose control L2"},value:"7.7 mmol/L"},{label:{vi:"Trung bình / SD",en:"Mean / SD"},value:"7.0 / 0.2"},{label:{vi:"hCG trên mẫu pha",en:"hCG on diluted sample"},value:"1846 mIU/mL"},{label:{vi:"Mẫu cấp cứu chờ",en:"Pending ER samples"},value:"12"}]},crisis:{vi:"Khoa Cấp cứu gọi giục kết quả glucose của 12 người bệnh. Trưởng ca bảo: “Cứ duyệt trả kết quả, QC lệch chút thôi. Em sửa giá trị QC trên LIS thành 7,3 cho đạt rồi chạy lại sau.”",en:"The emergency department is chasing glucose results for 12 patients. The shift lead says: “Just approve the results, QC is only slightly off. Change the QC value in the LIS to 7.3 so it passes and rerun later.”"},options:{safe:{vi:"Không duyệt kết quả lượt chạy bị loại, không sửa dữ liệu QC, tìm nguyên nhân, hiệu chuẩn và chạy lại QC cùng mẫu bệnh nhân, dùng máy dự phòng đã đạt QC cho mẫu cấp cứu và báo Trưởng khoa.",en:"Do not release results from the rejected run or edit QC data; troubleshoot, recalibrate and rerun QC with the patient samples, use a backup analyzer that passed QC for urgent samples and inform the Head of Laboratory."},shortcut:{vi:"Sửa giá trị QC thành 7,3 trên LIS và duyệt trả 12 kết quả cho kịp cấp cứu.",en:"Change the QC value to 7.3 in the LIS and release the 12 results for the ER."},wait:{vi:"Giữ kết quả lại và chờ trưởng ca tự quyết định, không báo cho khoa Cấp cứu.",en:"Hold the results and let the shift lead decide, without telling the ER."}},questions:{vi:["Vì sao lượt chạy phải kết luận REJECT-1-3s và kết quả hCG đúng là 18460 mIU/mL? Trình bày từ dữ liệu gốc.","Bạn bảo đảm kết quả cấp cứu kịp thời mà vẫn tuân thủ ISO 15189 và quy trình nội kiểm thế nào?"],en:["Why must the run be REJECT-1-3s and why is the correct hCG 18460 mIU/mL? Show it from the source data.","How do you deliver urgent results on time while still complying with ISO 15189 and the QC procedure?"]},hints:{vi:["Tính độ lệch chuẩn hóa (kết quả - trung bình) / SD và so với ngưỡng 2SD, 3SD.","Xác định hệ số pha loãng từ thể tích mẫu và dịch pha loãng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không trả kết quả khi QC bị loại và tuyệt đối không sửa dữ liệu QC."],en:["Compute the z-score (result - mean) / SD and compare it with the 2SD and 3SD limits.","Derive the dilution factor from the sample and diluent volumes in SOP 3.2.","Re-read SOP 4.2: never report results from a rejected QC run and never edit QC data."]}},learning:{summary:{vi:"Kỹ thuật viên xét nghiệm y học thực hiện các xét nghiệm huyết học, sinh hóa, miễn dịch, vi sinh để hỗ trợ chẩn đoán và theo dõi điều trị. Người làm nghề kiểm soát chất lượng ở cả ba giai đoạn trước, trong và sau xét nghiệm, vận hành và bảo trì thiết bị, thực hiện nội kiểm, ngoại kiểm và an toàn sinh học. Kết quả chính xác, kịp thời và trung thực là giá trị cốt lõi của nghề.",en:"A medical laboratory technologist performs haematology, chemistry, immunology and microbiology tests that support diagnosis and treatment monitoring. The role controls quality across the pre-analytical, analytical and post-analytical phases, runs and maintains analyzers, performs internal and external QC and follows biosafety. Accurate, timely and honest results are the core value of the profession."},responsibilities:{vi:["Tiếp nhận, kiểm tra và từ chối mẫu không đạt theo tiêu chí của phòng xét nghiệm.","Chạy nội kiểm, đánh giá theo quy tắc Westgard trước khi chạy mẫu người bệnh.","Vận hành, hiệu chuẩn, bảo trì thiết bị và ghi nhật ký đầy đủ.","Duyệt kết quả, xử lý mẫu vượt dải đo, báo giá trị nguy hiểm cho lâm sàng.","Tham gia ngoại kiểm, tuân thủ an toàn sinh học và quản lý chất thải y tế."],en:["Receive and check samples and reject unsuitable ones per laboratory criteria.","Run internal QC and evaluate it with Westgard rules before patient samples.","Operate, calibrate and maintain analyzers and keep complete logs.","Validate results, handle out-of-range samples and phone critical values to clinicians.","Join external quality assessment, follow biosafety and manage medical waste."]},competencies:[{name:{vi:"Kiểm soát chất lượng",en:"Quality control"},desc:{vi:"Đọc biểu đồ Levey-Jennings, áp dụng đa quy tắc Westgard và hành động khắc phục đúng.",en:"Read Levey-Jennings charts, apply Westgard multirules and take the right corrective action."}},{name:{vi:"Kỹ thuật xét nghiệm",en:"Analytical technique"},desc:{vi:"Thực hiện chuẩn xác pha loãng, ly tâm, pipet và quy trình vận hành chuẩn của từng xét nghiệm.",en:"Perform dilutions, centrifugation, pipetting and each test's SOP precisely."}},{name:{vi:"Nhận định kết quả",en:"Result interpretation"},desc:{vi:"Phát hiện kết quả bất thường, nhiễu do tan máu, mỡ máu và mâu thuẫn với lâm sàng.",en:"Spot abnormal results, haemolysis or lipaemia interference and clinical inconsistencies."}},{name:{vi:"An toàn sinh học",en:"Biosafety"},desc:{vi:"Dùng tủ an toàn sinh học, phương tiện bảo hộ và xử lý sự cố đổ tràn đúng quy trình.",en:"Use biosafety cabinets and protective equipment and handle spills correctly."}},{name:{vi:"Liêm chính dữ liệu",en:"Data integrity"},desc:{vi:"Không sửa dữ liệu QC hay kết quả; mọi chỉnh sửa trên LIS phải có lý do và lưu vết.",en:"Never alter QC data or results; every LIS correction needs a reason and an audit trail."}}],knowledge:{vi:["ISO 15189:2022 về yêu cầu chất lượng và năng lực của phòng xét nghiệm y tế.","Quyết định 2429/QĐ-BYT năm 2017 về tiêu chí đánh giá mức chất lượng phòng xét nghiệm y học.","Nghị định 103/2016/NĐ-CP về bảo đảm an toàn sinh học tại phòng xét nghiệm.","Đa quy tắc Westgard (1-2s, 1-3s, 2-2s, R-4s, 4-1s, 10x) và biểu đồ Levey-Jennings.","Ngoại kiểm, thử nghiệm thành thạo và đánh giá độ lệch, độ chụm của phương pháp.","Sai số giai đoạn trước xét nghiệm: tan máu, sai ống chống đông, bảo quản mẫu."],en:["ISO 15189:2022 on quality and competence requirements for medical laboratories.","Decision 2429/QD-BYT (2017) on quality level criteria for medical laboratories.","Decree 103/2016/ND-CP on laboratory biosafety.","Westgard multirules (1-2s, 1-3s, 2-2s, R-4s, 4-1s, 10x) and Levey-Jennings charts.","External quality assessment, proficiency testing and method bias and precision.","Pre-analytical errors: haemolysis, wrong anticoagulant tube and sample storage."]},tools:["Máy xét nghiệm sinh hóa, miễn dịch tự động","Hệ thống thông tin xét nghiệm (LIS)","Phần mềm nội kiểm Levey-Jennings","Tủ an toàn sinh học cấp II","Pipet và máy ly tâm đã hiệu chuẩn"],kpis:{vi:["Thời gian trả kết quả (TAT) cho mẫu cấp cứu và mẫu thường.","Tỷ lệ mẫu bị từ chối do lỗi trước xét nghiệm.","Kết quả ngoại kiểm đạt yêu cầu theo từng chương trình.","Số kết quả trả khi QC chưa đạt (mục tiêu bằng 0)."],en:["Turnaround time (TAT) for urgent and routine samples.","Share of samples rejected for pre-analytical errors.","Acceptable EQA results per programme.","Results released while QC had failed (target zero)."]},day:[{time:"06:30",vi:"Khởi động máy, bảo trì hằng ngày và chạy nội kiểm hai mức.",en:"Start up analyzers, do daily maintenance and run two-level QC."},{time:"07:30",vi:"Đánh giá QC theo Westgard, chỉ chạy mẫu người bệnh khi QC đạt.",en:"Evaluate QC by Westgard rules and run patient samples only after a pass."},{time:"09:00",vi:"Tiếp nhận mẫu, kiểm tra tan máu, đông dây và từ chối mẫu không đạt.",en:"Receive samples, check for haemolysis or clots and reject unsuitable ones."},{time:"11:00",vi:"Duyệt kết quả, pha loãng mẫu vượt dải đo và báo giá trị nguy hiểm.",en:"Validate results, dilute out-of-range samples and phone critical values."},{time:"14:00",vi:"Thực hiện ngoại kiểm, ghi nhật ký thiết bị và xử lý chất thải.",en:"Run EQA samples, update instrument logs and handle waste."}],mistakes:{vi:["Coi kết quả QC vượt 3SD là cảnh báo và vẫn trả kết quả người bệnh.","Quên nhân hệ số khi pha loãng mẫu thủ công.","Sửa giá trị QC trên LIS cho đạt để kịp trả kết quả."],en:["Treating a QC result beyond 3SD as a warning and still reporting patients.","Forgetting the factor after a manual dilution.","Editing QC values in the LIS to pass and report faster."]},career:[{vi:"Kỹ thuật viên xét nghiệm",en:"Medical laboratory technician"},{vi:"Kỹ thuật viên chính / Phụ trách chuyên môn một mảng",en:"Senior technologist / Section lead"},{vi:"Quản lý chất lượng phòng xét nghiệm",en:"Laboratory quality manager"},{vi:"Trưởng khoa hoặc Giám đốc trung tâm xét nghiệm",en:"Head of laboratory / Laboratory director"}],glossary:[{term:"IQC",vi:"Nội kiểm tra chất lượng: chạy mẫu kiểm tra đã biết giá trị để giám sát độ chính xác mỗi lượt chạy.",en:"Internal quality control: running known control samples to monitor each run's accuracy."},{term:"EQA",vi:"Ngoại kiểm: so sánh kết quả với các phòng xét nghiệm khác qua mẫu của đơn vị tổ chức độc lập.",en:"External quality assessment comparing results with other labs using an independent provider's samples."},{term:"Westgard 1-3s",vi:"Quy tắc loại bỏ khi một kết quả QC vượt trung bình cộng hoặc trừ 3 độ lệch chuẩn.",en:"Rejection rule triggered when one QC result exceeds the mean plus or minus 3 SD."},{term:"TAT",vi:"Thời gian từ khi nhận mẫu đến khi trả kết quả cho lâm sàng.",en:"Turnaround time from sample receipt to result release."},{term:"Dải tuyến tính",vi:"Khoảng nồng độ máy đo chính xác; vượt dải phải pha loãng và nhân hệ số.",en:"Concentration range measured accurately; above it, dilute and apply the factor."}],quiz:[{q:{vi:"Mẫu pha loãng thủ công 1 phần mẫu + 4 phần dịch, máy đọc 320. Kết quả trả là bao nhiêu?",en:"A sample is manually diluted 1 part + 4 parts diluent and reads 320. What do you report?"},options:{vi:["64","320","1600","1280"],en:["64","320","1600","1280"]},answer:2,explain:{vi:"Hệ số = (1 + 4) / 1 = 5; kết quả = 320 x 5 = 1600.",en:"Factor = (1 + 4) / 1 = 5; result = 320 x 5 = 1600."}},{q:{vi:"Hai lượt chạy liên tiếp của cùng một mức QC đều vượt +2SD. Vi phạm quy tắc nào?",en:"Two consecutive runs of the same QC level both exceed +2SD. Which rule is violated?"},options:{vi:["1-2s","2-2s","R-4s","10x"],en:["1-2s","2-2s","R-4s","10x"]},answer:1,explain:{vi:"2-2s: hai kết quả liên tiếp cùng phía vượt 2SD, gợi ý sai số hệ thống, phải loại lượt chạy.",en:"2-2s: two consecutive results beyond 2SD on the same side, suggesting systematic error; reject the run."}},{q:{vi:"Trưởng ca yêu cầu sửa giá trị QC trên LIS cho đạt để trả kết quả cấp cứu. Bạn làm gì?",en:"The shift lead asks you to edit a QC value in the LIS so urgent results can go out. What do you do?"},options:{vi:["Từ chối, khắc phục, chạy lại QC và dùng máy dự phòng đã đạt QC","Sửa vì là mẫu cấp cứu","Trả kết quả kèm ghi chú miệng","Xóa lượt QC lỗi khỏi hệ thống"],en:["Refuse, troubleshoot, rerun QC and use a backup analyzer that passed QC","Edit it because the samples are urgent","Report with a verbal caveat","Delete the failed QC run"]},answer:0,explain:{vi:"Sửa dữ liệu QC là gian lận và có thể gây chẩn đoán sai; cấp cứu được đáp ứng bằng phương án hợp lệ.",en:"Editing QC data is fraud and can cause misdiagnosis; urgency is met by valid alternatives."}},{q:{vi:"Mẫu xét nghiệm kali bị tan máu rõ. Cách xử lý đúng là gì?",en:"A potassium sample is clearly haemolysed. What is the correct action?"},options:{vi:["Trả kết quả bình thường","Trừ bớt 1 mmol/L rồi trả","Chạy lại trên cùng mẫu","Ghi nhận, báo lâm sàng và yêu cầu lấy lại mẫu"],en:["Report it as usual","Subtract 1 mmol/L and report","Rerun the same sample","Record it, inform the ward and request a new sample"]},answer:3,explain:{vi:"Tan máu giải phóng kali từ hồng cầu làm tăng giả kết quả; phải lấy lại mẫu.",en:"Haemolysis releases potassium from red cells and falsely raises it; a new sample is needed."}}]}},"KK-718":{scenario:{company:"Hai Van Xanh General Hospital",supervisor:{name:"Mai Thanh Tùng",role:{vi:"Trưởng phòng Quản lý Chất lượng",en:"Head of Quality Management"}},ref_code:"QI-1124",title:{vi:"Phân loại trung thực. Chỉ số đúng mẫu số. Học từ sự cố.",en:"Honest grading. Right denominator. Learn from incidents."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn thiện báo cáo chất lượng tháng QI-1124 trình Hội đồng Quản lý chất lượng. Sự cố nổi bật: một người bệnh bị tiêm insulin gấp đôi liều, hạ đường huyết phải truyền glucose, hồi phục trong ngày và không phải kéo dài thời gian nằm viện. Tháng này có 21 ca té ngã, 840 lượt vào viện và 6000 ngày điều trị nội trú. Đối chiếu báo cáo nháp với tài liệu gốc, sửa phân loại sai sót thuốc và tỷ lệ té ngã trên 1000 ngày nằm viện, rồi lập báo cáo.",en:"This is a training scenario. You are finalizing monthly quality report QI-1124 for the Quality Management Council. Key incident: a patient received a double dose of insulin, became hypoglycaemic and needed IV glucose, recovered the same day and did not need a longer stay. This month had 21 falls, 840 admissions and 6000 inpatient days. Compare the draft with the source documents, correct the medication error category and the fall rate per 1000 patient-days, then write the report."},reference_title:{vi:"Hồ sơ sự cố & dữ liệu thống kê nội trú",en:"Incident file & inpatient statistics"},fields:[{id:"MERP_CAT",label:{vi:"Phân loại sai sót thuốc (NCC MERP)",en:"Medication error category (NCC MERP)"},initial:"NCC MERP C",expected:"NCC MERP E",choices:["NCC MERP C","NCC MERP E","NCC MERP F"],reference:"Thang phân loại NCC MERP",ref_value:{vi:"C: đến người bệnh, không gây hại; E: tổn hại tạm thời cần can thiệp; F: tổn hại tạm thời phải nhập hoặc kéo dài nằm viện",en:"C: reached patient, no harm; E: temporary harm needing intervention; F: temporary harm needing admission or longer stay"},hint:{vi:"Hạ đường huyết phải truyền glucose là tổn hại cần can thiệp; xem có kéo dài nằm viện hay không.",en:"Hypoglycaemia treated with IV glucose is harm needing intervention; check whether the stay was prolonged."}},{id:"FALL_RATE",label:{vi:"Tỷ lệ té ngã / 1000 ngày nằm viện",en:"Falls per 1000 patient-days"},initial:"2.5",expected:"3.5",reference:"Thống kê nội trú tháng 11",ref_value:{vi:"21 ca té ngã; 840 lượt vào viện; 6000 ngày điều trị nội trú",en:"21 falls; 840 admissions; 6000 inpatient days"},hint:{vi:"Bản nháp đang dùng sai mẫu số; chỉ số té ngã chuẩn tính theo ngày nằm viện.",en:"The draft uses the wrong denominator; the standard fall indicator uses patient-days."}}],sop32:{vi:"Tỷ lệ té ngã = số ca té ngã / tổng số ngày điều trị nội trú x 1000. Không dùng số lượt vào viện làm mẫu số; ghi rõ tử số, mẫu số và kỳ báo cáo.",en:"Fall rate = number of falls / total inpatient days x 1000. Never use admissions as the denominator; state numerator, denominator and reporting period."},context:{label:"IR SYSTEM / QI-1124",metrics:[{label:{vi:"Số ca té ngã",en:"Falls"},value:"21"},{label:{vi:"Lượt vào viện",en:"Admissions"},value:"840"},{label:{vi:"Ngày điều trị nội trú",en:"Inpatient days"},value:"6000"},{label:{vi:"Số ngày đến đợt đánh giá",en:"Days to quality assessment"},value:"21"}]},crisis:{vi:"Phó Giám đốc chuyên môn đề nghị: “Hạ sự cố insulin xuống mức C và bỏ khỏi báo cáo tháng, sắp có đoàn đánh giá chất lượng. Còn điều dưỡng gây lỗi thì lập biên bản kỷ luật ngay để răn đe.”",en:"The Deputy Medical Director says: “Downgrade the insulin incident to C and leave it out of the monthly report, the quality assessors are coming. And write up the nurse involved for discipline right away as a warning.”"},options:{safe:{vi:"Giữ phân loại E theo bằng chứng, báo cáo đầy đủ lên Hội đồng, tiến hành phân tích nguyên nhân gốc theo hướng hệ thống, bảo mật người báo cáo và báo Giám đốc bệnh viện về đề nghị che giấu.",en:"Keep category E as the evidence shows, report it fully to the Council, run a systems-focused root cause analysis, protect the reporter's confidentiality and inform the Hospital Director of the request to conceal."},shortcut:{vi:"Hạ xuống mức C, bỏ khỏi báo cáo tháng và lập biên bản kỷ luật điều dưỡng.",en:"Downgrade to C, drop it from the report and discipline the nurse."},wait:{vi:"Treo báo cáo tháng lại đến sau đợt đánh giá chất lượng.",en:"Hold the monthly report until after the quality assessment."}},questions:{vi:["Vì sao sự cố insulin là NCC MERP E và tỷ lệ té ngã đúng là 3,5 trên 1000 ngày nằm viện? Dẫn chứng từ hồ sơ.","Bạn thiết kế phân tích nguyên nhân gốc và giải pháp hệ thống thế nào thay vì kỷ luật cá nhân?"],en:["Why is the insulin event NCC MERP E and why is the fall rate 3.5 per 1000 patient-days? Cite the records.","How would you design the root cause analysis and system fixes instead of individual blame?"]},hints:{vi:["Đối chiếu diễn biến người bệnh với định nghĩa từng mức C, E, F trong thang NCC MERP.","Chọn đúng mẫu số ngày điều trị nội trú trước khi nhân 1000 ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không hạ mức, không che giấu sự cố; văn hóa an toàn không đổ lỗi cá nhân."],en:["Match the patient's course with the definitions of C, E and F on the NCC MERP index.","Pick inpatient days as the denominator before multiplying by 1000 in SOP 3.2.","Re-read SOP 4.2: never downgrade or hide incidents; a safety culture does not blame individuals."]}},learning:{summary:{vi:"Chuyên viên quản lý chất lượng và an toàn người bệnh xây dựng, đo lường và cải tiến chất lượng dịch vụ của bệnh viện. Người làm nghề quản lý hệ thống báo cáo sự cố, phân loại và phân tích nguyên nhân gốc, theo dõi chỉ số chất lượng, triển khai các mục tiêu an toàn người bệnh và chuẩn bị đánh giá theo bộ tiêu chí. Giá trị cốt lõi là minh bạch, học hỏi từ sai sót và văn hóa an toàn không đổ lỗi.",en:"A healthcare quality and patient safety officer builds, measures and improves the quality of hospital services. The role runs the incident reporting system, grades and analyses root causes, tracks quality indicators, rolls out patient safety goals and prepares for assessments against hospital standards. Its core values are transparency, learning from errors and a just, blame-free safety culture."},responsibilities:{vi:["Quản lý hệ thống báo cáo sự cố y khoa tự nguyện và bắt buộc, bảo mật người báo cáo.","Phân loại mức độ tổn hại, phân tích nguyên nhân gốc và theo dõi hành động khắc phục.","Xây dựng, thu thập và phân tích bộ chỉ số chất lượng với tử số, mẫu số chuẩn.","Triển khai các mục tiêu an toàn người bệnh: nhận diện, dùng thuốc, phẫu thuật, phòng té ngã.","Tổ chức tự đánh giá, chuẩn bị đánh giá chất lượng bệnh viện và báo cáo Hội đồng."],en:["Run voluntary and mandatory incident reporting and protect reporters' confidentiality.","Grade harm, analyse root causes and track corrective actions.","Define, collect and analyse quality indicators with standard numerators and denominators.","Roll out patient safety goals: identification, medication, surgery and fall prevention.","Organize self-assessments, prepare hospital quality assessments and report to the Council."]},competencies:[{name:{vi:"Khoa học an toàn người bệnh",en:"Patient safety science"},desc:{vi:"Hiểu mô hình sai sót hệ thống, yếu tố con người và nguyên tắc văn hóa công bằng.",en:"Understand system error models, human factors and just culture principles."}},{name:{vi:"Đo lường chất lượng",en:"Quality measurement"},desc:{vi:"Định nghĩa chỉ số, chọn đúng mẫu số, phân tích xu hướng bằng biểu đồ kiểm soát.",en:"Define indicators, choose correct denominators and analyse trends with control charts."}},{name:{vi:"Phân tích nguyên nhân gốc",en:"Root cause analysis"},desc:{vi:"Dẫn dắt RCA, FMEA, biểu đồ xương cá để tìm lỗ hổng hệ thống và giải pháp bền vững.",en:"Lead RCA, FMEA and fishbone sessions to find system gaps and durable fixes."}},{name:{vi:"Cải tiến liên tục",en:"Continuous improvement"},desc:{vi:"Triển khai chu trình PDCA, đo lường trước, sau và chuẩn hóa thực hành tốt.",en:"Run PDCA cycles, measure before and after and standardize good practice."}},{name:{vi:"Minh bạch & độc lập",en:"Transparency & independence"},desc:{vi:"Báo cáo trung thực dù áp lực thành tích, bảo vệ người báo cáo và người bệnh.",en:"Report honestly despite performance pressure and protect reporters and patients."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 và quy định về quản lý chất lượng khám chữa bệnh.","Thông tư 19/2013/TT-BYT hướng dẫn quản lý chất lượng dịch vụ khám bệnh, chữa bệnh tại bệnh viện.","Thông tư 43/2018/TT-BYT hướng dẫn phòng ngừa sự cố y khoa trong cơ sở khám bệnh, chữa bệnh.","Bộ tiêu chí chất lượng bệnh viện Việt Nam ban hành theo Quyết định 6858/QĐ-BYT năm 2016.","Thang phân loại sai sót thuốc NCC MERP (A đến I) và mô hình pho mát Thụy Sĩ của James Reason.","Công cụ RCA, FMEA, PDCA, Pareto và các mục tiêu an toàn người bệnh quốc tế."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 and rules on care quality management.","Circular 19/2013/TT-BYT on quality management of hospital services.","Circular 43/2018/TT-BYT on preventing patient safety incidents in healthcare facilities.","The Vietnam hospital quality criteria issued by Decision 6858/QD-BYT (2016).","The NCC MERP medication error index (A to I) and James Reason's Swiss cheese model.","RCA, FMEA, PDCA and Pareto tools and the international patient safety goals."]},tools:["Phần mềm báo cáo sự cố y khoa","Bảng điều khiển chỉ số chất lượng","Biểu đồ xương cá và Pareto","Biểu mẫu FMEA","Microsoft Excel / Power BI"],kpis:{vi:["Số báo cáo sự cố tự nguyện trên 1000 ngày nằm viện (tăng thể hiện văn hóa báo cáo tốt).","Tỷ lệ sự cố nghiêm trọng được hoàn thành RCA đúng hạn.","Tỷ lệ hành động khắc phục được thực hiện và kiểm chứng hiệu quả.","Xu hướng tỷ lệ té ngã, sai sót thuốc và nhiễm khuẩn bệnh viện."],en:["Voluntary incident reports per 1000 patient-days (a rise signals a healthy reporting culture).","Share of serious incidents with RCA completed on time.","Share of corrective actions implemented and verified effective.","Trends in falls, medication errors and healthcare-associated infections."]},day:[{time:"08:00",vi:"Rà soát báo cáo sự cố mới trong 24 giờ, phân loại mức tổn hại.",en:"Review incident reports from the last 24 hours and grade harm."},{time:"09:30",vi:"Đi khảo sát khoa lâm sàng, quan sát tuân thủ nhận diện người bệnh và vệ sinh tay.",en:"Walk the wards and observe patient identification and hand hygiene."},{time:"11:00",vi:"Dẫn dắt buổi phân tích nguyên nhân gốc cho sự cố nghiêm trọng.",en:"Facilitate a root cause analysis for a serious incident."},{time:"14:00",vi:"Tính chỉ số chất lượng tháng, kiểm tra tử số, mẫu số với phòng kế hoạch.",en:"Calculate monthly indicators and check numerators and denominators with planning."},{time:"16:00",vi:"Soạn báo cáo cho Hội đồng Quản lý chất lượng và theo dõi kế hoạch cải tiến.",en:"Draft the Quality Council report and follow up improvement plans."}],mistakes:{vi:["Hạ mức độ sự cố hoặc bỏ sự cố khỏi báo cáo vì sợ ảnh hưởng đánh giá.","Tính tỷ lệ té ngã theo lượt vào viện thay vì ngày nằm viện.","Kết luận lỗi cá nhân và kỷ luật thay vì tìm nguyên nhân hệ thống."],en:["Downgrading or omitting incidents for fear of a poor assessment.","Calculating falls per admission instead of per patient-day.","Blaming and disciplining individuals instead of finding system causes."]},career:[{vi:"Nhân viên mạng lưới quản lý chất lượng khoa",en:"Ward quality network member"},{vi:"Chuyên viên quản lý chất lượng & an toàn người bệnh",en:"Quality & patient safety officer"},{vi:"Phó phòng / Trưởng nhóm an toàn người bệnh",en:"Deputy head / Patient safety lead"},{vi:"Trưởng phòng Quản lý chất lượng bệnh viện",en:"Hospital Head of Quality Management"}],glossary:[{term:"Sự cố y khoa",vi:"Tình huống không mong muốn xảy ra trong quá trình chăm sóc, điều trị có thể hoặc đã gây hại cho người bệnh.",en:"An unintended event during care or treatment that could or did harm a patient."},{term:"NCC MERP",vi:"Thang phân loại sai sót thuốc từ A (có nguy cơ sai sót) đến I (sai sót góp phần gây tử vong).",en:"Medication error index from A (capacity to cause error) to I (error contributing to death)."},{term:"RCA",vi:"Phân tích nguyên nhân gốc: phương pháp có cấu trúc tìm lỗ hổng hệ thống dẫn đến sự cố.",en:"Root cause analysis: a structured method to find system gaps that led to an incident."},{term:"Just culture",vi:"Văn hóa công bằng: khuyến khích báo cáo, phân biệt lỗi hệ thống với hành vi cố ý vi phạm.",en:"A culture that encourages reporting and separates system errors from reckless conduct."},{term:"Patient-days",vi:"Ngày nằm viện: tổng số ngày điều trị nội trú của mọi người bệnh trong kỳ, mẫu số chuẩn của nhiều chỉ số.",en:"Total inpatient days of all patients in a period, the standard denominator for many indicators."}],quiz:[{q:{vi:"Tháng có 12 ca té ngã và 4800 ngày điều trị nội trú. Tỷ lệ té ngã trên 1000 ngày nằm viện là bao nhiêu?",en:"A month has 12 falls and 4800 inpatient days. What is the fall rate per 1000 patient-days?"},options:{vi:["0,25","2,5","25","4,0"],en:["0.25","2.5","25","4.0"]},answer:1,explain:{vi:"12 / 4800 x 1000 = 2,5 ca té ngã trên 1000 ngày nằm viện.",en:"12 / 4800 x 1000 = 2.5 falls per 1000 patient-days."}},{q:{vi:"Sai sót thuốc đến người bệnh nhưng không gây hại thuộc mức nào của NCC MERP?",en:"A medication error that reached the patient without harm is which NCC MERP category?"},options:{vi:["Mức A","Mức B","Mức C","Mức E"],en:["Category A","Category B","Category C","Category E"]},answer:2,explain:{vi:"Mức C: sai sót đến người bệnh, không gây hại; mức B là sai sót chưa đến người bệnh.",en:"Category C: reached the patient without harm; B means it did not reach the patient."}},{q:{vi:"Lãnh đạo đề nghị hạ mức và bỏ một sự cố khỏi báo cáo trước đợt đánh giá. Bạn làm gì?",en:"A leader asks you to downgrade and omit an incident before an assessment. What do you do?"},options:{vi:["Giữ phân loại theo bằng chứng, báo cáo đầy đủ và báo Giám đốc","Hạ mức nhưng ghi chú riêng","Bỏ khỏi báo cáo tháng này, đưa vào tháng sau","Xóa hồ sơ sự cố"],en:["Keep the evidence-based grade, report fully and inform the Director","Downgrade it with a private note","Leave it out this month and add it next month","Delete the incident file"]},answer:0,explain:{vi:"Che giấu sự cố làm mất cơ hội học hỏi và vi phạm quy định; phải minh bạch và báo cấp có thẩm quyền.",en:"Concealing incidents loses learning and breaks the rules; be transparent and escalate."}},{q:{vi:"Mục đích chính của phân tích nguyên nhân gốc (RCA) là gì?",en:"What is the main purpose of a root cause analysis (RCA)?"},options:{vi:["Xác định người phải chịu kỷ luật","Hoàn thiện hồ sơ cho đoàn đánh giá","Ước tính chi phí bồi thường","Tìm lỗ hổng hệ thống để ngăn sự cố tái diễn"],en:["Identify who to discipline","Complete paperwork for assessors","Estimate compensation costs","Find system gaps to prevent recurrence"]},answer:3,explain:{vi:"RCA tập trung vào quy trình, hệ thống, không nhằm đổ lỗi cá nhân.",en:"RCA focuses on processes and systems, not on blaming individuals."}}]}},"KK-719":{scenario:{company:"Truong Xuan General Hospital",supervisor:{name:"Châu Ngọc Diệp",role:{vi:"Trưởng bộ phận Bảo hiểm y tế",en:"Health Insurance Unit Lead"}},ref_code:"BH-6382",title:{vi:"Đúng mã bệnh. Đúng phạm vi chi trả. Không trục lợi.",en:"Right code. Right coverage. No fraud."},brief:{vi:"Đây là tình huống đào tạo. Bạn giám định hồ sơ ra viện BH-6382 của người bệnh nội trú, chẩn đoán đái tháo đường týp 2 có bệnh thận do đái tháo đường, đang điều trị insulin. Tổng chi phí điều trị 9.240.000 đồng, trong đó 740.000 đồng là thuốc ngoài danh mục BHYT; thẻ có mức hưởng 80% (số liệu mô phỏng), khám chữa bệnh đúng tuyến. Đối chiếu bảng kê nháp với hồ sơ bệnh án, sửa mã ICD-10 bệnh chính và số tiền BHYT chi trả, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You audit discharge claim BH-6382 for an inpatient with type 2 diabetes and diabetic kidney disease, treated with insulin. Total treatment cost is 9,240,000 VND, of which 740,000 VND is a drug outside the insurance formulary; the card's benefit level is 80% (simulated figure) and care was at the correct facility level. Compare the draft claim with the medical record, correct the principal ICD-10 code and the insurer-paid amount, then write an evidence-based report."},reference_title:{vi:"Hồ sơ bệnh án & bảng kê chi phí gốc",en:"Medical record & original cost statement"},fields:[{id:"ICD_MAIN",label:{vi:"Mã ICD-10 bệnh chính",en:"Principal ICD-10 code"},initial:"E11.9",expected:"E11.2",choices:["E10.2","E11.2","E11.9"],reference:"Tóm tắt bệnh án ra viện",ref_value:{vi:"Đái tháo đường týp 2 có biến chứng thận (bệnh thận do đái tháo đường); dùng insulin không đổi týp bệnh",en:"Type 2 diabetes with renal complications (diabetic kidney disease); insulin use does not change the type"},hint:{vi:"Ký tự thứ tư của nhóm E11 thể hiện biến chứng; .9 chỉ dùng khi không có biến chứng.",en:"The fourth character in E11 shows the complication; .9 is only for no complications."}},{id:"BHYT_PAY",label:{vi:"Số tiền BHYT chi trả (VND)",en:"Insurer-paid amount (VND)"},initial:"7392000",expected:"6800000",reference:"Bảng kê chi phí gốc",ref_value:{vi:"Tổng chi phí 9.240.000 đồng; ngoài danh mục BHYT 740.000 đồng; mức hưởng 80% (mô phỏng)",en:"Total cost 9,240,000 VND; outside formulary 740,000 VND; benefit level 80% (simulated)"},hint:{vi:"Chi phí ngoài danh mục không thuộc phạm vi thanh toán BHYT, phải loại trước khi áp mức hưởng.",en:"Out-of-formulary costs are not covered and must be removed before applying the benefit level."}}],sop32:{vi:"Phần BHYT chi trả = (tổng chi phí - chi phí ngoài phạm vi, danh mục BHYT) x mức hưởng ghi trên thẻ (bài mô phỏng 80%). Phần ngoài danh mục và phần cùng chi trả do người bệnh thanh toán.",en:"Insurer-paid amount = (total cost - costs outside insurance coverage or formulary) x the card benefit level (simulated 80%). Out-of-formulary costs and the co-payment are paid by the patient."},context:{label:"HIS / BH-6382",metrics:[{label:{vi:"Tổng chi phí",en:"Total cost"},value:"9,240,000 VND"},{label:{vi:"Ngoài danh mục BHYT",en:"Outside formulary"},value:"740,000 VND"},{label:{vi:"Mức hưởng mô phỏng",en:"Simulated benefit level"},value:"80%"},{label:{vi:"Hạn gửi dữ liệu hôm nay",en:"Claim data deadline today"},value:"17:00"}]},crisis:{vi:"Trưởng khoa Nội nhắn: “Thêm mã suy thận mạn giai đoạn cuối và kê thêm 2 lần lọc máu vào bảng kê để bù phần vượt trần của khoa. Bên giám định không kiểm được đâu, chiều nay gửi luôn.”",en:"The Head of Internal Medicine messages you: “Add an end-stage kidney disease code and two dialysis sessions to the claim to cover the ward's budget overrun. The auditors will never check, send it this afternoon.”"},options:{safe:{vi:"Từ chối kê khống và nâng mã, mã hóa đúng theo bệnh án, gửi phiếu đề nghị bác sĩ xác nhận nếu hồ sơ thiếu thông tin, báo Trưởng phòng Kế hoạch tổng hợp và giải trình vượt trần theo quy trình hợp lệ.",en:"Refuse phantom services and upcoding, code strictly from the record, send the doctor a written query if documentation is missing, inform the Head of General Planning and explain the overrun properly."},shortcut:{vi:"Thêm mã suy thận giai đoạn cuối và 2 lần lọc máu rồi gửi dữ liệu cho kịp hạn.",en:"Add the end-stage code and two dialysis sessions and submit before the deadline."},wait:{vi:"Không gửi hồ sơ và chờ trưởng khoa tự chỉnh bảng kê.",en:"Hold the claim and wait for the department head to edit it himself."}},questions:{vi:["Vì sao bệnh chính là E11.2 chứ không phải E11.9 hay E10.2, và số tiền BHYT chi trả đúng là 6.800.000 đồng?","Bạn xử lý yêu cầu thêm mã và dịch vụ không có thật thế nào, và trao đổi với bác sĩ khi hồ sơ ghi chép chưa đủ ra sao?"],en:["Why is the principal code E11.2 rather than E11.9 or E10.2, and why is the insurer-paid amount 6,800,000 VND?","How do you handle the request to add codes and services that did not happen, and how do you query the doctor when documentation is incomplete?"]},hints:{vi:["Đọc tóm tắt bệnh án: xác định týp đái tháo đường và biến chứng được ghi nhận.","Loại phần ngoài danh mục BHYT khỏi tổng chi phí trước khi nhân mức hưởng ở SOP mục 3.2.","Đọc lại SOP mục 4.2: không kê khống dịch vụ, không nâng mã; mọi áp lực phải báo người có thẩm quyền."],en:["Read the discharge summary: identify the diabetes type and the recorded complication.","Remove out-of-formulary costs from the total before applying the benefit level in SOP 3.2.","Re-read SOP 4.2: never bill unperformed services or upcode; escalate any pressure."]}},learning:{summary:{vi:"Chuyên viên giám định và thanh toán bảo hiểm y tế mã hóa chẩn đoán, thủ thuật theo ICD-10, kiểm tra bảng kê chi phí, đối chiếu phạm vi quyền lợi và gửi dữ liệu thanh toán cho cơ quan bảo hiểm. Người làm nghề bảo đảm cơ sở y tế được thanh toán đúng, đủ, kịp thời, người bệnh được hưởng đúng quyền lợi và quỹ bảo hiểm không bị trục lợi.",en:"A medical coding and health insurance claims specialist codes diagnoses and procedures with ICD-10, checks cost statements, verifies coverage and submits claim data to the insurer. The role makes sure the hospital is paid correctly and on time, patients receive their full entitlements and the insurance fund is protected from abuse."},responsibilities:{vi:["Đọc bệnh án, chọn bệnh chính, bệnh kèm theo và mã hóa theo ICD-10.","Kiểm tra bảng kê thuốc, vật tư, dịch vụ kỹ thuật theo danh mục và điều kiện thanh toán.","Xác định mức hưởng, phần cùng chi trả và phần người bệnh tự thanh toán.","Gửi dữ liệu điện tử theo chuẩn đầu ra, xử lý phản hồi và giải trình xuất toán.","Phối hợp với khoa lâm sàng cải thiện chất lượng ghi chép bệnh án."],en:["Read records, select principal and secondary diagnoses and code them in ICD-10.","Check drugs, supplies and procedures against the formulary and payment conditions.","Determine the benefit level, co-payment and patient-paid amounts.","Submit electronic data in the required format, handle feedback and contest disallowances.","Work with clinical wards to improve documentation quality."]},competencies:[{name:{vi:"Mã hóa lâm sàng",en:"Clinical coding"},desc:{vi:"Áp dụng quy tắc ICD-10 về chọn bệnh chính, ký tự thứ tư, mã dấu dao găm và dấu sao.",en:"Apply ICD-10 rules on principal diagnosis, fourth characters and dagger-asterisk codes."}},{name:{vi:"Nghiệp vụ BHYT",en:"Health insurance rules"},desc:{vi:"Nắm phạm vi quyền lợi, mức hưởng, danh mục thanh toán và điều kiện chi trả.",en:"Know coverage scope, benefit levels, the payment formulary and reimbursement conditions."}},{name:{vi:"Kiến thức y khoa nền",en:"Medical background"},desc:{vi:"Hiểu thuật ngữ y khoa, giải phẫu, bệnh học để đọc đúng bệnh án.",en:"Understand medical terminology, anatomy and pathology to read records correctly."}},{name:{vi:"Kiểm soát dữ liệu",en:"Data control"},desc:{vi:"Đối chiếu chéo bệnh án, chỉ định, bảng kê và dữ liệu điện tử trước khi gửi.",en:"Cross-check records, orders, statements and electronic data before submission."}},{name:{vi:"Chống trục lợi",en:"Fraud prevention"},desc:{vi:"Từ chối kê khống, nâng mã, tách dịch vụ; báo cáo dấu hiệu gian lận.",en:"Refuse phantom billing, upcoding and unbundling and report signs of fraud."}}],knowledge:{vi:["Luật Bảo hiểm y tế số 25/2008/QH12, sửa đổi bởi Luật 46/2014/QH13 và các lần sửa đổi sau.","Quy định hiện hành về phạm vi quyền lợi, mức hưởng và thanh toán chi phí khám chữa bệnh BHYT.","Bảng phân loại quốc tế bệnh tật ICD-10 của WHO và hướng dẫn mã hóa bệnh tật của Bộ Y tế.","Danh mục thuốc, vật tư y tế, dịch vụ kỹ thuật thuộc phạm vi thanh toán BHYT.","Chuẩn dữ liệu đầu ra phục vụ giám định, thanh toán chi phí khám chữa bệnh BHYT.","Các hình thức trục lợi: kê khống, nâng mã, tách dịch vụ và chế tài xử lý."],en:["Health Insurance Law No. 25/2008/QH12, amended by Law 46/2014/QH13 and later amendments.","Current rules on coverage, benefit levels and reimbursement of insured care.","The WHO ICD-10 classification and the Ministry of Health coding guidance.","Lists of drugs, medical supplies and procedures covered by health insurance.","The output data standard for insurance claim auditing and payment.","Forms of abuse: phantom billing, upcoding and unbundling, and their penalties."]},tools:["Hệ thống thông tin bệnh viện (HIS)","Công cụ tra cứu ICD-10","Hệ thống thông tin giám định BHYT","Phần mềm kiểm tra dữ liệu XML trước khi gửi","Microsoft Excel"],kpis:{vi:["Tỷ lệ hồ sơ bị xuất toán trên tổng số hồ sơ gửi giám định.","Độ chính xác mã hóa qua kiểm tra mẫu ngẫu nhiên.","Tỷ lệ dữ liệu gửi đúng hạn và đúng chuẩn.","Số phát hiện kê khống, nâng mã khi kiểm tra (mục tiêu bằng 0)."],en:["Share of claims disallowed out of all claims submitted.","Coding accuracy in random sample audits.","Share of data submitted on time and in the correct format.","Phantom billing or upcoding findings in audits (target zero)."]},day:[{time:"08:00",vi:"Nhận hồ sơ ra viện, kiểm tra thông tin thẻ và đúng tuyến.",en:"Receive discharge files and check card details and facility level."},{time:"09:30",vi:"Đọc bệnh án, chọn bệnh chính, bệnh kèm theo và mã hóa ICD-10.",en:"Read records, choose principal and secondary diagnoses and code in ICD-10."},{time:"11:00",vi:"Đối chiếu bảng kê với chỉ định, danh mục và loại chi phí ngoài phạm vi.",en:"Match statements with orders and the formulary and remove uncovered costs."},{time:"14:00",vi:"Gửi phiếu đề nghị bác sĩ làm rõ chẩn đoán khi ghi chép chưa đủ.",en:"Send queries to doctors when diagnoses are poorly documented."},{time:"16:00",vi:"Kiểm tra lỗi dữ liệu XML, gửi giám định và xử lý phản hồi xuất toán.",en:"Validate XML data, submit claims and handle disallowance feedback."}],mistakes:{vi:["Dùng mã .9 không biến chứng dù bệnh án ghi rõ biến chứng.","Áp mức hưởng trên cả chi phí ngoài danh mục BHYT.","Thêm mã bệnh hoặc dịch vụ không có trong bệnh án để tăng thanh toán."],en:["Using the .9 no-complication code although the record states a complication.","Applying the benefit level to out-of-formulary costs.","Adding diagnoses or services not in the record to increase payment."]},career:[{vi:"Nhân viên mã hóa bệnh tật",en:"Clinical coder"},{vi:"Chuyên viên giám định & thanh toán BHYT",en:"Medical coding & claims specialist"},{vi:"Trưởng nhóm mã hóa / Kiểm soát hồ sơ thanh toán",en:"Coding lead / Claims audit lead"},{vi:"Trưởng bộ phận Bảo hiểm y tế và tài chính bệnh viện",en:"Head of health insurance & hospital revenue"}],glossary:[{term:"ICD-10",vi:"Bảng phân loại quốc tế bệnh tật lần thứ 10 của WHO dùng để mã hóa chẩn đoán.",en:"WHO's International Classification of Diseases, 10th revision, used to code diagnoses."},{term:"Bệnh chính",vi:"Tình trạng được xác định cuối đợt điều trị là nguyên nhân chính khiến người bệnh cần điều trị, thăm khám.",en:"The condition identified at the end of care as chiefly responsible for the need for treatment."},{term:"Upcoding",vi:"Nâng mã: mã hóa bệnh hoặc dịch vụ nặng hơn thực tế để được thanh toán cao hơn.",en:"Coding a more severe condition or service than actually occurred to get paid more."},{term:"Xuất toán",vi:"Phần chi phí bị cơ quan bảo hiểm từ chối thanh toán sau giám định.",en:"Costs the insurer refuses to pay after auditing a claim."},{term:"Cùng chi trả",vi:"Phần chi phí trong phạm vi BHYT mà người bệnh tự trả theo mức hưởng của thẻ.",en:"The share of covered costs the patient pays according to the card's benefit level."}],quiz:[{q:{vi:"Tổng chi phí 5.000.000 đồng, ngoài danh mục 600.000 đồng, mức hưởng 80%. BHYT chi trả bao nhiêu?",en:"Total cost 5,000,000 VND, out-of-formulary 600,000 VND, benefit level 80%. How much does the insurer pay?"},options:{vi:["3.520.000 đồng","4.000.000 đồng","4.400.000 đồng","880.000 đồng"],en:["3,520,000 VND","4,000,000 VND","4,400,000 VND","880,000 VND"]},answer:0,explain:{vi:"(5.000.000 - 600.000) x 80% = 4.400.000 x 0,8 = 3.520.000 đồng.",en:"(5,000,000 - 600,000) x 80% = 4,400,000 x 0.8 = 3,520,000 VND."}},{q:{vi:"Mã ICD-10 nào là viêm phổi, không đặc hiệu?",en:"Which ICD-10 code is pneumonia, unspecified?"},options:{vi:["J45.9","I10","N18.5","J18.9"],en:["J45.9","I10","N18.5","J18.9"]},answer:3,explain:{vi:"J18.9 là viêm phổi không đặc hiệu; J45.9 là hen, I10 là tăng huyết áp nguyên phát, N18.5 là bệnh thận mạn giai đoạn 5.",en:"J18.9 is pneumonia, unspecified; J45.9 is asthma, I10 essential hypertension and N18.5 CKD stage 5."}},{q:{vi:"Trưởng khoa yêu cầu thêm dịch vụ chưa thực hiện vào bảng kê để bù vượt trần. Bạn làm gì?",en:"A department head asks you to add services that were not performed to cover an overrun. What do you do?"},options:{vi:["Thêm vì là yêu cầu của trưởng khoa","Từ chối, mã hóa đúng bệnh án và báo cấp có thẩm quyền","Thêm một dịch vụ thay vì hai","Gửi hồ sơ nhưng ghi chú riêng"],en:["Add them because the head asked","Refuse, code from the record and escalate","Add one service instead of two","Submit with a private note"]},answer:1,explain:{vi:"Kê khống là trục lợi quỹ BHYT, có thể bị xử lý hành chính hoặc hình sự; phải từ chối và báo cáo.",en:"Phantom billing defrauds the insurance fund and can bring administrative or criminal penalties; refuse and report."}},{q:{vi:"Người bệnh đái tháo đường týp 2 dùng insulin. Điều nào đúng khi mã hóa?",en:"A type 2 diabetic patient uses insulin. Which coding statement is correct?"},options:{vi:["Chuyển sang nhóm E10 vì dùng insulin","Luôn dùng E11.9","Giữ nhóm E11, chọn ký tự thứ tư theo biến chứng","Không cần mã đái tháo đường"],en:["Switch to E10 because of insulin","Always use E11.9","Keep E11 and choose the fourth character by complication","No diabetes code is needed"]},answer:2,explain:{vi:"Týp bệnh do chẩn đoán xác định, không do thuốc điều trị; ký tự thứ tư phản ánh biến chứng.",en:"The type is set by diagnosis, not treatment; the fourth character reflects the complication."}}]}},"KK-720":{scenario:{company:"Bệnh viện Đa khoa Thiên Phúc Lam Hồng",supervisor:{name:"Lương Minh Khôi",role:{vi:"Kỹ thuật viên trưởng khoa Chẩn đoán hình ảnh",en:"Chief Radiologic Technologist"}},ref_code:"CT-5518",title:{vi:"Đúng giao thức. Đúng liều. An toàn người bệnh.",en:"Right protocol. Right dose. Patient safety first."},brief:{vi:"Đây là tình huống đào tạo. Phiếu chỉ định CT-5518 (người bệnh hư cấu): nghi thuyên tắc phổi, cân nặng 70 kg, eGFR 48 mL/phút/1,73 m². Bản lập lịch nháp đang chọn giao thức chụp ngực thường quy có thuốc và bơm 100 mL thuốc cản quang 350 mgI/mL. Đối chiếu với hướng dẫn giao thức đã duyệt, sửa giao thức chụp và thể tích thuốc cản quang, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. Order CT-5518 (fictional patient): suspected pulmonary embolism, weight 70 kg, eGFR 48 mL/min/1.73 m². The draft schedule uses a routine contrast chest protocol with 100 mL of 350 mgI/mL contrast. Compare it with the approved protocol guide, correct the scan protocol and the contrast volume, then write an evidence-based report."},reference_title:{vi:"Hướng dẫn giao thức CT đã duyệt · CT-5518",en:"Approved CT protocol guide · CT-5518"},fields:[{id:"PROTOCOL",label:{vi:"Giao thức chụp",en:"Scan protocol"},initial:"CHEST-CE",expected:"CTPA",choices:["CHEST-NC","CHEST-CE","CTPA"],reference:"Bảng chọn giao thức theo chỉ định",hint:{vi:"Nghi thuyên tắc phổi cần pha động mạch phổi, kích hoạt bolus tại thân động mạch phổi, không phải pha tĩnh mạch thường quy.",en:"Suspected PE needs a pulmonary arterial phase triggered at the pulmonary trunk, not a routine venous phase."}},{id:"CONTRAST_ML",label:{vi:"Thể tích thuốc cản quang (mL)",en:"Contrast volume (mL)"},initial:"100",expected:"56",reference:"Bảng liều thuốc cản quang",ref_value:{vi:"Cân nặng 70 kg; eGFR 48 mL/phút/1,73 m²; thuốc 350 mgI/mL",en:"Weight 70 kg; eGFR 48 mL/min/1.73 m²; contrast 350 mgI/mL"},hint:{vi:"Tính theo cân nặng trước, so với mức trần, rồi mới áp dụng hệ số giảm theo chức năng thận.",en:"Dose by weight first, check the cap, then apply the renal function reduction."}}],sop32:{vi:"Thể tích thuốc cản quang iod 350 mgI/mL = cân nặng x 1,0 mL/kg, tối đa 80 mL; eGFR 30-59 giảm 20%; eGFR dưới 30 phải hội chẩn bác sĩ chẩn đoán hình ảnh trước khi tiêm (định mức mô phỏng).",en:"Iodinated contrast volume (350 mgI/mL) = weight x 1.0 mL/kg, capped at 80 mL; reduce by 20% if eGFR is 30-59; eGFR below 30 requires radiologist review before injection (training values)."},context:{label:"RIS / CT-5518",metrics:[{label:{vi:"Cân nặng",en:"Body weight"},value:"70 kg"},{label:{vi:"eGFR",en:"eGFR"},value:"48 mL/min/1.73 m²"},{label:{vi:"Nồng độ thuốc",en:"Contrast strength"},value:"350 mgI/mL"}]},crisis:{vi:"Bác sĩ lâm sàng gọi giục: “Hồ sơ cũ ghi người bệnh từng nổi mề đay sau tiêm thuốc cản quang nhưng không sao đâu, cứ bơm 100 mL như mọi lần, đừng gọi bác sĩ chẩn đoán hình ảnh cho mất thời gian.”",en:"The referring doctor calls: “The old record says the patient had hives after contrast, but it's fine. Just inject 100 mL as usual and don't waste time calling the radiologist.”"},options:{safe:{vi:"Chưa tiêm, báo ngay bác sĩ chẩn đoán hình ảnh trực để đánh giá tiền sử phản ứng và quyết định phương án, chuẩn bị sẵn bộ cấp cứu phản vệ và ghi hồ sơ.",en:"Hold the injection, inform the on-call radiologist to assess the prior reaction and decide the plan, keep the anaphylaxis kit ready and document everything."},shortcut:{vi:"Bơm 100 mL như bác sĩ lâm sàng yêu cầu, nếu có phản ứng thì xử trí sau.",en:"Inject 100 mL as the referring doctor asks and treat any reaction afterwards."},wait:{vi:"Hoãn ca chụp, không báo ai và chờ khoa lâm sàng tự liên hệ lại.",en:"Postpone the scan, tell no one and wait for the ward to call back."}},questions:{vi:["Vì sao bạn đổi giao thức chụp? Dữ liệu nào trong phiếu chỉ định chứng minh lựa chọn đó?","Trình bày cách tính thể tích thuốc cản quang và cách xử lý khi phát hiện tiền sử phản ứng với thuốc cản quang."],en:["Why did you change the scan protocol? Which data in the order supports your choice?","Explain how you calculated the contrast volume and how you handle a documented prior contrast reaction."]},hints:{vi:["Đọc lại chẩn đoán nghi ngờ trên phiếu chỉ định trước khi chọn giao thức trong bảng chọn.","Theo SOP mục 3.2: tính theo cân nặng, kiểm tra mức trần, rồi áp dụng hệ số theo eGFR.","Đọc lại SOP mục 4.2: tiền sử phản ứng thuốc cản quang phải được bác sĩ chẩn đoán hình ảnh đánh giá trước khi tiêm."],en:["Re-read the suspected diagnosis on the order before choosing from the protocol table.","Per SOP 3.2: dose by weight, check the cap, then apply the eGFR factor.","Re-read SOP 4.2: a prior contrast reaction must be assessed by the radiologist before injection."]}},learning:{summary:{vi:"Kỹ thuật viên chẩn đoán hình ảnh vận hành máy X-quang, CT, MRI và hệ thống số hóa hình ảnh để tạo ra hình ảnh có giá trị chẩn đoán cho bác sĩ. Công việc gồm xác minh người bệnh, chọn đúng giao thức theo chỉ định, định vị chính xác, kiểm soát liều bức xạ theo nguyên tắc ALARA, phối hợp tiêm thuốc cản quang an toàn và bảo đảm chất lượng hình ảnh trên PACS. Nghề đòi hỏi kỹ năng kỹ thuật vững, tư duy an toàn và giao tiếp tốt với người bệnh.",en:"A medical imaging technologist operates X-ray, CT, MRI and digital imaging systems to produce diagnostic-quality images for physicians. The work covers patient identification, choosing the right protocol for the indication, accurate positioning, keeping radiation dose ALARA, safe contrast administration with the team and image quality control on PACS. The role requires solid technical skills, a safety mindset and good communication with patients."},responsibilities:{vi:["Xác minh người bệnh bằng ít nhất hai thông tin nhận dạng và đối chiếu phiếu chỉ định trước mỗi lần chụp.","Chọn giao thức chụp phù hợp chỉ định lâm sàng, điều chỉnh thông số theo thể trạng người bệnh.","Sàng lọc chống chỉ định: thai kỳ, chức năng thận, tiền sử dị ứng thuốc cản quang, kim loại khi chụp MRI.","Thực hiện kiểm tra chất lượng hằng ngày, ghi nhận liều bức xạ và báo cáo trường hợp vượt mức tham chiếu.","Gửi hình lên PACS đúng chuẩn DICOM, ghi chú kỹ thuật và phối hợp với bác sĩ đọc kết quả."],en:["Identify each patient with at least two identifiers and match the order before every scan.","Choose the protocol that fits the clinical indication and adjust parameters to the patient's build.","Screen contraindications: pregnancy, renal function, prior contrast reactions and metal before MRI.","Run daily quality control, record radiation dose and report cases above reference levels.","Send images to PACS in DICOM format, add technical notes and coordinate with the reporting radiologist."]},competencies:[{name:{vi:"Lựa chọn giao thức",en:"Protocol selection"},desc:{vi:"Liên kết câu hỏi lâm sàng với pha chụp, vùng chụp và thời điểm tiêm thuốc phù hợp.",en:"Link the clinical question to the right phase, scan range and contrast timing."}},{name:{vi:"An toàn bức xạ",en:"Radiation protection"},desc:{vi:"Áp dụng biện minh, tối ưu hóa và giới hạn liều; theo dõi CTDIvol, DLP so với mức tham chiếu.",en:"Apply justification, optimisation and dose limits; track CTDIvol and DLP against reference levels."}},{name:{vi:"Quản lý thuốc cản quang",en:"Contrast management"},desc:{vi:"Tính liều theo cân nặng và chức năng thận, nhận biết sớm phản ứng và phối hợp cấp cứu.",en:"Dose by weight and renal function, recognise reactions early and support emergency care."}},{name:{vi:"Chất lượng hình ảnh",en:"Image quality"},desc:{vi:"Đánh giá nhiễu, độ tương phản, nhiễu ảnh do chuyển động và quyết định chụp bổ sung có kiểm soát.",en:"Assess noise, contrast and motion artefacts and decide on controlled repeat imaging."}},{name:{vi:"Giao tiếp & đạo đức",en:"Communication & ethics"},desc:{vi:"Giải thích cho người bệnh, tôn trọng quyền riêng tư và báo cáo ngay khi có nguy cơ an toàn.",en:"Explain procedures to patients, respect privacy and escalate any safety risk immediately."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15 và quy định về phạm vi hoạt động chuyên môn của kỹ thuật viên.","Nguyên tắc an toàn bức xạ: biện minh, tối ưu hóa (ALARA), giới hạn liều; quy định hiện hành về an toàn bức xạ trong y tế.","Mức liều tham chiếu chẩn đoán (DRL), ý nghĩa của CTDIvol, DLP và cách theo dõi liều người bệnh.","Sàng lọc và xử trí phản ứng thuốc cản quang iod, gadolinium; nguy cơ tổn thương thận sau tiêm thuốc cản quang.","An toàn MRI: phân vùng an toàn, sàng lọc kim loại và thiết bị cấy ghép, nhãn MR Safe, MR Conditional, MR Unsafe."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15 and rules on technologists' scope of practice.","Radiation protection principles: justification, optimisation (ALARA) and dose limits; current rules on radiation safety in healthcare.","Diagnostic reference levels (DRL), the meaning of CTDIvol and DLP, and patient dose tracking.","Screening and management of iodinated and gadolinium contrast reactions; risk of kidney injury after contrast.","MRI safety: safety zones, screening for metal and implants, MR Safe, MR Conditional and MR Unsafe labels."]},tools:["Máy CT đa dãy đầu thu","Bơm tiêm thuốc cản quang tự động","Hệ thống RIS/PACS","Phantom kiểm tra chất lượng","Bộ cấp cứu phản vệ"],kpis:{vi:["Tỷ lệ chụp lại do lỗi kỹ thuật (mục tiêu dưới 3%).","Tỷ lệ ca có liều vượt mức tham chiếu chẩn đoán được rà soát.","Thời gian từ chỉ định đến hoàn tất chụp cấp cứu.","Số sự cố an toàn thuốc cản quang và tỷ lệ được báo cáo, xử lý đúng quy trình."],en:["Repeat rate due to technical errors (target below 3%).","Share of studies above diagnostic reference levels that were reviewed.","Time from order to completed emergency scan.","Contrast safety incidents and the share reported and handled per procedure."]},day:[{time:"07:00",vi:"Khởi động máy CT, hiệu chuẩn không khí và chụp phantom kiểm tra chất lượng hằng ngày.",en:"Warm up the CT scanner, run air calibration and the daily phantom QC scan."},{time:"08:00",vi:"Rà soát danh sách chỉ định, sàng lọc chức năng thận và tiền sử dị ứng của ca có tiêm thuốc.",en:"Review the worklist and screen renal function and allergy history for contrast cases."},{time:"10:30",vi:"Thực hiện ca chụp cấp cứu, phối hợp điều dưỡng đặt đường truyền và theo dõi người bệnh.",en:"Perform emergency scans, work with nurses on IV access and patient monitoring."},{time:"14:00",vi:"Tái tạo hình ảnh, kiểm tra chất lượng và gửi lên PACS kèm ghi chú kỹ thuật.",en:"Reconstruct images, check quality and send them to PACS with technical notes."},{time:"16:30",vi:"Ghi nhận liều bức xạ, cập nhật sổ sự cố và bàn giao ca.",en:"Record radiation dose, update the incident log and hand over the shift."}],mistakes:{vi:["Chọn giao thức theo thói quen thay vì theo câu hỏi lâm sàng trên phiếu chỉ định.","Bơm liều thuốc cản quang chuẩn cho mọi người bệnh, bỏ qua cân nặng và chức năng thận.","Bỏ qua bước xác minh hai thông tin nhận dạng hoặc nhầm bên chụp khi đông người bệnh."],en:["Choosing a protocol out of habit instead of the clinical question on the order.","Giving every patient a standard contrast dose, ignoring weight and renal function.","Skipping two-identifier verification or scanning the wrong side when the list is busy."]},career:[{vi:"Kỹ thuật viên chẩn đoán hình ảnh",en:"Medical imaging technologist"},{vi:"Kỹ thuật viên chuyên sâu CT, MRI",en:"Senior CT and MRI technologist"},{vi:"Kỹ thuật viên trưởng khoa Chẩn đoán hình ảnh",en:"Chief radiologic technologist"},{vi:"Quản lý chất lượng và an toàn bức xạ khoa",en:"Imaging quality and radiation safety manager"}],glossary:[{term:"CTPA",vi:"Chụp CT động mạch phổi có tiêm thuốc cản quang, dùng để chẩn đoán thuyên tắc phổi.",en:"CT pulmonary angiography with contrast, used to diagnose pulmonary embolism."},{term:"CTDIvol",vi:"Chỉ số liều CT thể tích, phản ánh cường độ bức xạ trên mỗi lát cắt của một lần quét.",en:"Volume CT dose index, reflecting radiation output per slice for a scan."},{term:"DLP",vi:"Tích liều theo chiều dài, bằng CTDIvol nhân chiều dài vùng quét, đơn vị mGy.cm.",en:"Dose length product, equal to CTDIvol times scan length, in mGy.cm."},{term:"ALARA",vi:"Nguyên tắc giữ liều bức xạ thấp nhất có thể hợp lý mà vẫn đạt mục đích chẩn đoán.",en:"Principle of keeping radiation dose as low as reasonably achievable while meeting the diagnostic goal."},{term:"Bolus tracking",vi:"Kỹ thuật theo dõi đậm độ thuốc tại vùng quan tâm để tự động bắt đầu quét đúng pha.",en:"Technique that monitors contrast density in a region of interest to start the scan at the right phase."}],quiz:[{q:{vi:"Người bệnh 60 kg, eGFR 52. Theo SOP mô phỏng 1,0 mL/kg, tối đa 80 mL, giảm 20% khi eGFR 30-59, thể tích thuốc cản quang là bao nhiêu?",en:"A 60 kg patient has eGFR 52. Under the training SOP of 1.0 mL/kg, max 80 mL, minus 20% for eGFR 30-59, what is the contrast volume?"},options:{vi:["60 mL","80 mL","48 mL","52 mL"],en:["60 mL","80 mL","48 mL","52 mL"]},answer:2,explain:{vi:"60 kg x 1,0 mL/kg = 60 mL, dưới mức trần 80 mL; giảm 20% vì eGFR 52 nên còn 48 mL.",en:"60 kg x 1.0 mL/kg = 60 mL, below the 80 mL cap; minus 20% for eGFR 52 gives 48 mL."}},{q:{vi:"Người bệnh chuẩn bị chụp MRI khai có máy tạo nhịp nhưng không rõ loại. Bạn làm gì?",en:"A patient about to have MRI reports a pacemaker of unknown type. What do you do?"},options:{vi:["Dừng lại, xác minh loại thiết bị và báo bác sĩ trước khi cho vào phòng máy","Cho chụp nhanh với chuỗi xung ngắn","Đề nghị người bệnh tự tắt máy tạo nhịp","Chụp vì đa số máy tạo nhịp mới đều an toàn"],en:["Stop, verify the device type and inform the physician before entering the scanner room","Scan quickly with short sequences","Ask the patient to switch off the pacemaker","Scan because most new pacemakers are safe"]},answer:0,explain:{vi:"Thiết bị cấy ghép chưa xác định trạng thái MR phải được coi là không an toàn cho đến khi có xác minh và quyết định của bác sĩ.",en:"An implant of unknown MR status must be treated as unsafe until it is verified and a physician decides."}},{q:{vi:"Nguyên tắc ALARA trong chẩn đoán hình ảnh có nghĩa là gì?",en:"What does the ALARA principle mean in medical imaging?"},options:{vi:["Luôn dùng liều cao để ảnh đẹp nhất","Không bao giờ chụp lại","Chỉ áp dụng cho trẻ em","Giữ liều thấp nhất có thể hợp lý mà vẫn đủ chất lượng chẩn đoán"],en:["Always use high dose for the best image","Never repeat a scan","Apply it only to children","Keep dose as low as reasonably achievable while keeping diagnostic quality"]},answer:3,explain:{vi:"ALARA là tối ưu hóa: đủ chất lượng để chẩn đoán với liều thấp nhất hợp lý, áp dụng cho mọi người bệnh.",en:"ALARA means optimisation: enough diagnostic quality with the lowest reasonable dose, for every patient."}},{q:{vi:"Hàng chờ dài, trưởng ca bảo bỏ bước hỏi lại họ tên và ngày sinh để chụp nhanh hơn. Bạn chọn cách nào?",en:"The queue is long and the shift lead says to skip asking name and date of birth to go faster. What do you choose?"},options:{vi:["Bỏ bước xác minh cho kịp","Vẫn xác minh hai thông tin nhận dạng và báo trưởng ca về rủi ro nhầm người bệnh","Chỉ xác minh với người bệnh lớn tuổi","Nhờ người nhà tự đọc tên"],en:["Skip verification to save time","Keep two-identifier verification and tell the shift lead about the wrong-patient risk","Verify only elderly patients","Let relatives read the name out"]},answer:1,explain:{vi:"Xác minh hai thông tin nhận dạng là hàng rào chống nhầm người bệnh, không được bỏ qua vì áp lực thời gian.",en:"Two-identifier verification is the barrier against wrong-patient events and cannot be skipped under time pressure."}}]}},"KK-721":{scenario:{company:"Bệnh viện Đa khoa Phú Lâm Viên",supervisor:{name:"Trịnh Văn Lâm",role:{vi:"Trưởng phòng Vật tư - Thiết bị y tế",en:"Head of Medical Equipment Department"}},ref_code:"WO-6143",title:{vi:"Đúng phân loại. Đúng phép thử. Đúng tem kiểm tra.",en:"Right class. Right test. Right inspection tag."},brief:{vi:"Đây là tình huống đào tạo. Bạn hoàn tất phiếu bảo trì WO-6143 cho bơm truyền dịch thể tích IP-27 của khoa Hồi sức tích cực. Phép thử lưu lượng cài 25 mL/h trong 120 phút cho thể tích tích lũy 23.6 mL ở phút 60 và 48.1 mL ở phút 120. Dùng terminal để chẩn đoán, sửa loại bộ phận ứng dụng và lưu lượng trung bình trên phiếu, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are closing work order WO-6143 for volumetric infusion pump IP-27 in the intensive care unit. The flow test at 25 mL/h over 120 minutes gave cumulative volumes of 23.6 mL at minute 60 and 48.1 mL at minute 120. Use the terminal to diagnose, correct the applied part type and the mean flow on the work order, then write an evidence-based report."},reference_title:{vi:"Hồ sơ kỹ thuật & biên bản thử đã duyệt · WO-6143",en:"Approved technical file & test record · WO-6143"},fields:[{id:"APPLIED_PART",label:{vi:"Loại bộ phận ứng dụng",en:"Applied part type"},initial:"Type BF",expected:"Type CF",choices:["Type B","Type BF","Type CF"],reference:"Nhãn thiết bị và hồ sơ kỹ thuật",hint:{vi:"Đọc ký hiệu trên nhãn: hình người, hình người trong ô vuông và hình trái tim trong ô vuông là ba loại khác nhau.",en:"Read the label symbol: a figure, a figure in a square and a heart in a square are three different types."}},{id:"FLOW_H2",label:{vi:"Lưu lượng trung bình giờ thứ 2 (mL/h)",en:"Second-hour mean flow (mL/h)"},initial:"24.05",expected:"24.5",reference:"Biên bản thử lưu lượng",ref_value:{vi:"Cài 25 mL/h; tích lũy 23.6 mL tại phút 60 và 48.1 mL tại phút 120",en:"Set 25 mL/h; cumulative 23.6 mL at minute 60 and 48.1 mL at minute 120"},hint:{vi:"Loại bỏ giờ đầu là giai đoạn khởi động, chỉ tính thể tích trong cửa sổ phân tích.",en:"Exclude the first hour start-up period and use only the volume in the analysis window."}}],sop32:{vi:"Lưu lượng trung bình = (thể tích tích lũy phút 120 - thể tích tích lũy phút 60) / 1 giờ; sai số = (lưu lượng đo - lưu lượng cài) / lưu lượng cài, dung sai ±5% (mô phỏng).",en:"Mean flow = (cumulative volume at minute 120 - cumulative volume at minute 60) / 1 hour; error = (measured - set) / set, tolerance ±5% (training value)."},context:{label:"CMMS / WO-6143",metrics:[{label:{vi:"Lưu lượng cài",en:"Set flow"},value:"25 mL/h"},{label:{vi:"Thời gian thử",en:"Test duration"},value:"120 min"},{label:{vi:"Dòng rò một lỗi",en:"Single fault leakage"},value:"62 µA"}]},terminal:{system:"biomed-cmms",settable:["APPLIED_PART","FLOW_H2"],commands:[{cmd:"status",out:{vi:"WO-6143: bơm IP-27, khoa Hồi sức tích cực, bảo trì định kỳ 12 tháng. An toàn điện đã chạy với cấu hình Type BF; thử lưu lượng hoàn tất 120 phút.",en:"WO-6143: pump IP-27, intensive care unit, 12-month preventive maintenance. Electrical safety ran with the Type BF profile; flow test completed over 120 minutes."}},{cmd:"cat nameplate.txt",out:{vi:"Nhãn máy: ký hiệu trái tim trong ô vuông, hai bên có hình bản cực (chống sốc tim); Class I; 220-240 V 50/60 Hz.",en:"Label: heart-in-a-square symbol with paddles on both sides (defibrillation-proof); Class I; 220-240 V 50/60 Hz."}},{cmd:"esa report",out:{vi:"Dòng rò bệnh nhân: bình thường 7 µA; một lỗi (hở trung tính) 62 µA. Giới hạn đang nạp 100/500 µA (Type BF). Kết luận tự động: PASS.",en:"Patient leakage: normal condition 7 µA; single fault (open neutral) 62 µA. Loaded limits 100/500 µA (Type BF). Automatic verdict: PASS."}},{cmd:"flowtest log",out:{vi:"Cài 25 mL/h. Thể tích tích lũy: phút 30 = 11.4 mL; phút 60 = 23.6 mL; phút 90 = 35.9 mL; phút 120 = 48.1 mL.",en:"Set 25 mL/h. Cumulative volume: minute 30 = 11.4 mL; minute 60 = 23.6 mL; minute 90 = 35.9 mL; minute 120 = 48.1 mL."}},{cmd:"cat limits.txt",out:{vi:"Giới hạn dòng rò bệnh nhân (AC): Type B và BF 100 µA bình thường, 500 µA một lỗi; Type CF 10 µA bình thường, 50 µA một lỗi.",en:"Patient leakage limits (AC): Type B and BF 100 µA normal, 500 µA single fault; Type CF 10 µA normal, 50 µA single fault."}}]},crisis:{vi:"Trưởng khoa Hồi sức nhắn: “Khoa đang thiếu bơm, cứ dán tem Đạt cho IP-27 theo kết luận PASS của máy đo, an toàn điện đo lại sau. Có gì tôi chịu trách nhiệm.”",en:"The ICU head messages you: “We are short of pumps. Put a Pass tag on IP-27 based on the analyser's PASS and redo electrical safety later. I take responsibility.”"},options:{safe:{vi:"Không dán tem Đạt; gắn nhãn Không sử dụng, đo lại với cấu hình đúng theo nhãn máy, báo trưởng phòng Vật tư - Thiết bị y tế và điều chuyển bơm dự phòng cho khoa.",en:"Do not apply a Pass tag; label it Do Not Use, retest with the profile matching the label, inform the equipment manager and send a backup pump to the unit."},shortcut:{vi:"Dán tem Đạt theo kết luận tự động của máy đo cho kịp, đo lại sau khi khoa trả máy.",en:"Apply the Pass tag from the automatic verdict now and retest when the unit returns the pump."},wait:{vi:"Để máy trên bàn sửa chữa, không ghi kết luận và chờ khoa tự gọi lại.",en:"Leave the pump on the bench with no verdict and wait for the unit to call again."}},questions:{vi:["Vì sao kết luận PASS tự động của máy phân tích an toàn điện không còn giá trị? Dữ liệu nào chứng minh?","Trình bày cách tính lưu lượng giờ thứ 2 và cách xử lý thiết bị không đạt khi khoa lâm sàng đang thiếu máy."],en:["Why is the analyser's automatic PASS verdict no longer valid? Which data proves it?","Explain how you calculated the second-hour flow and how you handle a failed device when the ward is short of equipment."]},hints:{vi:["Chạy cat nameplate.txt và so ký hiệu trên nhãn với cấu hình giới hạn mà máy đo đang nạp.","Theo SOP mục 3.2: chỉ dùng thể tích trong cửa sổ từ phút 60 đến phút 120.","Đọc lại SOP mục 4.2: thiết bị chưa đạt không được dán tem Đạt, phải cách ly và báo cáo."],en:["Run cat nameplate.txt and compare the label symbol with the limit profile loaded in the analyser.","Per SOP 3.2: use only the volume in the window from minute 60 to minute 120.","Re-read SOP 4.2: a device that has not passed must not get a Pass tag; quarantine and report it."]}},learning:{summary:{vi:"Kỹ sư thiết bị y tế quản lý vòng đời trang thiết bị trong bệnh viện: tiếp nhận, nghiệm thu, lắp đặt, bảo trì phòng ngừa, sửa chữa, hiệu chuẩn, kiểm tra an toàn điện và thanh lý. Mục tiêu là thiết bị luôn sẵn sàng, chính xác và an toàn cho người bệnh, người vận hành. Nghề đòi hỏi kiến thức điện tử y sinh, đọc tiêu chuẩn kỹ thuật, dùng thành thạo máy phân tích chuyên dụng và bản lĩnh từ chối đưa thiết bị chưa đạt vào sử dụng.",en:"A biomedical equipment engineer manages the life cycle of hospital equipment: receiving, acceptance testing, installation, preventive maintenance, repair, calibration, electrical safety testing and disposal. The goal is equipment that is always available, accurate and safe for patients and operators. The role needs biomedical electronics knowledge, the ability to read technical standards, skill with specialised analysers and the integrity to keep failed devices out of service."},responsibilities:{vi:["Lập và thực hiện kế hoạch bảo trì phòng ngừa theo mức rủi ro và khuyến cáo nhà sản xuất.","Kiểm tra an toàn điện, hiệu năng thiết bị bằng máy phân tích chuyên dụng sau bảo trì và sửa chữa.","Chẩn đoán, sửa chữa sự cố, quản lý phụ tùng và phối hợp với nhà cung cấp dịch vụ.","Nghiệm thu thiết bị mới, đào tạo người sử dụng và lưu hồ sơ kỹ thuật trên CMMS.","Theo dõi cảnh báo an toàn, thông báo thu hồi và báo cáo sự cố liên quan đến thiết bị."],en:["Plan and perform preventive maintenance by risk level and manufacturer recommendations.","Test electrical safety and performance with specialised analysers after maintenance and repair.","Diagnose and repair faults, manage spare parts and coordinate with service providers.","Run acceptance tests for new equipment, train users and keep technical records in the CMMS.","Track safety alerts and recalls and report equipment-related incidents."]},competencies:[{name:{vi:"An toàn điện y tế",en:"Medical electrical safety"},desc:{vi:"Xác định cấp bảo vệ, loại bộ phận ứng dụng và áp đúng giới hạn dòng rò khi thử nghiệm.",en:"Identify protection class and applied part type and apply the correct leakage limits."}},{name:{vi:"Kiểm tra hiệu năng",en:"Performance verification"},desc:{vi:"Đo lưu lượng, năng lượng, áp suất, thông số sinh lý và so với dung sai nhà sản xuất.",en:"Measure flow, energy, pressure and physiological parameters against manufacturer tolerances."}},{name:{vi:"Chẩn đoán sự cố",en:"Fault diagnosis"},desc:{vi:"Đọc nhật ký lỗi, sơ đồ mạch và khoanh vùng nguyên nhân gốc trước khi thay linh kiện.",en:"Read error logs and schematics and isolate the root cause before replacing parts."}},{name:{vi:"Quản lý rủi ro thiết bị",en:"Equipment risk management"},desc:{vi:"Ưu tiên bảo trì theo chức năng, rủi ro và lịch sử sự cố; cách ly thiết bị không đạt.",en:"Prioritise maintenance by function, risk and incident history; quarantine failed devices."}},{name:{vi:"Liêm chính kỹ thuật",en:"Technical integrity"},desc:{vi:"Chỉ dán tem khi đủ bằng chứng thử nghiệm, ghi hồ sơ trung thực và báo cáo áp lực sai quy trình.",en:"Tag equipment only with full test evidence, keep honest records and escalate improper pressure."}}],knowledge:{vi:["Nghị định 98/2021/NĐ-CP về quản lý trang thiết bị y tế, phân loại theo mức rủi ro A, B, C, D.","IEC 60601-1 về an toàn chung thiết bị điện y tế và IEC 62353 về thử nghiệm định kỳ, sau sửa chữa.","IEC 60601-2-24 về yêu cầu riêng cho bơm truyền dịch và bộ điều khiển truyền dịch.","ISO 14971 về quản lý rủi ro và ISO 13485 về hệ thống quản lý chất lượng trang thiết bị y tế.","Phương pháp bảo trì dựa trên rủi ro và chỉ số sẵn sàng, thời gian ngừng máy, thời gian sửa chữa trung bình."],en:["Decree 98/2021/ND-CP on medical device management, with risk classes A, B, C and D.","IEC 60601-1 on general safety of medical electrical equipment and IEC 62353 on recurrent and post-repair testing.","IEC 60601-2-24 on particular requirements for infusion pumps and controllers.","ISO 14971 on risk management and ISO 13485 on quality management systems for medical devices.","Risk-based maintenance and the metrics of availability, downtime and mean time to repair."]},tools:["Máy phân tích an toàn điện","Máy phân tích bơm truyền dịch","Máy phân tích máy phá rung tim","Bộ mô phỏng thông số người bệnh","Phần mềm CMMS quản lý thiết bị"],kpis:{vi:["Tỷ lệ bảo trì phòng ngừa hoàn thành đúng hạn (mục tiêu từ 95%).","Tỷ lệ sẵn sàng của thiết bị hỗ trợ sự sống.","Thời gian sửa chữa trung bình mỗi sự cố.","Số sự cố người bệnh liên quan đến thiết bị do lỗi bảo trì (mục tiêu bằng 0)."],en:["Preventive maintenance completed on time (target 95% or more).","Availability of life-support equipment.","Mean time to repair per fault.","Patient incidents caused by maintenance errors (target zero)."]},day:[{time:"07:30",vi:"Xem lệnh công việc trên CMMS, ưu tiên thiết bị hỗ trợ sự sống đang chờ sửa.",en:"Review CMMS work orders and prioritise life-support devices awaiting repair."},{time:"09:00",vi:"Bảo trì định kỳ bơm truyền dịch, chạy thử an toàn điện và thử lưu lượng.",en:"Service infusion pumps and run electrical safety and flow tests."},{time:"11:00",vi:"Xử lý cuộc gọi sự cố tại khoa Cấp cứu, khoanh vùng lỗi máy theo dõi người bệnh.",en:"Respond to a fault call in the emergency department and isolate a patient monitor fault."},{time:"14:00",vi:"Nghiệm thu thiết bị mới với nhà cung cấp và hướng dẫn điều dưỡng sử dụng.",en:"Run acceptance testing with the vendor and train nurses on the new device."},{time:"16:30",vi:"Cập nhật hồ sơ, dán tem kiểm tra cho thiết bị đạt và báo cáo thiết bị cách ly.",en:"Update records, tag passed equipment and report quarantined devices."}],mistakes:{vi:["Nạp sai cấu hình phân loại trên máy phân tích và tin vào kết luận tự động.","Tính lưu lượng trên toàn bộ thời gian thử, gồm cả giai đoạn khởi động.","Dán tem Đạt hoặc trả máy cho khoa trước khi hoàn tất đủ các phép thử."],en:["Loading the wrong classification profile on the analyser and trusting the automatic verdict.","Computing flow over the whole test including the start-up period.","Tagging a device as passed or returning it before all tests are complete."]},career:[{vi:"Kỹ thuật viên thiết bị y tế",en:"Medical equipment technician"},{vi:"Kỹ sư thiết bị y tế",en:"Biomedical equipment engineer"},{vi:"Kỹ sư chính, phụ trách nhóm thiết bị chuyên sâu",en:"Senior engineer for specialised equipment"},{vi:"Trưởng phòng Vật tư - Thiết bị y tế",en:"Head of medical equipment management"}],glossary:[{term:"Applied part",vi:"Bộ phận của thiết bị tiếp xúc trực tiếp với người bệnh khi sử dụng bình thường.",en:"Part of the equipment that contacts the patient in normal use."},{term:"Type CF",vi:"Bộ phận ứng dụng có mức bảo vệ cao nhất, dùng được khi có thể tiếp xúc trực tiếp với tim.",en:"Applied part with the highest protection level, suitable for possible direct cardiac contact."},{term:"Leakage current",vi:"Dòng điện không mong muốn chạy qua người bệnh, người vận hành hoặc vỏ máy.",en:"Unwanted current flowing through the patient, the operator or the enclosure."},{term:"Preventive maintenance",vi:"Bảo trì phòng ngừa theo lịch để phát hiện suy giảm trước khi gây hỏng hóc.",en:"Scheduled maintenance that detects degradation before it causes failure."},{term:"CMMS",vi:"Phần mềm quản lý bảo trì: danh mục thiết bị, lệnh công việc, lịch sử và phụ tùng.",en:"Maintenance management software for asset lists, work orders, history and spare parts."}],quiz:[{q:{vi:"Theo IEC 60601-1, giới hạn dòng rò bệnh nhân (AC) trong điều kiện một lỗi của bộ phận ứng dụng Type CF là bao nhiêu?",en:"Under IEC 60601-1, what is the AC patient leakage limit in single fault condition for a Type CF applied part?"},options:{vi:["500 µA","50 µA","100 µA","10 µA"],en:["500 µA","50 µA","100 µA","10 µA"]},answer:1,explain:{vi:"Type CF: 10 µA ở điều kiện bình thường và 50 µA ở điều kiện một lỗi; Type B và BF là 100 và 500 µA.",en:"Type CF: 10 µA in normal condition and 50 µA in single fault; Type B and BF are 100 and 500 µA."}},{q:{vi:"Bơm cài 50 mL/h, thể tích tích lũy phút 60 là 49.0 mL và phút 120 là 97.5 mL. Sai số lưu lượng giờ thứ 2 là bao nhiêu?",en:"A pump set at 50 mL/h shows 49.0 mL at minute 60 and 97.5 mL at minute 120. What is the second-hour flow error?"},options:{vi:["-2.5%","+1.0%","-1.0%","-3.0%"],en:["-2.5%","+1.0%","-1.0%","-3.0%"]},answer:3,explain:{vi:"Giờ thứ 2: 97.5 - 49.0 = 48.5 mL/h; sai số (48.5 - 50) / 50 = -3.0%.",en:"Second hour: 97.5 - 49.0 = 48.5 mL/h; error (48.5 - 50) / 50 = -3.0%."}},{q:{vi:"Khoa lâm sàng thiếu máy và yêu cầu dán tem Đạt trước khi bạn hoàn tất phép thử. Bạn làm gì?",en:"A ward short of devices asks you to tag a pump as passed before testing is complete. What do you do?"},options:{vi:["Giữ máy cách ly, báo cấp trên và điều chuyển thiết bị dự phòng","Dán tem rồi thử lại sau","Cho mượn máy không dán tem","Đề nghị khoa tự kiểm tra"],en:["Keep it quarantined, escalate and provide a backup device","Tag it now and retest later","Lend it without a tag","Ask the ward to test it themselves"]},answer:0,explain:{vi:"Tem Đạt là cam kết an toàn; thiết bị chưa đủ bằng chứng phải cách ly, báo cáo và thay bằng thiết bị dự phòng.",en:"A Pass tag is a safety commitment; a device without full evidence must be quarantined, reported and replaced by a backup."}},{q:{vi:"Theo Nghị định 98/2021/NĐ-CP, trang thiết bị y tế được phân loại theo mức độ rủi ro như thế nào?",en:"How does Decree 98/2021/ND-CP classify medical devices by risk?"},options:{vi:["Hai loại: thường và đặc biệt","Ba loại: I, II, III","Bốn loại: A, B, C, D","Năm nhóm theo chuyên khoa"],en:["Two types: ordinary and special","Three classes: I, II, III","Four classes: A, B, C, D","Five groups by specialty"]},answer:2,explain:{vi:"Nghị định 98/2021/NĐ-CP phân trang thiết bị y tế thành loại A, B, C, D, trong đó A có mức rủi ro thấp nhất.",en:"Decree 98/2021/ND-CP sorts medical devices into classes A, B, C and D, with A the lowest risk."}}]}},"KK-722":{scenario:{company:"Bệnh viện Đa khoa Cẩm Giang Xanh",supervisor:{name:"Hà Thị Mai Phương",role:{vi:"Trưởng phòng Kế hoạch tổng hợp",en:"Head of General Planning Department"}},ref_code:"BM-3307",title:{vi:"Đúng phòng cách ly. Đúng công suất giường.",en:"Right isolation room. Right bed occupancy."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát bảng điều phối giường BM-3307 của khoa Nội tổng hợp. Người bệnh mới nhập viện (hư cấu) nghi lao phổi, ho kéo dài, xét nghiệm AFB đang chờ kết quả. Báo cáo tháng 6 (30 ngày): khoa có 40 giường kế hoạch, kê thêm 2 giường tạm, tổng 1092 ngày điều trị nội trú. Sửa loại phòng ngừa cách ly và công suất sử dụng giường, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing bed management board BM-3307 for the general internal medicine ward. A newly admitted (fictional) patient has suspected pulmonary tuberculosis with a prolonged cough, AFB test pending. June report (30 days): 40 planned beds, 2 temporary extra beds, 1092 inpatient days in total. Correct the isolation precaution type and the bed occupancy rate, then write an evidence-based report."},reference_title:{vi:"Quy trình điều phối giường & kiểm soát nhiễm khuẩn · BM-3307",en:"Bed management & infection control procedure · BM-3307"},fields:[{id:"ISOLATION",label:{vi:"Loại phòng ngừa cách ly",en:"Isolation precaution type"},initial:"Droplet",expected:"Airborne",choices:["Contact","Droplet","Airborne"],reference:"Bảng phân loại cách ly theo đường lây",hint:{vi:"Vi khuẩn lao lây qua hạt nhân giọt bắn rất nhỏ lơ lửng lâu trong không khí, cần phòng áp lực âm.",en:"TB spreads through tiny droplet nuclei that stay suspended in the air and needs a negative-pressure room."}},{id:"BED_OCC",label:{vi:"Công suất sử dụng giường (%)",en:"Bed occupancy rate (%)"},initial:"86.7",expected:"91",reference:"Báo cáo hoạt động khoa tháng 6",ref_value:{vi:"1092 ngày điều trị; 40 giường kế hoạch; 2 giường kê thêm; kỳ 30 ngày",en:"1092 inpatient days; 40 planned beds; 2 extra beds; 30-day period"},hint:{vi:"Mẫu số dùng số giường kế hoạch được giao, không cộng giường kê tạm.",en:"The denominator uses the assigned planned beds, not the temporary extra beds."}}],sop32:{vi:"Công suất sử dụng giường (%) = tổng ngày điều trị nội trú / (số giường kế hoạch x số ngày trong kỳ) x 100; giường kê thêm không đưa vào mẫu số (quy ước mô phỏng).",en:"Bed occupancy (%) = total inpatient days / (planned beds x days in period) x 100; temporary extra beds are excluded from the denominator (training convention)."},context:{label:"HIS / BM-3307",metrics:[{label:{vi:"Giường kế hoạch",en:"Planned beds"},value:"40"},{label:{vi:"Ngày điều trị tháng 6",en:"June inpatient days"},value:"1092"},{label:{vi:"Phòng áp lực âm trống",en:"Free negative-pressure room"},value:"1 (A12)"}]},crisis:{vi:"Phó giám đốc nhắn: “Phòng áp lực âm A12 đang giữ cho người nhà một lãnh đạo nằm theo yêu cầu. Xếp người bệnh nghi lao vào phòng 2 giường, cho đeo khẩu trang là được, đừng làm to chuyện.”",en:"The deputy director messages you: “Negative-pressure room A12 is reserved for a VIP's relative on request. Put the suspected TB patient in a two-bed room with a mask and don't make a fuss.”"},options:{safe:{vi:"Không xếp vào phòng thường; báo ngay khoa Kiểm soát nhiễm khuẩn và trực lãnh đạo, dùng phòng A12 theo chỉ định lâm sàng và đề xuất giường phù hợp khác cho người bệnh theo yêu cầu.",en:"Do not use a regular room; alert infection control and the duty director, assign A12 by clinical need and propose another suitable bed for the on-request patient."},shortcut:{vi:"Xếp người bệnh nghi lao vào phòng 2 giường, phát khẩu trang và ghi chú theo dõi.",en:"Place the suspected TB patient in a two-bed room, hand out masks and note it for follow-up."},wait:{vi:"Để người bệnh chờ ở hành lang khoa Cấp cứu cho đến khi lãnh đạo tự quyết định.",en:"Leave the patient waiting in the emergency corridor until management decides."}},questions:{vi:["Vì sao bạn thay đổi loại phòng ngừa cách ly? Đặc điểm lây truyền nào chứng minh lựa chọn đó?","Trình bày cách tính công suất sử dụng giường và cách xử lý khi phòng cách ly bị giữ cho mục đích không theo chỉ định chuyên môn."],en:["Why did you change the isolation precaution type? Which transmission feature supports your choice?","Explain how you calculated bed occupancy and how you handle an isolation room held for a non-clinical reason."]},hints:{vi:["Đặt chẩn đoán nghi ngờ cạnh bảng phân loại cách ly và xác định đường lây chính của bệnh.","Theo SOP mục 3.2: kiểm tra lại mẫu số, chỉ dùng giường kế hoạch nhân số ngày trong kỳ.","Đọc lại SOP mục 4.2: phòng cách ly được phân bổ theo chỉ định lâm sàng, mọi áp lực khác phải báo cáo."],en:["Put the suspected diagnosis next to the isolation table and identify the main transmission route.","Per SOP 3.2: check the denominator and use planned beds times days in the period.","Re-read SOP 4.2: isolation rooms are allocated by clinical need; any other pressure must be escalated."]}},learning:{summary:{vi:"Chuyên viên điều phối vận hành bệnh viện và phòng khám bảo đảm dòng người bệnh thông suốt: phân bổ giường, lập lịch khám và phòng mổ, phối hợp xét nghiệm, chẩn đoán hình ảnh, vận chuyển, vệ sinh và theo dõi chỉ số vận hành hằng ngày. Công việc giúp giảm thời gian chờ, dùng hiệu quả nguồn lực và giữ an toàn người bệnh. Nghề đòi hỏi tư duy dữ liệu, hiểu quy định kiểm soát nhiễm khuẩn và khả năng ra quyết định nhanh dưới áp lực.",en:"A hospital and clinic operations coordinator keeps patient flow moving: allocating beds, scheduling clinics and operating rooms, coordinating laboratory, imaging, transport and cleaning, and tracking daily operating metrics. The work reduces waiting times, uses resources efficiently and keeps patients safe. The role needs data thinking, knowledge of infection control rules and the ability to decide quickly under pressure."},responsibilities:{vi:["Điều phối giường cho nhập viện, chuyển khoa và ra viện theo mức ưu tiên lâm sàng.","Lập và điều chỉnh lịch phòng khám, phòng mổ, cân đối nhân lực theo dự báo lượt khám.","Theo dõi công suất giường, ngày điều trị trung bình, thời gian chờ và cảnh báo quá tải.","Phối hợp các bộ phận hỗ trợ: xét nghiệm, chẩn đoán hình ảnh, vận chuyển, vệ sinh, dinh dưỡng.","Kích hoạt kế hoạch ứng phó khi quá tải, sự cố hoặc tiếp nhận cấp cứu hàng loạt."],en:["Allocate beds for admissions, transfers and discharges by clinical priority.","Build and adjust clinic and operating room schedules and balance staff against visit forecasts.","Track bed occupancy, average length of stay and waiting times and flag overload.","Coordinate support services: laboratory, imaging, transport, cleaning and nutrition.","Activate response plans for overload, incidents or mass casualty events."]},competencies:[{name:{vi:"Quản lý dòng người bệnh",en:"Patient flow management"},desc:{vi:"Nhìn toàn bộ chuỗi từ cấp cứu đến ra viện, phát hiện điểm nghẽn và điều chỉnh kịp thời.",en:"See the whole chain from emergency to discharge, spot bottlenecks and adjust in time."}},{name:{vi:"Phân tích chỉ số vận hành",en:"Operational analytics"},desc:{vi:"Tính đúng công suất giường, ngày điều trị trung bình, thời gian chờ và giải thích xu hướng.",en:"Compute bed occupancy, length of stay and waiting times correctly and explain trends."}},{name:{vi:"Kiểm soát nhiễm khuẩn trong điều phối",en:"Infection control in placement"},desc:{vi:"Xếp giường theo đường lây: tiếp xúc, giọt bắn, không khí; ưu tiên phòng cách ly đúng chỉ định.",en:"Place patients by transmission route: contact, droplet, airborne; allocate isolation by indication."}},{name:{vi:"Phối hợp liên khoa",en:"Cross-department coordination"},desc:{vi:"Làm việc với bác sĩ, điều dưỡng, hậu cần bằng thông tin rõ ràng và cam kết thời gian.",en:"Work with doctors, nurses and logistics using clear information and time commitments."}},{name:{vi:"Liêm chính & bảo mật",en:"Integrity & confidentiality"},desc:{vi:"Phân bổ nguồn lực công bằng theo chuyên môn, bảo mật thông tin người bệnh và báo cáo áp lực sai.",en:"Allocate resources fairly by clinical need, protect patient data and escalate improper pressure."}}],knowledge:{vi:["Luật Khám bệnh, chữa bệnh số 15/2023/QH15: quyền người bệnh, bảo mật thông tin, tổ chức cơ sở khám chữa bệnh.","Bộ tiêu chí chất lượng bệnh viện Việt Nam ban hành theo Quyết định 6858/QĐ-BYT năm 2016.","Thông tư 16/2018/TT-BYT về kiểm soát nhiễm khuẩn trong cơ sở khám bệnh, chữa bệnh.","Phòng ngừa chuẩn và phòng ngừa dựa trên đường lây: tiếp xúc, giọt bắn, không khí.","Chỉ số vận hành: công suất sử dụng giường, ngày điều trị trung bình, thời gian chờ, tỷ lệ hủy hoãn mổ."],en:["Law on Medical Examination and Treatment No. 15/2023/QH15: patient rights, confidentiality, facility organisation.","Vietnam hospital quality criteria issued under Decision 6858/QD-BYT in 2016.","Circular 16/2018/TT-BYT on infection control in healthcare facilities.","Standard precautions and transmission-based precautions: contact, droplet and airborne.","Operating metrics: bed occupancy, average length of stay, waiting time and surgery cancellation rate."]},tools:["Hệ thống thông tin bệnh viện (HIS)","Bảng điều phối giường điện tử","Phần mềm lập lịch phòng khám, phòng mổ","Bảng điều khiển chỉ số vận hành","Bảng tính điện tử"],kpis:{vi:["Thời gian chờ nhập giường từ khoa Cấp cứu.","Công suất sử dụng giường trong vùng mục tiêu của bệnh viện.","Tỷ lệ người bệnh ra viện trước 12 giờ trưa.","Tỷ lệ hủy, hoãn mổ do lỗi điều phối (mục tiêu bằng 0)."],en:["Waiting time for a bed from the emergency department.","Bed occupancy within the hospital's target range.","Share of patients discharged before noon.","Surgery cancellations or delays caused by coordination errors (target zero)."]},day:[{time:"07:30",vi:"Dự giao ban, cập nhật giường trống, giường dự kiến ra viện và ca cấp cứu chờ nhập.",en:"Attend the morning huddle and update free beds, expected discharges and waiting admissions."},{time:"09:00",vi:"Điều phối chuyển khoa, xếp phòng cách ly theo đường lây cho ca mới.",en:"Coordinate transfers and assign isolation rooms by transmission route for new cases."},{time:"11:00",vi:"Theo dõi tiến độ ra viện, phối hợp vệ sinh buồng và vận chuyển người bệnh.",en:"Track discharges and coordinate room cleaning and patient transport."},{time:"14:00",vi:"Chốt lịch mổ ngày mai, kiểm tra giường hồi sức và nhân lực gây mê.",en:"Finalise tomorrow's surgery list and check recovery beds and anaesthesia staff."},{time:"16:30",vi:"Cập nhật bảng chỉ số, báo cáo điểm nghẽn và đề xuất cải tiến.",en:"Update the dashboard, report bottlenecks and propose improvements."}],mistakes:{vi:["Dùng số giường thực kê làm mẫu số khiến công suất giường bị báo thấp hơn thực tế.","Nhầm phòng ngừa giọt bắn với phòng ngừa qua không khí khi xếp người bệnh nghi lao, sởi.","Ưu tiên giường theo quan hệ thay vì theo mức độ cấp thiết lâm sàng."],en:["Using actual beds as the denominator so occupancy is reported lower than reality.","Confusing droplet and airborne precautions when placing suspected TB or measles patients.","Allocating beds by connections instead of clinical urgency."]},career:[{vi:"Nhân viên điều phối người bệnh",en:"Patient flow assistant"},{vi:"Chuyên viên điều phối vận hành bệnh viện",en:"Hospital operations coordinator"},{vi:"Trưởng nhóm điều phối giường và phòng mổ",en:"Bed and theatre coordination lead"},{vi:"Trưởng phòng Kế hoạch tổng hợp hoặc Giám đốc vận hành",en:"Head of planning or chief operating officer"}],glossary:[{term:"Bed occupancy",vi:"Công suất sử dụng giường: tỷ lệ ngày điều trị thực tế so với khả năng giường kế hoạch trong kỳ.",en:"Ratio of actual inpatient days to planned bed capacity over a period."},{term:"ALOS",vi:"Ngày điều trị trung bình: tổng ngày điều trị chia cho số người bệnh ra viện trong kỳ.",en:"Average length of stay: total inpatient days divided by discharges in the period."},{term:"Airborne precautions",vi:"Phòng ngừa lây qua không khí: phòng áp lực âm, khẩu trang N95, hạn chế di chuyển người bệnh.",en:"Precautions for airborne spread: negative-pressure room, N95 respirators, limited patient movement."},{term:"Patient flow",vi:"Dòng di chuyển của người bệnh qua các khâu khám, chẩn đoán, điều trị và ra viện.",en:"Movement of patients through assessment, diagnostics, treatment and discharge."},{term:"Surge plan",vi:"Kế hoạch tăng công suất khẩn cấp khi lượng người bệnh vượt khả năng thông thường.",en:"Emergency plan to expand capacity when patient volume exceeds normal limits."}],quiz:[{q:{vi:"Khoa có 30 giường kế hoạch, tháng có 31 ngày, tổng 837 ngày điều trị nội trú. Công suất sử dụng giường là bao nhiêu?",en:"A ward has 30 planned beds, a 31-day month and 837 inpatient days. What is the bed occupancy?"},options:{vi:["93%","84%","87%","90%"],en:["93%","84%","87%","90%"]},answer:3,explain:{vi:"Công suất = 837 / (30 giường x 31 ngày) x 100 = 837 / 930 x 100 = 90%.",en:"837 / (30 x 31) x 100 = 837 / 930 x 100 = 90%."}},{q:{vi:"Người bệnh nghi lao phổi cần áp dụng loại phòng ngừa nào khi xếp giường?",en:"Which precaution applies when placing a patient with suspected pulmonary TB?"},options:{vi:["Phòng ngừa tiếp xúc","Phòng ngừa qua không khí","Phòng ngừa giọt bắn","Chỉ cần phòng ngừa chuẩn"],en:["Contact precautions","Airborne precautions","Droplet precautions","Standard precautions only"]},answer:1,explain:{vi:"Lao phổi lây qua hạt nhân giọt bắn lơ lửng trong không khí nên cần phòng áp lực âm và khẩu trang N95.",en:"Pulmonary TB spreads by airborne droplet nuclei, so it needs a negative-pressure room and N95 respirators."}},{q:{vi:"Một người quen nhờ bạn tra cứu chẩn đoán của người bệnh khác trên HIS. Bạn làm gì?",en:"An acquaintance asks you to look up another patient's diagnosis in the HIS. What do you do?"},options:{vi:["Từ chối và giải thích thông tin người bệnh chỉ được cung cấp theo quy định","Tra cứu nhưng chỉ nói miệng","Chụp màn hình gửi riêng","Nhờ đồng nghiệp tra hộ"],en:["Refuse and explain patient data is only released per regulations","Look it up and only tell them verbally","Send a private screenshot","Ask a colleague to look it up"]},answer:0,explain:{vi:"Thông tin người bệnh được pháp luật bảo vệ; chỉ truy cập khi có nhiệm vụ và cung cấp theo đúng quy định.",en:"Patient information is protected by law; access it only for duty and release it only as regulations allow."}},{q:{vi:"Ngày điều trị trung bình (ALOS) được tính như thế nào?",en:"How is average length of stay (ALOS) calculated?"},options:{vi:["Số giường chia số người bệnh","Tổng ngày điều trị chia số giường","Tổng ngày điều trị chia số người bệnh ra viện","Số người bệnh nhập chia số ngày"],en:["Beds divided by patients","Inpatient days divided by beds","Inpatient days divided by discharges","Admissions divided by days"]},answer:2,explain:{vi:"ALOS bằng tổng số ngày điều trị nội trú của người bệnh ra viện chia cho số người bệnh ra viện trong kỳ.",en:"ALOS equals total inpatient days of discharged patients divided by the number of discharges in the period."}}]}}}),n.JobLabContentClusters=(n.JobLabContentClusters||[]).concat(9)})(window.KKR);
